  /**
 * Enterprise Project CRM - Central Reactive DataStore
 * Handles LocalStorage persistence, state reactivity, CRUD APIs,
 * automation triggers, time tracking, CSV/JSON export, and global search.
 */



const STORAGE_KEY = 'APEXFLOW_CRM_DB_V1';

class DataStore {
  constructor() {
    this.subscribers = new Map();
    this.activeTimer = null;
    this.timerInterval = null;
    this.init();
  }

  init() {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        this.data = JSON.parse(stored);
        // Ensure all required collections exist
        ['settings', 'team', 'accounts', 'contacts', 'deals', 'projects', 'tasks', 'invoices', 'tickets', 'automations', 'activities'].forEach(key => {
          if (!this.data[key]) {
            this.data[key] = JSON.parse(JSON.stringify(INITIAL_MOCK_DATA[key] || []));
          }
        });
      } else {
        this.resetToDefaultData(false);
      }
    } catch (e) {
      console.error('Failed to load CRM data from localStorage, resetting to defaults:', e);
      this.resetToDefaultData(false);
    }

    // Load active timer if any
    try {
      const storedTimer = localStorage.getItem(STORAGE_KEY + '_TIMER');
      if (storedTimer) {
        this.activeTimer = JSON.parse(storedTimer);
        if (this.activeTimer && this.activeTimer.isRunning) {
          this.resumeTimer();
        }
      }
    } catch (e) {
      console.warn('Failed to load timer state:', e);
    }
  }

  save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.data));
    } catch (e) {
      console.error('Failed to save CRM state to localStorage:', e);
    }
  }

  // --- PUB/SUB EVENT SYSTEM ---
  subscribe(event, callback) {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, new Set());
    }
    this.subscribers.get(event).add(callback);
    return () => {
      this.subscribers.get(event).delete(callback);
    };
  }

  notify(event, payload = {}) {
    if (this.subscribers.has(event)) {
      this.subscribers.get(event).forEach(cb => {
        try {
          cb(payload);
        } catch (err) {
          console.error(`Error in subscriber for event ${event}:`, err);
        }
      });
    }
    // Also notify global wildcard
    if (this.subscribers.has('*')) {
      this.subscribers.get('*').forEach(cb => {
        try {
          cb({ event, payload });
        } catch (err) {
          console.error('Error in wildcard subscriber:', err);
        }
      });
    }
  }

  // --- SETTINGS ---
  getSettings() {
    return { ...this.data.settings };
  }

  saveSettings(newSettings) {
    this.data.settings = { ...this.data.settings, ...newSettings };
    this.save();
    this.notify('settings:updated', this.data.settings);
    this.logActivity({
      type: 'settings',
      action: 'Updated Settings',
      title: 'Company and system preferences updated',
      details: `Theme: ${this.data.settings.theme}, Currency: ${this.data.settings.defaultCurrency}`,
      icon: 'settings',
      color: '#6366f1'
    });
    return this.data.settings;
  }

  // --- ACCOUNTS (CLIENTS) ---
  getAccounts() {
    return [...this.data.accounts];
  }

  getAccountById(id) {
    return this.data.accounts.find(a => a.id === id) || null;
  }

  saveAccount(account) {
    let isNew = false;
    if (!account.id) {
      account.id = 'acc-' + String(Date.now()).slice(-6);
      account.createdAt = new Date().toISOString();
      account.logoBg = account.logoBg || this.getRandomColor();
      this.data.accounts.unshift(account);
      isNew = true;
    } else {
      const idx = this.data.accounts.findIndex(a => a.id === account.id);
      if (idx !== -1) {
        this.data.accounts[idx] = { ...this.data.accounts[idx], ...account };
      } else {
        this.data.accounts.unshift(account);
        isNew = true;
      }
    }
    this.save();
    this.notify('accounts:updated', account);
    this.logActivity({
      type: 'account',
      action: isNew ? 'Created Account' : 'Updated Account',
      title: `${isNew ? 'Added' : 'Updated'} company "${account.name}"`,
      details: `Tier: ${account.tier}, Health: ${account.healthScore || 85}%`,
      icon: 'briefcase',
      color: '#10b981'
    });
    return account;
  }

  deleteAccount(id) {
    const acc = this.getAccountById(id);
    this.data.accounts = this.data.accounts.filter(a => a.id !== id);
    this.save();
    this.notify('accounts:updated', { id, deleted: true });
    if (acc) {
      this.logActivity({
        type: 'account',
        action: 'Deleted Account',
        title: `Removed company "${acc.name}"`,
        details: `Account ID: ${id}`,
        icon: 'trash-2',
        color: '#ef4444'
      });
    }
  }

  getAccount360(accountId) {
    const account = this.getAccountById(accountId);
    if (!account) return null;
    const contacts = this.data.contacts.filter(c => c.accountId === accountId);
    const deals = this.data.deals.filter(d => d.accountId === accountId);
    const projects = this.data.projects.filter(p => p.accountId === accountId);
    const invoices = this.data.invoices.filter(i => i.accountId === accountId);
    const tickets = this.data.tickets.filter(t => t.accountId === accountId);

    const totalDealValue = deals.reduce((sum, d) => sum + (Number(d.amount) || 0), 0);
    const wonDealValue = deals.filter(d => d.stage === 'closed_won').reduce((sum, d) => sum + (Number(d.amount) || 0), 0);
    const totalInvoiced = invoices.reduce((sum, i) => sum + (Number(i.total) || 0), 0);
    const totalPaid = invoices.filter(i => i.status === 'paid').reduce((sum, i) => sum + (Number(i.paidAmount) || 0), 0);
    const totalOutstanding = invoices.filter(i => i.status === 'pending' || i.status === 'overdue').reduce((sum, i) => sum + (Number(i.total) || 0), 0);

    return {
      account,
      contacts,
      deals,
      projects,
      invoices,
      tickets,
      stats: {
        totalDealValue,
        wonDealValue,
        totalInvoiced,
        totalPaid,
        totalOutstanding,
        activeProjectsCount: projects.filter(p => p.status !== 'completed').length,
        openTicketsCount: tickets.filter(t => t.status !== 'resolved' && t.status !== 'closed').length
      }
    };
  }

  // --- CONTACTS ---
  getContacts() {
    return [...this.data.contacts];
  }

  getContactById(id) {
    return this.data.contacts.find(c => c.id === id) || null;
  }

  saveContact(contact) {
    let isNew = false;
    if (!contact.id) {
      contact.id = 'cnt-' + String(Date.now()).slice(-6);
      contact.initials = (contact.firstName?.[0] || '') + (contact.lastName?.[0] || '');
      contact.name = `${contact.firstName || ''} ${contact.lastName || ''}`.trim() || contact.name || 'Unnamed';
      this.data.contacts.unshift(contact);
      isNew = true;
    } else {
      const idx = this.data.contacts.findIndex(c => c.id === contact.id);
      contact.initials = (contact.firstName?.[0] || '') + (contact.lastName?.[0] || '') || contact.initials;
      contact.name = `${contact.firstName || ''} ${contact.lastName || ''}`.trim() || contact.name;
      if (idx !== -1) {
        this.data.contacts[idx] = { ...this.data.contacts[idx], ...contact };
      } else {
        this.data.contacts.unshift(contact);
        isNew = true;
      }
    }
    this.save();
    this.notify('contacts:updated', contact);
    this.logActivity({
      type: 'contact',
      action: isNew ? 'Created Contact' : 'Updated Contact',
      title: `${isNew ? 'Added' : 'Updated'} contact "${contact.name}"`,
      details: `${contact.title || 'Contact'} at ${contact.accountName || 'Company'}`,
      icon: 'user-plus',
      color: '#8b5cf6'
    });
    return contact;
  }

  deleteContact(id) {
    const cnt = this.getContactById(id);
    this.data.contacts = this.data.contacts.filter(c => c.id !== id);
    this.save();
    this.notify('contacts:updated', { id, deleted: true });
    if (cnt) {
      this.logActivity({
        type: 'contact',
        action: 'Deleted Contact',
        title: `Removed contact "${cnt.name}"`,
        details: `Contact ID: ${id}`,
        icon: 'user-minus',
        color: '#ef4444'
      });
    }
  }

  // --- DEALS / OPPORTUNITIES ---
  getDeals() {
    return [...this.data.deals];
  }

  getDealById(id) {
    return this.data.deals.find(d => d.id === id) || null;
  }

  saveDeal(deal) {
    let isNew = false;
    const stages = this.data.settings.pipelineStages;
    const stageObj = stages.find(s => s.id === deal.stage) || { probability: 50 };
    deal.probability = deal.probability !== undefined ? deal.probability : stageObj.probability;
    deal.amount = Number(deal.amount) || 0;
    deal.weightedAmount = Math.round((deal.amount * deal.probability) / 100);

    if (!deal.id) {
      deal.id = 'deal-' + String(Date.now()).slice(-6);
      deal.createdAt = new Date().toISOString();
      deal.history = [{
        date: new Date().toISOString().split('T')[0],
        stage: deal.stage,
        note: 'Opportunity created'
      }];
      this.data.deals.unshift(deal);
      isNew = true;
    } else {
      const idx = this.data.deals.findIndex(d => d.id === deal.id);
      if (idx !== -1) {
        const old = this.data.deals[idx];
        if (old.stage !== deal.stage) {
          deal.history = [...(old.history || []), {
            date: new Date().toISOString().split('T')[0],
            stage: deal.stage,
            note: `Stage transitioned from ${old.stage} to ${deal.stage}`
          }];
          if (deal.stage === 'closed_won') {
            deal.actualCloseDate = new Date().toISOString().split('T')[0];
            this.triggerAutomations('deal_won', { deal });
          }
        }
        this.data.deals[idx] = { ...old, ...deal };
      } else {
        this.data.deals.unshift(deal);
        isNew = true;
      }
    }
    this.save();
    this.notify('deals:updated', deal);
    this.logActivity({
      type: 'deal',
      action: isNew ? 'Created Deal' : 'Updated Deal',
      title: `${isNew ? 'Created' : 'Updated'} deal "${deal.title}"`,
      details: `Value: $${deal.amount.toLocaleString()} | Stage: ${deal.stage}`,
      icon: 'dollar-sign',
      color: deal.stage === 'closed_won' ? '#10b981' : '#6366f1'
    });
    return deal;
  }

  updateDealStage(dealId, newStage) {
    const deal = this.getDealById(dealId);
    if (!deal) return null;
    deal.stage = newStage;
    return this.saveDeal(deal);
  }

  deleteDeal(id) {
    const deal = this.getDealById(id);
    this.data.deals = this.data.deals.filter(d => d.id !== id);
    this.save();
    this.notify('deals:updated', { id, deleted: true });
    if (deal) {
      this.logActivity({
        type: 'deal',
        action: 'Deleted Deal',
        title: `Removed deal "${deal.title}"`,
        details: `Deal ID: ${id}`,
        icon: 'trash-2',
        color: '#ef4444'
      });
    }
  }

  getPipelineMetrics() {
    const deals = this.data.deals;
    const stages = this.data.settings.pipelineStages;

    let totalPipelineValue = 0;
    let weightedPipelineValue = 0;
    let wonValue = 0;
    let wonCount = 0;
    let lostCount = 0;
    let openCount = 0;

    const byStage = {};
    stages.forEach(s => {
      byStage[s.id] = { count: 0, totalAmount: 0, weightedAmount: 0, deals: [], stageInfo: s };
    });

    deals.forEach(d => {
      const amt = Number(d.amount) || 0;
      const wAmt = Number(d.weightedAmount) || 0;

      if (d.stage === 'closed_won') {
        wonValue += amt;
        wonCount++;
      } else if (d.stage === 'closed_lost') {
        lostCount++;
      } else {
        totalPipelineValue += amt;
        weightedPipelineValue += wAmt;
        openCount++;
      }

      if (byStage[d.stage]) {
        byStage[d.stage].count++;
        byStage[d.stage].totalAmount += amt;
        byStage[d.stage].weightedAmount += wAmt;
        byStage[d.stage].deals.push(d);
      }
    });

    const totalClosed = wonCount + lostCount;
    const winRate = totalClosed > 0 ? Math.round((wonCount / totalClosed) * 100) : 0;
    const avgDealSize = wonCount > 0 ? Math.round(wonValue / wonCount) : (deals.length > 0 ? Math.round(totalPipelineValue / deals.length) : 0);

    return {
      totalPipelineValue,
      weightedPipelineValue,
      wonValue,
      wonCount,
      lostCount,
      openCount,
      winRate,
      avgDealSize,
      byStage
    };
  }

  // --- PROJECTS ---
  getProjects() {
    return [...this.data.projects];
  }

  getProjectById(id) {
    return this.data.projects.find(p => p.id === id) || null;
  }

  saveProject(project) {
    let isNew = false;
    project.budget = Number(project.budget) || 0;
    project.spent = Number(project.spent) || 0;
    project.progress = Number(project.progress) || 0;
    project.health = Number(project.health) || (project.status === 'delayed' ? 60 : (project.status === 'at_risk' ? 75 : 95));

    if (!project.id) {
      project.id = 'prj-' + String(Date.now()).slice(-6);
      project.code = project.code || 'PRJ-' + String(Math.floor(100 + Math.random() * 900));
      project.milestones = project.milestones || [];
      this.data.projects.unshift(project);
      isNew = true;
    } else {
      const idx = this.data.projects.findIndex(p => p.id === project.id);
      if (idx !== -1) {
        this.data.projects[idx] = { ...this.data.projects[idx], ...project };
      } else {
        this.data.projects.unshift(project);
        isNew = true;
      }
    }
    this.save();
    this.notify('projects:updated', project);
    this.logActivity({
      type: 'project',
      action: isNew ? 'Created Project' : 'Updated Project',
      title: `${isNew ? 'Launched' : 'Updated'} project "${project.name}"`,
      details: `Status: ${project.status} | Budget: $${project.budget.toLocaleString()} | Progress: ${project.progress}%`,
      icon: 'folder-plus',
      color: '#06b6d4'
    });
    return project;
  }

  toggleMilestone(projectId, milestoneId) {
    const prj = this.getProjectById(projectId);
    if (!prj || !prj.milestones) return null;
    const ms = prj.milestones.find(m => m.id === milestoneId);
    if (ms) {
      ms.completed = !ms.completed;
      // recalculate project progress based on completed milestones
      const total = prj.milestones.length;
      const completed = prj.milestones.filter(m => m.completed).length;
      if (total > 0) {
        prj.progress = Math.round((completed / total) * 100);
        if (prj.progress === 100) prj.status = 'completed';
      }
      this.saveProject(prj);
      if (ms.completed) {
        this.triggerAutomations('milestone_completed', { project: prj, milestone: ms });
      }
    }
    return prj;
  }

  deleteProject(id) {
    const prj = this.getProjectById(id);
    this.data.projects = this.data.projects.filter(p => p.id !== id);
    this.save();
    this.notify('projects:updated', { id, deleted: true });
    if (prj) {
      this.logActivity({
        type: 'project',
        action: 'Deleted Project',
        title: `Removed project "${prj.name}"`,
        details: `Project Code: ${prj.code}`,
        icon: 'trash-2',
        color: '#ef4444'
      });
    }
  }

  // --- TASKS ---
  getTasks() {
    return [...this.data.tasks];
  }

  getTaskById(id) {
    return this.data.tasks.find(t => t.id === id) || null;
  }

  saveTask(task) {
    let isNew = false;
    task.estimatedHours = Number(task.estimatedHours) || 0;
    task.loggedHours = Number(task.loggedHours) || 0;
    task.subtasks = task.subtasks || [];
    task.tags = task.tags || [];

    if (!task.id) {
      task.id = 'tsk-' + String(Date.now()).slice(-6);
      this.data.tasks.unshift(task);
      isNew = true;
    } else {
      const idx = this.data.tasks.findIndex(t => t.id === task.id);
      if (idx !== -1) {
        this.data.tasks[idx] = { ...this.data.tasks[idx], ...task };
      } else {
        this.data.tasks.unshift(task);
        isNew = true;
      }
    }
    this.save();
    this.notify('tasks:updated', task);
    this.logActivity({
      type: 'task',
      action: isNew ? 'Created Task' : 'Updated Task',
      title: `${isNew ? 'Created' : 'Updated'} task "${task.title}"`,
      details: `Priority: ${task.priority} | Status: ${task.status}`,
      icon: 'check-square',
      color: '#3b82f6'
    });
    return task;
  }

  updateTaskStatus(taskId, newStatus) {
    const task = this.getTaskById(taskId);
    if (!task) return null;
    task.status = newStatus;
    return this.saveTask(task);
  }

  toggleSubtask(taskId, subtaskId) {
    const task = this.getTaskById(taskId);
    if (!task || !task.subtasks) return null;
    const st = task.subtasks.find(s => s.id === subtaskId);
    if (st) {
      st.done = !st.done;
      // If all subtasks done, optionally prompt or mark complete
      const allDone = task.subtasks.every(s => s.done);
      if (allDone && task.status !== 'completed') {
        task.status = 'review';
      }
      this.saveTask(task);
    }
    return task;
  }

  logTaskTime(taskId, additionalHours, note = '') {
    const task = this.getTaskById(taskId);
    if (!task) return null;
    task.loggedHours = (Number(task.loggedHours) || 0) + Number(additionalHours);
    this.saveTask(task);
    this.logActivity({
      type: 'task',
      action: 'Logged Time',
      title: `Logged ${additionalHours}h on "${task.title}"`,
      details: note || `Total logged: ${task.loggedHours}h`,
      icon: 'clock',
      color: '#10b981'
    });
    return task;
  }

  deleteTask(id) {
    const task = this.getTaskById(id);
    this.data.tasks = this.data.tasks.filter(t => t.id !== id);
    this.save();
    this.notify('tasks:updated', { id, deleted: true });
    if (task) {
      this.logActivity({
        type: 'task',
        action: 'Deleted Task',
        title: `Removed task "${task.title}"`,
        details: `Task ID: ${id}`,
        icon: 'trash-2',
        color: '#ef4444'
      });
    }
  }

  // --- TIME TRACKER LIVE STOPWATCH ---
  startTimer(taskId, taskName = 'General Task') {
    if (this.activeTimer && this.activeTimer.isRunning) {
      this.pauseTimer();
    }
    this.activeTimer = {
      taskId,
      taskName,
      startTime: Date.now(),
      elapsedSeconds: this.activeTimer && this.activeTimer.taskId === taskId ? this.activeTimer.elapsedSeconds : 0,
      isRunning: true
    };
    this.saveTimer();
    this.resumeTimer();
    this.notify('timer:change', this.activeTimer);
  }

  resumeTimer() {
    if (this.timerInterval) clearInterval(this.timerInterval);
    this.timerInterval = setInterval(() => {
      if (this.activeTimer && this.activeTimer.isRunning) {
        this.activeTimer.elapsedSeconds++;
        this.saveTimer();
        this.notify('timer:tick', this.activeTimer);
      }
    }, 1000);
  }

  pauseTimer() {
    if (this.activeTimer) {
      this.activeTimer.isRunning = false;
      if (this.timerInterval) clearInterval(this.timerInterval);
      this.saveTimer();
      this.notify('timer:change', this.activeTimer);
    }
  }

  stopAndLogTimer() {
    if (!this.activeTimer) return null;
    const hours = (this.activeTimer.elapsedSeconds / 3600).toFixed(2);
    if (this.timerInterval) clearInterval(this.timerInterval);

    if (Number(hours) > 0 && this.activeTimer.taskId) {
      this.logTaskTime(this.activeTimer.taskId, Number(hours), 'Logged via live stopwatch timer');
    }

    const recorded = { ...this.activeTimer, loggedHours: hours };
    this.activeTimer = null;
    localStorage.removeItem(STORAGE_KEY + '_TIMER');
    this.notify('timer:change', null);
    return recorded;
  }

  getTimerState() {
    return this.activeTimer;
  }

  saveTimer() {
    try {
      localStorage.setItem(STORAGE_KEY + '_TIMER', JSON.stringify(this.activeTimer));
    } catch (e) {
      console.warn('Failed to save timer:', e);
    }
  }

  // --- INVOICES ---
  getInvoices() {
    return [...this.data.invoices];
  }

  getInvoiceById(id) {
    return this.data.invoices.find(i => i.id === id) || null;
  }

  saveInvoice(invoice) {
    let isNew = false;
    invoice.items = invoice.items || [];
    invoice.subtotal = invoice.items.reduce((sum, item) => sum + (Number(item.quantity || 1) * Number(item.unitPrice || 0)), 0);
    invoice.taxRate = Number(invoice.taxRate) || 0;
    invoice.taxAmount = (invoice.subtotal * invoice.taxRate) / 100;
    invoice.discount = Number(invoice.discount) || 0;
    invoice.total = Math.max(0, invoice.subtotal + invoice.taxAmount - invoice.discount);
    invoice.paidAmount = invoice.status === 'paid' ? invoice.total : (Number(invoice.paidAmount) || 0);

    if (!invoice.id) {
      invoice.id = 'inv-' + String(Date.now()).slice(-6);
      invoice.invoiceNumber = invoice.invoiceNumber || 'INV-2025-' + String(Math.floor(100 + Math.random() * 900));
      this.data.invoices.unshift(invoice);
      isNew = true;
    } else {
      const idx = this.data.invoices.findIndex(i => i.id === invoice.id);
      if (idx !== -1) {
        this.data.invoices[idx] = { ...this.data.invoices[idx], ...invoice };
      } else {
        this.data.invoices.unshift(invoice);
        isNew = true;
      }
    }
    this.save();
    this.notify('invoices:updated', invoice);
    this.logActivity({
      type: 'invoice',
      action: isNew ? 'Created Invoice' : 'Updated Invoice',
      title: `${isNew ? 'Generated' : 'Updated'} invoice ${invoice.invoiceNumber}`,
      details: `Total: $${invoice.total.toLocaleString()} | Status: ${invoice.status} | Client: ${invoice.accountName}`,
      icon: 'receipt',
      color: invoice.status === 'paid' ? '#10b981' : '#f59e0b'
    });
    return invoice;
  }

  markInvoicePaid(invoiceId, paymentMethod = 'Direct ACH / Wire') {
    const inv = this.getInvoiceById(invoiceId);
    if (!inv) return null;
    inv.status = 'paid';
    inv.paidAmount = inv.total;
    inv.paymentDate = new Date().toISOString().split('T')[0];
    inv.paymentMethod = paymentMethod;
    this.saveInvoice(inv);
    this.triggerAutomations('invoice_paid', { invoice: inv });
    return inv;
  }

  deleteInvoice(id) {
    const inv = this.getInvoiceById(id);
    this.data.invoices = this.data.invoices.filter(i => i.id !== id);
    this.save();
    this.notify('invoices:updated', { id, deleted: true });
    if (inv) {
      this.logActivity({
        type: 'invoice',
        action: 'Deleted Invoice',
        title: `Removed invoice ${inv.invoiceNumber}`,
        details: `Invoice ID: ${id}`,
        icon: 'trash-2',
        color: '#ef4444'
      });
    }
  }

  // --- SUPPORT TICKETS ---
  getTickets() {
    return [...this.data.tickets];
  }

  getTicketById(id) {
    return this.data.tickets.find(t => t.id === id) || null;
  }

  saveTicket(ticket) {
    let isNew = false;
    ticket.messages = ticket.messages || [];

    if (!ticket.id) {
      ticket.id = 'tkt-' + String(Date.now()).slice(-6);
      ticket.ticketNumber = ticket.ticketNumber || 'TKT-' + String(Math.floor(1000 + Math.random() * 9000));
      ticket.createdAt = new Date().toISOString();
      ticket.slaDeadline = new Date(Date.now() + 24 * 3600 * 1000).toISOString();
      this.data.tickets.unshift(ticket);
      isNew = true;
      this.triggerAutomations('ticket_created', { ticket });
    } else {
      const idx = this.data.tickets.findIndex(t => t.id === ticket.id);
      if (idx !== -1) {
        this.data.tickets[idx] = { ...this.data.tickets[idx], ...ticket };
      } else {
        this.data.tickets.unshift(ticket);
        isNew = true;
      }
    }
    this.save();
    this.notify('tickets:updated', ticket);
    this.logActivity({
      type: 'ticket',
      action: isNew ? 'Created Ticket' : 'Updated Ticket',
      title: `${isNew ? 'Opened' : 'Updated'} ticket ${ticket.ticketNumber}`,
      details: `${ticket.subject} | Priority: ${ticket.priority}`,
      icon: 'life-buoy',
      color: ticket.priority === 'urgent' ? '#ef4444' : '#3b82f6'
    });
    return ticket;
  }

  addTicketMessage(ticketId, message) {
    const ticket = this.getTicketById(ticketId);
    if (!ticket) return null;
    message.id = 'msg-' + String(Date.now()).slice(-6);
    message.timestamp = new Date().toISOString();
    ticket.messages.push(message);
    if (message.senderType === 'agent' && ticket.status === 'open') {
      ticket.status = 'in_progress';
    }
    this.saveTicket(ticket);
    return ticket;
  }

  deleteTicket(id) {
    const tkt = this.getTicketById(id);
    this.data.tickets = this.data.tickets.filter(t => t.id !== id);
    this.save();
    this.notify('tickets:updated', { id, deleted: true });
    if (tkt) {
      this.logActivity({
        type: 'ticket',
        action: 'Deleted Ticket',
        title: `Removed ticket ${tkt.ticketNumber}`,
        details: `Ticket ID: ${id}`,
        icon: 'trash-2',
        color: '#ef4444'
      });
    }
  }

  // --- TEAM & RESOURCES ---
  getTeamMembers() {
    return [...this.data.team];
  }

  getTeamMemberById(id) {
    return this.data.team.find(u => u.id === id) || null;
  }

  saveTeamMember(member) {
    if (!member.id) {
      member.id = 'usr-' + String(Date.now()).slice(-4);
      member.initials = member.name.split(' ').map(p => p[0]).join('').slice(0, 2).toUpperCase();
      this.data.team.push(member);
    } else {
      const idx = this.data.team.findIndex(u => u.id === member.id);
      member.initials = member.name.split(' ').map(p => p[0]).join('').slice(0, 2).toUpperCase();
      if (idx !== -1) {
        this.data.team[idx] = { ...this.data.team[idx], ...member };
      } else {
        this.data.team.push(member);
      }
    }
    this.save();
    this.notify('team:updated', member);
    return member;
  }

  // --- AUTOMATIONS ENGINE ---
  getAutomations() {
    return [...this.data.automations];
  }

  saveAutomation(rule) {
    if (!rule.id) {
      rule.id = 'auto-' + String(Date.now()).slice(-4);
      rule.executionCount = 0;
      this.data.automations.push(rule);
    } else {
      const idx = this.data.automations.findIndex(a => a.id === rule.id);
      if (idx !== -1) {
        this.data.automations[idx] = { ...this.data.automations[idx], ...rule };
      } else {
        this.data.automations.push(rule);
      }
    }
    this.save();
    this.notify('automations:updated', rule);
    return rule;
  }

  toggleAutomation(id) {
    const rule = this.data.automations.find(a => a.id === id);
    if (rule) {
      rule.isEnabled = !rule.isEnabled;
      this.save();
      this.notify('automations:updated', rule);
    }
    return rule;
  }

  triggerAutomations(triggerType, payload) {
    const activeRules = this.data.automations.filter(a => a.isEnabled && a.trigger === triggerType);
    activeRules.forEach(rule => {
      // Execute condition check
      let matches = true;
      if (rule.conditions && rule.conditions.length > 0) {
        rule.conditions.forEach(cond => {
          const val = this.getNestedValue(payload, cond.field);
          if (cond.operator === 'greater_than') {
            if (!(Number(val) > Number(cond.value))) matches = false;
          } else if (cond.operator === 'equals') {
            if (String(val).toLowerCase() !== String(cond.value).toLowerCase()) matches = false;
          }
        });
      }

      if (matches) {
        rule.executionCount = (rule.executionCount || 0) + 1;
        rule.lastRun = new Date().toISOString();

        // Perform side-effects if applicable
        if (rule.trigger === 'deal_won' && payload.deal) {
          // auto-create project if rule has create_project action
          const hasCreateProject = rule.actions.some(a => a.type === 'create_project');
          if (hasCreateProject) {
            this.saveProject({
              name: `Client Onboarding: ${payload.deal.title}`,
              accountId: payload.deal.accountId,
              accountName: payload.deal.accountName,
              dealId: payload.deal.id,
              status: 'on_track',
              progress: 10,
              budget: payload.deal.amount,
              spent: 0,
              startDate: new Date().toISOString().split('T')[0],
              endDate: new Date(Date.now() + 60 * 24 * 3600 * 1000).toISOString().split('T')[0],
              description: `Automated onboarding project spawned from Closed Won deal ${payload.deal.title}.`,
              milestones: [
                { id: 'm-auto-1', title: 'Executive Kickoff Call', dueDate: new Date(Date.now() + 7 * 24 * 3600 * 1000).toISOString().split('T')[0], completed: false },
                { id: 'm-auto-2', title: 'Technical Architecture Sign-off', dueDate: new Date(Date.now() + 21 * 24 * 3600 * 1000).toISOString().split('T')[0], completed: false }
              ]
            });
          }
        }

        this.logActivity({
          type: 'automation',
          action: 'Automation Executed',
          title: `Rule "${rule.name}" triggered`,
          details: `Trigger: ${rule.triggerLabel || rule.trigger} | Actions: ${rule.actions.length}`,
          icon: 'zap',
          color: '#ec4899'
        });
      }
    });
    this.save();
  }

  getNestedValue(obj, path) {
    if (!obj || !path) return undefined;
    return path.split('.').reduce((acc, part) => acc && acc[part], obj);
  }

  // --- ACTIVITIES & AUDIT LOGS ---
  getActivities(limit = 50) {
    return [...this.data.activities].slice(0, limit);
  }

  logActivity(activity) {
    activity.id = 'act-' + String(Date.now()).slice(-6);
    activity.timestamp = activity.timestamp || new Date().toISOString();
    activity.user = activity.user || 'Alexander Sterling';
    activity.userInitials = activity.userInitials || 'AS';
    this.data.activities.unshift(activity);
    if (this.data.activities.length > 200) {
      this.data.activities.pop();
    }
    this.save();
    this.notify('activities:new', activity);
  }

  // --- GLOBAL SEARCH ---
  searchAll(query) {
    if (!query || query.trim().length === 0) return { total: 0, results: [] };
    const q = query.trim().toLowerCase();
    const results = [];

    // Search Accounts
    this.data.accounts.forEach(a => {
      if (a.name.toLowerCase().includes(q) || a.industry.toLowerCase().includes(q) || a.tier.toLowerCase().includes(q)) {
        results.push({ type: 'account', id: a.id, title: a.name, subtitle: `${a.industry} • ${a.tier}`, icon: 'briefcase', color: a.logoBg || '#6366f1' });
      }
    });

    // Search Contacts
    this.data.contacts.forEach(c => {
      if (c.name.toLowerCase().includes(q) || c.email.toLowerCase().includes(q) || c.title.toLowerCase().includes(q)) {
        results.push({ type: 'contact', id: c.id, title: c.name, subtitle: `${c.title} @ ${c.accountName}`, icon: 'user', color: '#8b5cf6' });
      }
    });

    // Search Deals
    this.data.deals.forEach(d => {
      if (d.title.toLowerCase().includes(q) || d.accountName.toLowerCase().includes(q) || d.stage.toLowerCase().includes(q)) {
        results.push({ type: 'deal', id: d.id, title: d.title, subtitle: `$${d.amount.toLocaleString()} • Stage: ${d.stage}`, icon: 'dollar-sign', color: '#10b981' });
      }
    });

    // Search Projects
    this.data.projects.forEach(p => {
      if (p.name.toLowerCase().includes(q) || p.code.toLowerCase().includes(q) || p.accountName.toLowerCase().includes(q)) {
        results.push({ type: 'project', id: p.id, title: `${p.code}: ${p.name}`, subtitle: `Status: ${p.status} • Progress: ${p.progress}%`, icon: 'folder', color: '#06b6d4' });
      }
    });

    // Search Tasks
    this.data.tasks.forEach(t => {
      if (t.title.toLowerCase().includes(q) || t.projectName.toLowerCase().includes(q) || t.priority.toLowerCase().includes(q)) {
        results.push({ type: 'task', id: t.id, title: t.title, subtitle: `${t.projectName} • Priority: ${t.priority}`, icon: 'check-square', color: '#3b82f6' });
      }
    });

    // Search Invoices
    this.data.invoices.forEach(i => {
      if (i.invoiceNumber.toLowerCase().includes(q) || i.accountName.toLowerCase().includes(q) || i.status.toLowerCase().includes(q)) {
        results.push({ type: 'invoice', id: i.id, title: `${i.invoiceNumber} - ${i.accountName}`, subtitle: `$${i.total.toLocaleString()} • ${i.status.toUpperCase()}`, icon: 'receipt', color: '#f59e0b' });
      }
    });

    // Search Tickets
    this.data.tickets.forEach(t => {
      if (t.ticketNumber.toLowerCase().includes(q) || t.subject.toLowerCase().includes(q) || t.accountName.toLowerCase().includes(q)) {
        results.push({ type: 'ticket', id: t.id, title: `${t.ticketNumber}: ${t.subject}`, subtitle: `${t.accountName} • Priority: ${t.priority}`, icon: 'life-buoy', color: '#ef4444' });
      }
    });

    return { total: results.length, results: results.slice(0, 15) };
  }

  // --- DATA MANAGEMENT / IMPORT / EXPORT / RESET ---
  exportJSON() {
    return JSON.stringify(this.data, null, 2);
  }

  importJSON(jsonString) {
    try {
      const parsed = JSON.parse(jsonString);
      if (parsed && parsed.accounts && parsed.deals) {
        this.data = parsed;
        this.save();
        this.notify('*', { action: 'import' });
        return { success: true, message: 'Database imported successfully!' };
      }
      return { success: false, message: 'Invalid JSON format for CRM database.' };
    } catch (e) {
      return { success: false, message: 'JSON Parse Error: ' + e.message };
    }
  }

  resetToDefaultData(notifyUser = true) {
    this.data = JSON.parse(JSON.stringify(INITIAL_MOCK_DATA));
    this.save();
    if (notifyUser) {
      this.notify('*', { action: 'reset' });
      this.logActivity({
        type: 'system',
        action: 'Reset System',
        title: 'Database reset to default seed state',
        details: 'All collections re-seeded with initial mock records',
        icon: 'refresh-cw',
        color: '#6366f1'
      });
    }
  }

  exportCollectionCSV(collectionName) {
    const list = this.data[collectionName];
    if (!list || !Array.isArray(list) || list.length === 0) return '';
    const headers = Object.keys(list[0]).filter(k => typeof list[0][k] !== 'object');
    const rows = list.map(item => {
      return headers.map(h => {
        let val = item[h] !== undefined ? String(item[h]) : '';
        val = val.replace(/"/g, '""');
        return `"${val}"`;
      }).join(',');
    });
    return [headers.join(','), ...rows].join('\n');
  }

  getRandomColor() {
    const colors = ['#6366f1', '#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#8b5cf6', '#06b6d4', '#14b8a6', '#f97316'];
    return colors[Math.floor(Math.random() * colors.length)];
  }
}

const dataStore = new DataStore();

  /**
 * Enterprise Project CRM - Toast Notifications Manager
 * Multi-type alerts (success, info, warning, error) with auto-dismiss and progress bar.
 */

class ToastManager {
  constructor() {
    this.container = null;
    this.init();
  }

  init() {
    let existing = document.getElementById('crm-toast-container');
    if (!existing) {
      existing = document.createElement('div');
      existing.id = 'crm-toast-container';
      existing.className = 'toast-container';
      document.body.appendChild(existing);
    }
    this.container = existing;
  }

  show(options = {}) {
    const {
      type = 'info', // 'success', 'error', 'warning', 'info'
      title = 'Notification',
      message = '',
      duration = 4000
    } = typeof options === 'string' ? { message: options } : options;

    const toast = document.createElement('div');
    toast.className = `toast toast-${type} animate-slide-in`;

    const iconMap = {
      success: `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>`,
      error: `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>`,
      warning: `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>`,
      info: `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>`
    };

    toast.innerHTML = `
      <div class="toast-icon">${iconMap[type] || iconMap.info}</div>
      <div class="toast-content">
        <div class="toast-title">${this.escapeHtml(title)}</div>
        ${message ? `<div class="toast-message">${this.escapeHtml(message)}</div>` : ''}
      </div>
      <button class="toast-close" aria-label="Close">&times;</button>
      <div class="toast-progress" style="animation-duration: ${duration}ms"></div>
    `;

    const closeBtn = toast.querySelector('.toast-close');
    const dismiss = () => {
      toast.classList.add('animate-fade-out');
      setTimeout(() => {
        if (toast.parentElement) {
          toast.parentElement.removeChild(toast);
        }
      }, 300);
    };

    closeBtn.addEventListener('click', dismiss);

    this.container.appendChild(toast);

    if (duration > 0) {
      setTimeout(dismiss, duration);
    }
  }

  success(title, message = '') {
    this.show({ type: 'success', title, message });
  }

  error(title, message = '') {
    this.show({ type: 'error', title, message, duration: 6000 });
  }

  warning(title, message = '') {
    this.show({ type: 'warning', title, message });
  }

  info(title, message = '') {
    this.show({ type: 'info', title, message });
  }

  escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}

const toast = new ToastManager();

  /**
 * Enterprise Project CRM - Modal & Drawer Manager
 * Supports accessible dialogs, slide-over side drawers, confirmation prompts,
 * backdrop animations, and form validation bindings.
 */

class ModalManager {
  constructor() {
    this.activeModal = null;
    this.activeDrawer = null;
    this.init();
  }

  init() {
    // Listen for Escape key
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        if (this.activeModal) {
          this.closeModal();
        } else if (this.activeDrawer) {
          this.closeDrawer();
        }
      }
    });
  }

  /**
   * Opens a standard centered modal
   */
  openModal(options = {}) {
    const {
      title = 'Dialog',
      content = '',
      width = '640px',
      showFooter = true,
      confirmText = 'Save Changes',
      confirmClass = 'btn-primary',
      cancelText = 'Cancel',
      onConfirm = null,
      onOpen = null
    } = options;

    this.closeModal(false);

    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay animate-fade-in';
    overlay.id = 'crm-active-modal-overlay';

    const modal = document.createElement('div');
    modal.className = 'modal-dialog animate-scale-up';
    modal.style.maxWidth = width;

    modal.innerHTML = `
      <div class="modal-header">
        <h3 class="modal-title">${this.escapeHtml(title)}</h3>
        <button class="modal-close-btn" aria-label="Close dialog">&times;</button>
      </div>
      <div class="modal-body">
        ${typeof content === 'string' ? content : ''}
      </div>
      ${showFooter ? `
        <div class="modal-footer">
          <button class="btn btn-secondary modal-cancel-btn">${this.escapeHtml(cancelText)}</button>
          <button class="btn ${confirmClass} modal-confirm-btn">${this.escapeHtml(confirmText)}</button>
        </div>
      ` : ''}
    `;

    if (typeof content !== 'string' && content instanceof HTMLElement) {
      modal.querySelector('.modal-body').appendChild(content);
    }

    overlay.appendChild(modal);
    document.body.appendChild(overlay);
    this.activeModal = overlay;
    document.body.classList.add('modal-open');

    // Event Listeners
    const closeBtn = modal.querySelector('.modal-close-btn');
    const cancelBtn = modal.querySelector('.modal-cancel-btn');
    const confirmBtn = modal.querySelector('.modal-confirm-btn');

    if (closeBtn) closeBtn.addEventListener('click', () => this.closeModal());
    if (cancelBtn) cancelBtn.addEventListener('click', () => this.closeModal());
    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) this.closeModal();
    });

    if (confirmBtn && onConfirm) {
      confirmBtn.addEventListener('click', async () => {
        const bodyEl = modal.querySelector('.modal-body');
        const form = bodyEl.querySelector('form');
        let formData = null;
        if (form) {
          if (!form.checkValidity()) {
            form.reportValidity();
            return;
          }
          formData = new FormData(form);
        }
        const shouldClose = await onConfirm(formData, bodyEl);
        if (shouldClose !== false) {
          this.closeModal();
        }
      });
    }

    if (onOpen) {
      setTimeout(() => onOpen(modal.querySelector('.modal-body')), 50);
    }
  }

  closeModal(animate = true) {
    if (!this.activeModal) return;
    const overlay = this.activeModal;
    this.activeModal = null;
    document.body.classList.remove('modal-open');

    if (animate) {
      overlay.classList.add('animate-fade-out');
      setTimeout(() => {
        if (overlay.parentElement) overlay.parentElement.removeChild(overlay);
      }, 200);
    } else {
      if (overlay.parentElement) overlay.parentElement.removeChild(overlay);
    }
  }

  /**
   * Opens a slide-over side drawer (perfect for 360 views and details)
   */
  openDrawer(options = {}) {
    const {
      title = 'Details',
      subtitle = '',
      content = '',
      width = '680px',
      onOpen = null
    } = options;

    this.closeDrawer(false);

    const overlay = document.createElement('div');
    overlay.className = 'drawer-overlay animate-fade-in';
    overlay.id = 'crm-active-drawer-overlay';

    const drawer = document.createElement('div');
    drawer.className = 'drawer-panel animate-slide-left';
    drawer.style.maxWidth = width;

    drawer.innerHTML = `
      <div class="drawer-header">
        <div>
          <h3 class="drawer-title">${this.escapeHtml(title)}</h3>
          ${subtitle ? `<div class="drawer-subtitle">${this.escapeHtml(subtitle)}</div>` : ''}
        </div>
        <button class="drawer-close-btn" aria-label="Close drawer">&times;</button>
      </div>
      <div class="drawer-body">
        ${typeof content === 'string' ? content : ''}
      </div>
    `;

    if (typeof content !== 'string' && content instanceof HTMLElement) {
      drawer.querySelector('.drawer-body').appendChild(content);
    }

    overlay.appendChild(drawer);
    document.body.appendChild(overlay);
    this.activeDrawer = overlay;
    document.body.classList.add('modal-open');

    const closeBtn = drawer.querySelector('.drawer-close-btn');
    if (closeBtn) closeBtn.addEventListener('click', () => this.closeDrawer());
    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) this.closeDrawer();
    });

    if (onOpen) {
      setTimeout(() => onOpen(drawer.querySelector('.drawer-body')), 50);
    }
  }

  closeDrawer(animate = true) {
    if (!this.activeDrawer) return;
    const overlay = this.activeDrawer;
    this.activeDrawer = null;
    document.body.classList.remove('modal-open');

    if (animate) {
      const panel = overlay.querySelector('.drawer-panel');
      if (panel) panel.classList.add('animate-slide-right');
      overlay.classList.add('animate-fade-out');
      setTimeout(() => {
        if (overlay.parentElement) overlay.parentElement.removeChild(overlay);
      }, 250);
    } else {
      if (overlay.parentElement) overlay.parentElement.removeChild(overlay);
    }
  }

  /**
   * Displays a confirmation prompt
   */
  confirm(options = {}) {
    const {
      title = 'Are you sure?',
      message = 'This action cannot be undone.',
      confirmText = 'Confirm',
      confirmClass = 'btn-danger',
      cancelText = 'Cancel',
      onConfirm = null
    } = options;

    this.openModal({
      title,
      width: '450px',
      content: `<p class="confirm-modal-message">${this.escapeHtml(message)}</p>`,
      confirmText,
      confirmClass,
      cancelText,
      onConfirm: async () => {
        if (onConfirm) await onConfirm();
        return true;
      }
    });
  }

  escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}

const modal = new ModalManager();

  /**
 * Enterprise Project CRM - Custom Pure SVG & Canvas Chart Engine
 * Zero external libraries (100% self-contained).
 * Supports: Line/Area Charts, Bar Charts, Donut/Pie Charts, Pipeline Funnels, and Sparklines.
 */

class ChartEngine {
  /**
   * Renders a sleek Line / Area Chart with gradient fill and tooltips
   */
  static renderAreaChart(container, options = {}) {
    const {
      data = [], // [{ label: 'Jan', value: 120000, value2?: 90000 }]
      series = [{ key: 'value', color: '#6366f1', label: 'Revenue' }],
      height = 240,
      currency = '$',
      showGrid = true
    } = options;

    if (!container) return;
    if (typeof container === 'string') container = document.querySelector(container);
    if (!container || !data.length) {
      if (container) container.innerHTML = '<div class="chart-empty">No data available</div>';
      return;
    }

    const width = container.clientWidth || 500;
    const padding = { top: 20, right: 20, bottom: 35, left: 55 };
    const chartW = width - padding.left - padding.right;
    const chartH = height - padding.top - padding.bottom;

    // Find max value across all series
    let maxVal = 0;
    data.forEach(d => {
      series.forEach(s => {
        const v = Number(d[s.key]) || 0;
        if (v > maxVal) maxVal = v;
      });
    });
    maxVal = maxVal === 0 ? 100 : Math.ceil(maxVal * 1.15);

    const stepX = chartW / Math.max(1, data.length - 1);
    const getY = (val) => chartH - (val / maxVal) * chartH;

    // Build SVG
    let svg = `<svg viewBox="0 0 ${width} ${height}" class="crm-chart-svg" style="width:100%; height:${height}px;">`;

    // Gradients
    svg += '<defs>';
    series.forEach((s, idx) => {
      svg += `
        <linearGradient id="grad-${idx}" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="${s.color}" stop-opacity="0.35"/>
          <stop offset="100%" stop-color="${s.color}" stop-opacity="0.0"/>
        </linearGradient>
      `;
    });
    svg += '</defs>';

    // Horizontal Grid Lines & Y-Axis Labels
    if (showGrid) {
      const gridSteps = 4;
      for (let i = 0; i <= gridSteps; i++) {
        const yVal = (maxVal / gridSteps) * (gridSteps - i);
        const yPos = padding.top + (chartH / gridSteps) * i;
        svg += `
          <line x1="${padding.left}" y1="${yPos}" x2="${width - padding.right}" y2="${yPos}" stroke="var(--border-color)" stroke-dasharray="3,3" stroke-width="1"/>
          <text x="${padding.left - 10}" y="${yPos + 4}" font-size="11" fill="var(--text-muted)" text-anchor="end">${currency}${this.formatNumber(yVal)}</text>
        `;
      }
    }

    // Series Paths
    series.forEach((s, sIdx) => {
      const points = data.map((d, i) => ({
        x: padding.left + i * stepX,
        y: padding.top + getY(Number(d[s.key]) || 0),
        val: Number(d[s.key]) || 0,
        label: d.label
      }));

      // Smooth Bezier Curve
      let pathD = `M ${points[0].x} ${points[0].y}`;
      for (let i = 0; i < points.length - 1; i++) {
        const p0 = points[i];
        const p1 = points[i + 1];
        const cpX = (p0.x + p1.x) / 2;
        pathD += ` C ${cpX} ${p0.y}, ${cpX} ${p1.y}, ${p1.x} ${p1.y}`;
      }

      // Area path
      const areaD = `${pathD} L ${points[points.length - 1].x} ${padding.top + chartH} L ${points[0].x} ${padding.top + chartH} Z`;

      svg += `<path d="${areaD}" fill="url(#grad-${sIdx})" />`;
      svg += `<path d="${pathD}" fill="none" stroke="${s.color}" stroke-width="3" stroke-linecap="round" class="chart-line-path" />`;

      // Data dots
      points.forEach((p, pIdx) => {
        svg += `
          <circle cx="${p.x}" cy="${p.y}" r="4.5" fill="${s.color}" stroke="var(--bg-card)" stroke-width="2" class="chart-dot" data-label="${p.label}" data-value="${currency}${p.val.toLocaleString()}" data-series="${s.label}"/>
        `;
      });
    });

    // X-Axis Labels
    data.forEach((d, i) => {
      const xPos = padding.left + i * stepX;
      svg += `
        <text x="${xPos}" y="${height - 10}" font-size="11" fill="var(--text-muted)" text-anchor="middle">${d.label}</text>
      `;
    });

    svg += '</svg>';
    container.innerHTML = svg;

    this.attachTooltipHandler(container);
  }

  /**
   * Renders a modern Vertical Bar Chart
   */
  static renderBarChart(container, options = {}) {
    const {
      data = [], // [{ label: 'Q1', value: 80, color: '#3b82f6' }]
      height = 240,
      currency = '',
      barColor = '#3b82f6'
    } = options;

    if (!container) return;
    if (typeof container === 'string') container = document.querySelector(container);
    if (!container || !data.length) {
      if (container) container.innerHTML = '<div class="chart-empty">No data available</div>';
      return;
    }

    const width = container.clientWidth || 500;
    const padding = { top: 25, right: 20, bottom: 35, left: 55 };
    const chartW = width - padding.left - padding.right;
    const chartH = height - padding.top - padding.bottom;

    const maxVal = Math.ceil((Math.max(...data.map(d => Number(d.value) || 0)) || 100) * 1.15);
    const barWidth = Math.min(42, Math.max(14, (chartW / data.length) * 0.55));
    const stepX = chartW / data.length;

    let svg = `<svg viewBox="0 0 ${width} ${height}" class="crm-chart-svg" style="width:100%; height:${height}px;">`;

    // Grid lines
    const gridSteps = 4;
    for (let i = 0; i <= gridSteps; i++) {
      const yVal = (maxVal / gridSteps) * (gridSteps - i);
      const yPos = padding.top + (chartH / gridSteps) * i;
      svg += `
        <line x1="${padding.left}" y1="${yPos}" x2="${width - padding.right}" y2="${yPos}" stroke="var(--border-color)" stroke-dasharray="3,3" stroke-width="1"/>
        <text x="${padding.left - 10}" y="${yPos + 4}" font-size="11" fill="var(--text-muted)" text-anchor="end">${currency}${this.formatNumber(yVal)}</text>
      `;
    }

    // Bars
    data.forEach((d, i) => {
      const val = Number(d.value) || 0;
      const bH = (val / maxVal) * chartH;
      const x = padding.left + i * stepX + (stepX - barWidth) / 2;
      const y = padding.top + chartH - bH;
      const color = d.color || barColor;

      svg += `
        <rect x="${x}" y="${y}" width="${barWidth}" height="${Math.max(2, bH)}" rx="5" ry="5" fill="${color}" class="chart-bar" data-label="${d.label}" data-value="${currency}${val.toLocaleString()}" />
        <text x="${x + barWidth / 2}" y="${height - 10}" font-size="11" fill="var(--text-muted)" text-anchor="middle">${d.label}</text>
      `;
    });

    svg += '</svg>';
    container.innerHTML = svg;

    this.attachTooltipHandler(container);
  }

  /**
   * Renders a Donut / Pie Chart with center metrics and legend
   */
  static renderDonutChart(container, options = {}) {
    const {
      data = [], // [{ label: 'Enterprise', value: 45, color: '#6366f1' }]
      height = 240,
      centerLabel = 'Total',
      centerValue = ''
    } = options;

    if (!container) return;
    if (typeof container === 'string') container = document.querySelector(container);
    if (!container || !data.length) {
      if (container) container.innerHTML = '<div class="chart-empty">No data available</div>';
      return;
    }

    const total = data.reduce((sum, d) => sum + (Number(d.value) || 0), 0);
    const size = Math.min(220, height);
    const center = size / 2;
    const radius = size * 0.42;
    const innerRadius = size * 0.28;

    let cumulativeAngle = 0;
    let svgSegments = '';

    data.forEach(d => {
      const val = Number(d.value) || 0;
      if (val <= 0) return;
      const sliceAngle = (val / total) * 360;
      const startAngle = cumulativeAngle;
      const endAngle = cumulativeAngle + sliceAngle;
      cumulativeAngle += sliceAngle;

      const path = this.describeDonutArc(center, center, radius, innerRadius, startAngle, endAngle);
      svgSegments += `
        <path d="${path}" fill="${d.color}" class="chart-donut-segment" data-label="${d.label}" data-value="${val} (${Math.round((val / total) * 100)}%)" />
      `;
    });

    const displayCenterVal = centerValue || total.toLocaleString();

    let html = `
      <div class="donut-chart-wrapper" style="display:flex; align-items:center; justify-content:center; gap:20px; flex-wrap:wrap;">
        <div style="position:relative; width:${size}px; height:${size}px;">
          <svg viewBox="0 0 ${size} ${size}" width="${size}" height="${size}">
            ${svgSegments}
          </svg>
          <div style="position:absolute; top:50%; left:50%; transform:translate(-50%, -50%); text-align:center; pointer-events:none;">
            <div style="font-size:11px; color:var(--text-muted); text-transform:uppercase; font-weight:600;">${centerLabel}</div>
            <div style="font-size:18px; font-weight:700; color:var(--text-primary);">${displayCenterVal}</div>
          </div>
        </div>
        <div class="donut-legend" style="display:flex; flex-direction:column; gap:8px;">
          ${data.map(d => {
            const pct = total > 0 ? Math.round((d.value / total) * 100) : 0;
            return `
              <div class="legend-item" style="display:flex; align-items:center; gap:8px; font-size:12px;">
                <span style="width:10px; height:10px; border-radius:50%; background-color:${d.color}; display:inline-block;"></span>
                <span style="color:var(--text-secondary); min-width:110px;">${d.label}</span>
                <span style="font-weight:600; color:var(--text-primary);">${d.value}</span>
                <span style="color:var(--text-muted); font-size:11px;">(${pct}%)</span>
              </div>
            `;
          }).join('')}
        </div>
      </div>
    `;

    container.innerHTML = html;
    this.attachTooltipHandler(container);
  }

  /**
   * Renders a Deal Pipeline Conversion Funnel
   */
  static renderFunnelChart(container, stages = [], deals = []) {
    if (!container) return;
    if (typeof container === 'string') container = document.querySelector(container);
    if (!container) return;

    // Filter out closed lost for funnel progression
    const validStages = stages.filter(s => s.id !== 'closed_lost');
    const counts = {};
    const amounts = {};
    validStages.forEach(s => {
      counts[s.id] = 0;
      amounts[s.id] = 0;
    });

    deals.forEach(d => {
      if (counts[d.stage] !== undefined) {
        counts[d.stage]++;
        amounts[d.stage] += Number(d.amount) || 0;
      }
    });

    const maxCount = Math.max(...Object.values(counts), 1);

    let html = `
      <div class="funnel-container" style="display:flex; flex-direction:column; gap:12px; width:100%;">
        ${validStages.map((s, idx) => {
          const count = counts[s.id] || 0;
          const amt = amounts[s.id] || 0;
          const pct = Math.round((count / maxCount) * 100);
          const widthPct = Math.max(18, pct);

          return `
            <div class="funnel-stage-row" style="display:flex; align-items:center; gap:12px;">
              <div style="width:130px; font-size:12px; font-weight:600; color:var(--text-primary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
                ${s.name}
              </div>
              <div style="flex:1; background:var(--bg-card-hover); border-radius:8px; overflow:hidden; height:34px; display:flex; align-items:center; padding:2px;">
                <div style="width:${widthPct}%; height:100%; background:${s.color}; border-radius:6px; display:flex; align-items:center; justify-content:space-between; padding:0 12px; transition:width 0.5s ease;">
                  <span style="font-size:12px; font-weight:700; color:#fff;">${count} deals</span>
                  <span style="font-size:11px; font-weight:600; color:rgba(255,255,255,0.9);">$${amt.toLocaleString()}</span>
                </div>
              </div>
              <div style="width:45px; text-align:right; font-size:11px; font-weight:600; color:var(--text-muted);">
                ${s.probability}%
              </div>
            </div>
          `;
        }).join('')}
      </div>
    `;

    container.innerHTML = html;
  }

  /**
   * Renders a lightweight SVG Sparkline for KPI cards
   */
  static renderSparkline(values = [], color = '#10b981', width = 100, height = 32) {
    if (!values || values.length < 2) return '';
    const min = Math.min(...values);
    const max = Math.max(...values);
    const range = max - min || 1;
    const step = width / (values.length - 1);

    const points = values.map((v, i) => {
      const x = i * step;
      const y = height - ((v - min) / range) * (height - 8) - 4;
      return `${x},${y}`;
    }).join(' ');

    return `
      <svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" style="overflow:visible;">
        <polyline fill="none" stroke="${color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" points="${points}" />
      </svg>
    `;
  }

  // --- HELPER METHODS ---
  static describeDonutArc(cx, cy, r, ir, startAngle, endAngle) {
    // clamp angles
    if (endAngle - startAngle >= 359.99) endAngle = startAngle + 359.99;
    const startRad = (startAngle - 90) * Math.PI / 180.0;
    const endRad = (endAngle - 90) * Math.PI / 180.0;

    const x1 = cx + r * Math.cos(startRad);
    const y1 = cy + r * Math.sin(startRad);
    const x2 = cx + r * Math.cos(endRad);
    const y2 = cy + r * Math.sin(endRad);

    const ix1 = cx + ir * Math.cos(endRad);
    const iy1 = cy + ir * Math.sin(endRad);
    const ix2 = cx + ir * Math.cos(startRad);
    const iy2 = cy + ir * Math.sin(startRad);

    const largeArcFlag = endAngle - startAngle <= 180 ? '0' : '1';

    return [
      'M', x1, y1,
      'A', r, r, 0, largeArcFlag, 1, x2, y2,
      'L', ix1, iy1,
      'A', ir, ir, 0, largeArcFlag, 0, ix2, iy2,
      'Z'
    ].join(' ');
  }

  static formatNumber(num) {
    if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
    if (num >= 1000) return (num / 1000).toFixed(0) + 'k';
    return Math.round(num);
  }

  static attachTooltipHandler(container) {
    let tooltip = document.getElementById('crm-chart-tooltip');
    if (!tooltip) {
      tooltip = document.createElement('div');
      tooltip.id = 'crm-chart-tooltip';
      tooltip.className = 'chart-tooltip';
      document.body.appendChild(tooltip);
    }

    const targets = container.querySelectorAll('.chart-dot, .chart-bar, .chart-donut-segment');
    targets.forEach(el => {
      el.addEventListener('mouseenter', (e) => {
        const label = el.getAttribute('data-label') || '';
        const val = el.getAttribute('data-value') || '';
        const series = el.getAttribute('data-series') || '';

        tooltip.innerHTML = `
          <div class="tooltip-title">${label}</div>
          <div class="tooltip-value">${series ? `<strong>${series}:</strong> ` : ''}${val}</div>
        `;
        tooltip.style.opacity = '1';
      });

      el.addEventListener('mousemove', (e) => {
        tooltip.style.left = `${e.clientX + 14}px`;
        tooltip.style.top = `${e.clientY - 28}px`;
      });

      el.addEventListener('mouseleave', () => {
        tooltip.style.opacity = '0';
      });
    });
  }
}

  /**
 * Enterprise Project CRM - Reusable High-Performance Table Grid Component
 * Features: Sorting, search filtering, batch selection, pagination, and CSV export.
 */

class TableGrid {
  constructor(options = {}) {
    this.container = options.container;
    if (typeof this.container === 'string') {
      this.container = document.querySelector(this.container);
    }
    this.columns = options.columns || []; // [{ key: 'id', label: 'ID', sortable: true, render: fn }]
    this.data = options.data || [];
    this.filteredData = [...this.data];
    this.pageSize = options.pageSize || 10;
    this.currentPage = 1;
    this.sortKey = options.defaultSortKey || null;
    this.sortAsc = options.defaultSortAsc !== undefined ? options.defaultSortAsc : true;
    this.searchQuery = '';
    this.selectedIds = new Set();
    this.onRowClick = options.onRowClick || null;
    this.batchActions = options.batchActions || []; // [{ label: 'Delete', action: fn, class: 'btn-danger' }]
    this.emptyMessage = options.emptyMessage || 'No records found';
    this.idKey = options.idKey || 'id';

    this.render();
  }

  setData(newData) {
    this.data = newData || [];
    this.selectedIds.clear();
    this.applyFilters();
  }

  applyFilters() {
    let result = [...this.data];

    // Search query filter
    if (this.searchQuery) {
      const q = this.searchQuery.toLowerCase();
      result = result.filter(item => {
        return this.columns.some(col => {
          const val = item[col.key];
          if (val === null || val === undefined) return false;
          return String(val).toLowerCase().includes(q);
        });
      });
    }

    // Sorting
    if (this.sortKey) {
      result.sort((a, b) => {
        let valA = a[this.sortKey];
        let valB = b[this.sortKey];

        if (typeof valA === 'number' && typeof valB === 'number') {
          return this.sortAsc ? valA - valB : valB - valA;
        }

        valA = String(valA || '').toLowerCase();
        valB = String(valB || '').toLowerCase();
        if (valA < valB) return this.sortAsc ? -1 : 1;
        if (valA > valB) return this.sortAsc ? 1 : -1;
        return 0;
      });
    }

    this.filteredData = result;
    this.currentPage = 1;
    this.render();
  }

  render() {
    if (!this.container) return;

    const totalPages = Math.max(1, Math.ceil(this.filteredData.length / this.pageSize));
    if (this.currentPage > totalPages) this.currentPage = totalPages;

    const startIndex = (this.currentPage - 1) * this.pageSize;
    const pageItems = this.filteredData.slice(startIndex, startIndex + this.pageSize);
    const allPageSelected = pageItems.length > 0 && pageItems.every(item => this.selectedIds.has(item[this.idKey]));

    let html = `
      <div class="table-grid-wrapper">
        <div class="table-grid-toolbar">
          <div class="table-grid-search">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
            <input type="text" class="input table-search-input" placeholder="Search records..." value="${this.escapeHtml(this.searchQuery)}" />
          </div>
          <div class="table-grid-actions">
            ${this.selectedIds.size > 0 ? `
              <div class="table-batch-menu animate-fade-in">
                <span class="batch-count-badge">${this.selectedIds.size} selected</span>
                ${this.batchActions.map((act, i) => `
                  <button class="btn btn-sm ${act.class || 'btn-secondary'} table-batch-btn" data-batch-index="${i}">
                    ${act.icon || ''} ${act.label}
                  </button>
                `).join('')}
              </div>
            ` : ''}
          </div>
        </div>

        <div class="table-container">
          <table class="table crm-table">
            <thead>
              <tr>
                <th style="width: 40px; text-align:center;">
                  <input type="checkbox" class="crm-checkbox table-select-all" ${allPageSelected ? 'checked' : ''} />
                </th>
                ${this.columns.map(col => {
                  const isSorted = this.sortKey === col.key;
                  const sortIcon = isSorted ? (this.sortAsc ? '▲' : '▼') : '↕';
                  return `
                    <th class="${col.sortable !== false ? 'sortable' : ''} ${col.headerClass || ''}" data-col-key="${col.key}">
                      <div class="th-content">
                        <span>${col.label}</span>
                        ${col.sortable !== false ? `<span class="sort-icon ${isSorted ? 'active' : ''}">${sortIcon}</span>` : ''}
                      </div>
                    </th>
                  `;
                }).join('')}
              </tr>
            </thead>
            <tbody>
              ${pageItems.length === 0 ? `
                <tr>
                  <td colspan="${this.columns.length + 1}" class="table-empty-cell">
                    <div class="table-empty-state">
                      <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
                      <div>${this.emptyMessage}</div>
                    </div>
                  </td>
                </tr>
              ` : pageItems.map(item => {
                const isSelected = this.selectedIds.has(item[this.idKey]);
                return `
                  <tr class="table-row ${isSelected ? 'row-selected' : ''}" data-id="${item[this.idKey]}">
                    <td style="text-align:center;" onclick="event.stopPropagation()">
                      <input type="checkbox" class="crm-checkbox table-row-select" data-id="${item[this.idKey]}" ${isSelected ? 'checked' : ''} />
                    </td>
                    ${this.columns.map(col => {
                      let content = '';
                      if (col.render && typeof col.render === 'function') {
                        content = col.render(item[col.key], item);
                      } else {
                        content = this.escapeHtml(item[col.key] !== undefined ? item[col.key] : '');
                      }
                      return `<td class="${col.cellClass || ''}">${content}</td>`;
                    }).join('')}
                  </tr>
                `;
              }).join('')}
            </tbody>
          </table>
        </div>

        <div class="table-grid-pagination">
          <div class="pagination-info">
            Showing <strong>${this.filteredData.length === 0 ? 0 : startIndex + 1}</strong> to <strong>${Math.min(startIndex + this.pageSize, this.filteredData.length)}</strong> of <strong>${this.filteredData.length}</strong> entries
          </div>
          <div class="pagination-controls">
            <button class="btn btn-sm btn-secondary btn-prev" ${this.currentPage <= 1 ? 'disabled' : ''}>Previous</button>
            <span class="pagination-page-indicator">Page ${this.currentPage} of ${totalPages}</span>
            <button class="btn btn-sm btn-secondary btn-next" ${this.currentPage >= totalPages ? 'disabled' : ''}>Next</button>
          </div>
        </div>
      </div>
    `;

    this.container.innerHTML = html;
    this.bindEvents();
  }

  bindEvents() {
    // Search input
    const searchInput = this.container.querySelector('.table-search-input');
    if (searchInput) {
      searchInput.addEventListener('input', (e) => {
        this.searchQuery = e.target.value;
        this.applyFilters();
      });
      // Keep focus if user is typing
      if (this.searchQuery) {
        searchInput.focus();
        searchInput.setSelectionRange(searchInput.value.length, searchInput.value.length);
      }
    }

    // Sort headers
    const sortHeaders = this.container.querySelectorAll('th.sortable');
    sortHeaders.forEach(th => {
      th.addEventListener('click', () => {
        const key = th.getAttribute('data-col-key');
        if (this.sortKey === key) {
          this.sortAsc = !this.sortAsc;
        } else {
          this.sortKey = key;
          this.sortAsc = true;
        }
        this.applyFilters();
      });
    });

    // Select all checkbox
    const selectAll = this.container.querySelector('.table-select-all');
    if (selectAll) {
      selectAll.addEventListener('change', (e) => {
        const startIndex = (this.currentPage - 1) * this.pageSize;
        const pageItems = this.filteredData.slice(startIndex, startIndex + this.pageSize);
        if (e.target.checked) {
          pageItems.forEach(item => this.selectedIds.add(item[this.idKey]));
        } else {
          pageItems.forEach(item => this.selectedIds.delete(item[this.idKey]));
        }
        this.render();
      });
    }

    // Row selection checkboxes
    const rowCheckboxes = this.container.querySelectorAll('.table-row-select');
    rowCheckboxes.forEach(cb => {
      cb.addEventListener('change', (e) => {
        const id = cb.getAttribute('data-id');
        if (e.target.checked) {
          this.selectedIds.add(id);
        } else {
          this.selectedIds.delete(id);
        }
        this.render();
      });
    });

    // Row click handler
    if (this.onRowClick) {
      const rows = this.container.querySelectorAll('tbody tr.table-row');
      rows.forEach(tr => {
        tr.addEventListener('click', () => {
          const id = tr.getAttribute('data-id');
          const item = this.data.find(d => String(d[this.idKey]) === String(id));
          if (item) this.onRowClick(item);
        });
      });
    }

    // Pagination Previous / Next
    const prevBtn = this.container.querySelector('.btn-prev');
    const nextBtn = this.container.querySelector('.btn-next');
    if (prevBtn) {
      prevBtn.addEventListener('click', () => {
        if (this.currentPage > 1) {
          this.currentPage--;
          this.render();
        }
      });
    }
    if (nextBtn) {
      nextBtn.addEventListener('click', () => {
        const totalPages = Math.ceil(this.filteredData.length / this.pageSize);
        if (this.currentPage < totalPages) {
          this.currentPage++;
          this.render();
        }
      });
    }

    // Batch Actions
    const batchBtns = this.container.querySelectorAll('.table-batch-btn');
    batchBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const idx = Number(btn.getAttribute('data-batch-index'));
        const act = this.batchActions[idx];
        if (act && act.action) {
          const selectedItems = this.data.filter(d => this.selectedIds.has(d[this.idKey]));
          act.action(selectedItems, Array.from(this.selectedIds));
        }
      });
    });
  }

  escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}

  /**
 * Enterprise Project CRM - Executive Dashboard View Controller
 * Displays key performance indicator cards, interactive charts, quick action bar,
 * active projects health matrix, and real-time audit feed.
 */






class DashboardView {
  constructor(container) {
    this.container = container;
  }

  render() {
    const pipeline = dataStore.getPipelineMetrics();
    const projects = dataStore.getProjects();
    const tasks = dataStore.getTasks();
    const invoices = dataStore.getInvoices();
    const activities = dataStore.getActivities(8);
    const settings = dataStore.getSettings();

    // Calculate metrics
    const activeProjects = projects.filter(p => p.status !== 'completed');
    const delayedProjects = projects.filter(p => p.status === 'delayed' || p.status === 'at_risk');
    const overdueTasks = tasks.filter(t => t.status !== 'completed' && new Date(t.dueDate) < new Date());
    const totalPaidRevenue = invoices.filter(i => i.status === 'paid').reduce((sum, i) => sum + (Number(i.paidAmount) || 0), 0);
    const outstandingInvoices = invoices.filter(i => i.status === 'pending' || i.status === 'overdue').reduce((sum, i) => sum + (Number(i.total) || 0), 0);

    const currency = settings.currencySymbol || '$';

    let html = `
      <div class="view-header">
        <div>
          <h1 class="view-title">Executive Command Center</h1>
          <p class="view-subtitle">Real-time pipeline analytics, project portfolio health, and financial velocity</p>
        </div>
        <div class="view-header-actions">
          <button class="btn btn-secondary" id="dash-quick-time-btn">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
            Track Time
          </button>
          <button class="btn btn-primary" id="dash-new-deal-btn">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            New Deal
          </button>
        </div>
      </div>

      <!-- KPI METRIC CARDS -->
      <div class="grid grid-4 kpi-grid">
        <div class="card kpi-card">
          <div class="kpi-header">
            <span class="kpi-title">Active Pipeline Value</span>
            <div class="kpi-icon-badge" style="background: rgba(99, 102, 241, 0.15); color: #6366f1;">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>
            </div>
          </div>
          <div class="kpi-value">${currency}${pipeline.totalPipelineValue.toLocaleString()}</div>
          <div class="kpi-footer">
            <span class="badge badge-success">+18.4% vs last month</span>
            <span class="kpi-subtext">Weighted: ${currency}${pipeline.weightedPipelineValue.toLocaleString()}</span>
          </div>
        </div>

        <div class="card kpi-card">
          <div class="kpi-header">
            <span class="kpi-title">Total Revenue Recognized</span>
            <div class="kpi-icon-badge" style="background: rgba(16, 185, 129, 0.15); color: #10b981;">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"/><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"/></svg>
            </div>
          </div>
          <div class="kpi-value">${currency}${totalPaidRevenue.toLocaleString()}</div>
          <div class="kpi-footer">
            <span class="badge badge-warning">${currency}${outstandingInvoices.toLocaleString()} pending</span>
            <span class="kpi-subtext">Win Rate: ${pipeline.winRate}%</span>
          </div>
        </div>

        <div class="card kpi-card">
          <div class="kpi-header">
            <span class="kpi-title">Active Projects</span>
            <div class="kpi-icon-badge" style="background: rgba(6, 182, 212, 0.15); color: #06b6d4;">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>
            </div>
          </div>
          <div class="kpi-value">${activeProjects.length}</div>
          <div class="kpi-footer">
            ${delayedProjects.length > 0 ? `<span class="badge badge-danger">${delayedProjects.length} At Risk</span>` : `<span class="badge badge-success">All On Track</span>`}
            <span class="kpi-subtext">Total: ${projects.length} portfolios</span>
          </div>
        </div>

        <div class="card kpi-card">
          <div class="kpi-header">
            <span class="kpi-title">Tasks & Overdue Queue</span>
            <div class="kpi-icon-badge" style="background: rgba(245, 158, 11, 0.15); color: #f59e0b;">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 11 12 14 22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>
            </div>
          </div>
          <div class="kpi-value">${tasks.filter(t => t.status !== 'completed').length}</div>
          <div class="kpi-footer">
            ${overdueTasks.length > 0 ? `<span class="badge badge-danger">${overdueTasks.length} Overdue</span>` : `<span class="badge badge-success">Zero Overdue</span>`}
            <span class="kpi-subtext">Completed: ${tasks.filter(t => t.status === 'completed').length}</span>
          </div>
        </div>
      </div>

      <!-- MAIN CHARTS SECTION -->
      <div class="grid grid-2" style="margin-top: 24px;">
        <div class="card">
          <div class="card-header">
            <div>
              <h3 class="card-title">Monthly Revenue & Cashflow</h3>
              <p class="card-subtitle">Actual billings vs forecasted milestone recognized value</p>
            </div>
            <div class="chart-legend-inline">
              <span class="legend-dot" style="background:#6366f1;"></span> Revenue
              <span class="legend-dot" style="background:#06b6d4; margin-left:12px;"></span> Target
            </div>
          </div>
          <div class="card-body" id="dash-revenue-chart-container"></div>
        </div>

        <div class="card">
          <div class="card-header">
            <div>
              <h3 class="card-title">Sales Pipeline Conversion Funnel</h3>
              <p class="card-subtitle">Active opportunities progression by stage</p>
            </div>
          </div>
          <div class="card-body" id="dash-funnel-chart-container"></div>
        </div>
      </div>

      <!-- BOTTOM ROW: ACTIVE PROJECTS & AUDIT ACTIVITY FEED -->
      <div class="grid grid-3" style="margin-top: 24px;">
        <!-- ACTIVE PROJECTS (2 COLUMNS) -->
        <div class="card" style="grid-column: span 2;">
          <div class="card-header">
            <div>
              <h3 class="card-title">Project Portfolio Health</h3>
              <p class="card-subtitle">High-priority engagements and delivery progress</p>
            </div>
            <button class="btn btn-sm btn-ghost" id="dash-view-all-projects-btn">View All →</button>
          </div>
          <div class="card-body no-padding">
            <div class="table-container">
              <table class="table">
                <thead>
                  <tr>
                    <th>Project</th>
                    <th>Client</th>
                    <th>Status</th>
                    <th>Budget</th>
                    <th>Progress</th>
                    <th>Health</th>
                  </tr>
                </thead>
                <tbody>
                  ${projects.slice(0, 5).map(p => {
                    const healthColor = p.health >= 90 ? '#10b981' : (p.health >= 75 ? '#f59e0b' : '#ef4444');
                    return `
                      <tr class="table-row cursor-pointer" data-project-id="${p.id}">
                        <td>
                          <div style="font-weight:600; color:var(--text-primary);">${this.escapeHtml(p.name)}</div>
                          <div style="font-size:11px; color:var(--text-muted);">${p.code}</div>
                        </td>
                        <td>${this.escapeHtml(p.accountName)}</td>
                        <td>
                          <span class="badge badge-status badge-${p.status}">${p.status.replace('_', ' ').toUpperCase()}</span>
                        </td>
                        <td>
                          <div style="font-weight:600;">${currency}${p.budget.toLocaleString()}</div>
                          <div style="font-size:11px; color:var(--text-muted);">${currency}${p.spent.toLocaleString()} spent</div>
                        </td>
                        <td style="width: 140px;">
                          <div class="progress-bar-wrapper">
                            <div class="progress-bar-fill" style="width:${p.progress}%; background:${healthColor};"></div>
                          </div>
                          <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">${p.progress}% complete</div>
                        </td>
                        <td>
                          <span style="font-weight:700; color:${healthColor};">${p.health}%</span>
                        </td>
                      </tr>
                    `;
                  }).join('')}
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <!-- REAL-TIME AUDIT FEED (1 COLUMN) -->
        <div class="card">
          <div class="card-header">
            <div>
              <h3 class="card-title">Live Activity Feed</h3>
              <p class="card-subtitle">Real-time audit log & automations</p>
            </div>
          </div>
          <div class="card-body">
            <div class="activity-timeline">
              ${activities.map(act => `
                <div class="activity-item">
                  <div class="activity-icon" style="background:${act.color || '#6366f1'};">
                    ${this.getActivityIcon(act.icon)}
                  </div>
                  <div class="activity-content">
                    <div class="activity-title">${this.escapeHtml(act.title)}</div>
                    <div class="activity-details">${this.escapeHtml(act.details || '')}</div>
                    <div class="activity-meta">
                      <span>${this.escapeHtml(act.user)}</span> •
                      <span>${this.formatTimeAgo(act.timestamp)}</span>
                    </div>
                  </div>
                </div>
              `).join('')}
            </div>
          </div>
        </div>
      </div>
    `;

    this.container.innerHTML = html;
    this.renderCharts();
    this.bindEvents();
  }

  renderCharts() {
    const settings = dataStore.getSettings();
    const currency = settings.currencySymbol || '$';

    // Revenue Area Chart
    const revenueData = [
      { label: 'Mar', value: 240000, value2: 210000 },
      { label: 'Apr', value: 310000, value2: 280000 },
      { label: 'May', value: 290000, value2: 300000 },
      { label: 'Jun', value: 420000, value2: 350000 },
      { label: 'Jul', value: 390000, value2: 380000 },
      { label: 'Aug', value: 520000, value2: 450000 },
      { label: 'Sep (Est)', value: 610000, value2: 500000 }
    ];

    ChartEngine.renderAreaChart('#dash-revenue-chart-container', {
      data: revenueData,
      series: [
        { key: 'value', color: '#6366f1', label: 'Revenue' },
        { key: 'value2', color: '#06b6d4', label: 'Target' }
      ],
      height: 240,
      currency
    });

    // Funnel Chart
    const stages = settings.pipelineStages || [];
    const deals = dataStore.getDeals();
    ChartEngine.renderFunnelChart('#dash-funnel-chart-container', stages, deals);
  }

  bindEvents() {
    const quickTimeBtn = this.container.querySelector('#dash-quick-time-btn');
    if (quickTimeBtn) {
      quickTimeBtn.addEventListener('click', () => {
        window.crmApp.openTimeTrackerModal();
      });
    }

    const newDealBtn = this.container.querySelector('#dash-new-deal-btn');
    if (newDealBtn) {
      newDealBtn.addEventListener('click', () => {
        window.crmApp.openNewDealModal();
      });
    }

    const viewProjectsBtn = this.container.querySelector('#dash-view-all-projects-btn');
    if (viewProjectsBtn) {
      viewProjectsBtn.addEventListener('click', () => {
        window.crmApp.navigate('projects');
      });
    }

    // Row clicks on projects
    const projectRows = this.container.querySelectorAll('[data-project-id]');
    projectRows.forEach(row => {
      row.addEventListener('click', () => {
        const id = row.getAttribute('data-project-id');
        window.crmApp.openProjectDrawer(id);
      });
    });
  }

  getActivityIcon(icon) {
    const icons = {
      briefcase: `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"/><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"/></svg>`,
      ticket: `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5"><path d="M2 9a3 3 0 0 1 0 6v2a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-2a3 3 0 0 1 0-6V7a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2z"/></svg>`,
      clock: `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>`,
      zap: `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>`,
      'check-circle': `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>`,
      'user-plus': `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5"><path d="M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="8.5" cy="7" r="4"/><line x1="20" y1="8" x2="20" y2="14"/><line x1="23" y1="11" x2="17" y2="11"/></svg>`,
      award: `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5"><circle cx="12" cy="8" r="7"/><polyline points="8.21 13.89 7 23 12 20 17 23 15.79 13.88"/></svg>`,
      'dollar-sign': `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>`
    };
    return icons[icon] || icons.briefcase;
  }

  formatTimeAgo(isoString) {
    if (!isoString) return 'recently';
    const diff = Math.floor((Date.now() - new Date(isoString).getTime()) / 1000);
    if (diff < 60) return `${diff}s ago`;
    if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
    if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
    return `${Math.floor(diff / 86400)}d ago`;
  }

  escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}

  /**
 * Enterprise Project CRM - Deals & Sales Pipeline View Controller
 * Features: Interactive Drag-and-Drop Kanban Board, Table Grid View,
 * Deal 360° Drawer, Probability Calculation, and Stage History Stepper.
 */






class DealsView {
  constructor(container) {
    this.container = container;
    this.viewMode = 'kanban'; // 'kanban' or 'table'
    this.tableGrid = null;
  }

  render() {
    const deals = dataStore.getDeals();
    const settings = dataStore.getSettings();
    const stages = settings.pipelineStages || [];
    const metrics = dataStore.getPipelineMetrics();
    const currency = settings.currencySymbol || '$';

    let html = `
      <div class="view-header">
        <div>
          <h1 class="view-title">Deals & Opportunities Pipeline</h1>
          <p class="view-subtitle">
            Active: <strong>${currency}${metrics.totalPipelineValue.toLocaleString()}</strong> (${metrics.openCount} deals) • 
            Weighted: <strong>${currency}${metrics.weightedPipelineValue.toLocaleString()}</strong> • 
            Won: <strong style="color:var(--color-success);">${currency}${metrics.wonValue.toLocaleString()}</strong> (${metrics.winRate}% win rate)
          </p>
        </div>
        <div class="view-header-actions">
          <div class="view-mode-toggle">
            <button class="btn btn-sm ${this.viewMode === 'kanban' ? 'btn-primary' : 'btn-secondary'}" id="deals-toggle-kanban">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="7" height="18" rx="1"/><rect x="14" y="3" width="7" height="18" rx="1"/></svg>
              Kanban
            </button>
            <button class="btn btn-sm ${this.viewMode === 'table' ? 'btn-primary' : 'btn-secondary'}" id="deals-toggle-table">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg>
              Table
            </button>
          </div>
          <button class="btn btn-secondary" id="deals-export-csv-btn">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
            Export CSV
          </button>
          <button class="btn btn-primary" id="deals-new-deal-btn">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            New Opportunity
          </button>
        </div>
      </div>

      <div id="deals-view-content" class="animate-fade-in"></div>
    `;

    this.container.innerHTML = html;
    this.renderContent();
    this.bindHeaderEvents();
  }

  renderContent() {
    const contentEl = this.container.querySelector('#deals-view-content');
    if (!contentEl) return;

    if (this.viewMode === 'kanban') {
      this.renderKanban(contentEl);
    } else {
      this.renderTable(contentEl);
    }
  }

  renderKanban(container) {
    const deals = dataStore.getDeals();
    const settings = dataStore.getSettings();
    const stages = settings.pipelineStages || [];
    const currency = settings.currencySymbol || '$';

    let html = `
      <div class="kanban-board" id="deals-kanban-board">
        ${stages.map(stage => {
          const stageDeals = deals.filter(d => d.stage === stage.id);
          const stageTotal = stageDeals.reduce((sum, d) => sum + (Number(d.amount) || 0), 0);

          return `
            <div class="kanban-column" data-stage-id="${stage.id}">
              <div class="kanban-column-header">
                <div class="kanban-column-title-wrap">
                  <span class="kanban-stage-indicator" style="background:${stage.color};"></span>
                  <h4 class="kanban-column-title">${this.escapeHtml(stage.name)}</h4>
                  <span class="kanban-count-pill">${stageDeals.length}</span>
                </div>
                <div class="kanban-column-amount">${currency}${stageTotal.toLocaleString()}</div>
              </div>

              <div class="kanban-cards-container" data-stage-id="${stage.id}">
                ${stageDeals.map(deal => `
                  <div class="kanban-card cursor-grab animate-scale-up" draggable="true" data-deal-id="${deal.id}">
                    <div class="kanban-card-header">
                      <span class="badge badge-priority badge-${deal.priority || 'medium'}">${(deal.priority || 'medium').toUpperCase()}</span>
                      <span class="kanban-card-date">${this.formatDate(deal.expectedCloseDate)}</span>
                    </div>

                    <div class="kanban-card-title">${this.escapeHtml(deal.title)}</div>
                    
                    <div class="kanban-card-account">
                      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"/><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"/></svg>
                      <span>${this.escapeHtml(deal.accountName)}</span>
                    </div>

                    <div class="kanban-card-footer">
                      <div class="kanban-card-amount">
                        ${currency}${Number(deal.amount || 0).toLocaleString()}
                        <span class="kanban-prob-hint">(${deal.probability}%)</span>
                      </div>
                      <div class="avatar-pill" title="Assigned to ${deal.assignedUser?.name || 'Unassigned'}">
                        ${deal.assignedUser?.initials || 'UN'}
                      </div>
                    </div>
                  </div>
                `).join('')}

                ${stageDeals.length === 0 ? `
                  <div class="kanban-empty-dropzone">Drop deals here</div>
                ` : ''}
              </div>
            </div>
          `;
        }).join('')}
      </div>
    `;

    container.innerHTML = html;
    this.initDragAndDrop();
    this.bindCardClicks();
  }

  renderTable(container) {
    const deals = dataStore.getDeals();
    const settings = dataStore.getSettings();
    const currency = settings.currencySymbol || '$';

    container.innerHTML = '<div id="deals-table-container"></div>';

    this.tableGrid = new TableGrid({
      container: '#deals-table-container',
      data: deals,
      pageSize: 10,
      defaultSortKey: 'amount',
      defaultSortAsc: false,
      columns: [
        {
          key: 'title',
          label: 'Opportunity',
          sortable: true,
          render: (val, item) => `
            <div>
              <strong style="color:var(--text-primary); font-size:13px;">${this.escapeHtml(val)}</strong>
              <div style="font-size:11px; color:var(--text-muted);">${item.tags?.join(', ') || ''}</div>
            </div>
          `
        },
        {
          key: 'accountName',
          label: 'Company / Account',
          sortable: true,
          render: (val) => `<span style="font-weight:600;">${this.escapeHtml(val)}</span>`
        },
        {
          key: 'stage',
          label: 'Stage',
          sortable: true,
          render: (val) => {
            const st = settings.pipelineStages.find(s => s.id === val);
            const color = st ? st.color : '#6366f1';
            const name = st ? st.name : val;
            return `<span class="badge" style="background:rgba(99,102,241,0.15); color:${color}; font-weight:700;">${name}</span>`;
          }
        },
        {
          key: 'amount',
          label: 'Value',
          sortable: true,
          render: (val) => `<strong style="font-size:13px;">${currency}${Number(val).toLocaleString()}</strong>`
        },
        {
          key: 'probability',
          label: 'Probability',
          sortable: true,
          render: (val, item) => `
            <div>
              <span>${val}%</span>
              <div style="font-size:11px; color:var(--text-muted);">Weighted: ${currency}${Number(item.weightedAmount || 0).toLocaleString()}</div>
            </div>
          `
        },
        {
          key: 'expectedCloseDate',
          label: 'Close Date',
          sortable: true,
          render: (val) => this.formatDate(val)
        },
        {
          key: 'assignedTo',
          label: 'Rep',
          sortable: true,
          render: (val, item) => `
            <div style="display:flex; align-items:center; gap:6px;">
              <span class="avatar-pill">${item.assignedUser?.initials || 'SC'}</span>
              <span>${item.assignedUser?.name || 'Sophia Chen'}</span>
            </div>
          `
        }
      ],
      onRowClick: (deal) => {
        this.openDealDrawer(deal.id);
      },
      batchActions: [
        {
          label: 'Delete Selected',
          class: 'btn-danger',
          action: (items, ids) => {
            modal.confirm({
              title: `Delete ${ids.length} Deals?`,
              message: 'This will permanently remove the selected deals from your CRM pipeline.',
              onConfirm: () => {
                ids.forEach(id => dataStore.deleteDeal(id));
                toast.success('Deals deleted', `Successfully removed ${ids.length} records.`);
                this.render();
              }
            });
          }
        }
      ]
    });
  }

  initDragAndDrop() {
    const cards = this.container.querySelectorAll('.kanban-card');
    const containers = this.container.querySelectorAll('.kanban-cards-container');

    cards.forEach(card => {
      card.addEventListener('dragstart', (e) => {
        card.classList.add('is-dragging');
        e.dataTransfer.setData('text/plain', card.getAttribute('data-deal-id'));
        e.dataTransfer.effectAllowed = 'move';
      });

      card.addEventListener('dragend', () => {
        card.classList.remove('is-dragging');
        containers.forEach(c => c.classList.remove('drag-over'));
      });
    });

    containers.forEach(dropzone => {
      dropzone.addEventListener('dragover', (e) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        dropzone.classList.add('drag-over');
      });

      dropzone.addEventListener('dragleave', (e) => {
        if (!dropzone.contains(e.relatedTarget)) {
          dropzone.classList.remove('drag-over');
        }
      });

      dropzone.addEventListener('drop', (e) => {
        e.preventDefault();
        dropzone.classList.remove('drag-over');
        const dealId = e.dataTransfer.getData('text/plain');
        const targetStage = dropzone.getAttribute('data-stage-id');

        if (dealId && targetStage) {
          const updated = dataStore.updateDealStage(dealId, targetStage);
          if (updated) {
            toast.success('Stage Updated', `Deal "${updated.title}" moved to ${targetStage.replace('_', ' ').toUpperCase()}`);
            this.render();
          }
        }
      });
    });
  }

  bindCardClicks() {
    const cards = this.container.querySelectorAll('.kanban-card');
    cards.forEach(card => {
      card.addEventListener('click', (e) => {
        const id = card.getAttribute('data-deal-id');
        this.openDealDrawer(id);
      });
    });
  }

  bindHeaderEvents() {
    const toggleKanban = this.container.querySelector('#deals-toggle-kanban');
    const toggleTable = this.container.querySelector('#deals-toggle-table');
    const exportBtn = this.container.querySelector('#deals-export-csv-btn');
    const newDealBtn = this.container.querySelector('#deals-new-deal-btn');

    if (toggleKanban) {
      toggleKanban.addEventListener('click', () => {
        this.viewMode = 'kanban';
        this.render();
      });
    }

    if (toggleTable) {
      toggleTable.addEventListener('click', () => {
        this.viewMode = 'table';
        this.render();
      });
    }

    if (exportBtn) {
      exportBtn.addEventListener('click', () => {
        const csv = dataStore.exportCollectionCSV('deals');
        this.downloadCSV(csv, 'crm-deals-export.csv');
        toast.info('CSV Exported', 'Downloaded deals data to CSV.');
      });
    }

    if (newDealBtn) {
      newDealBtn.addEventListener('click', () => {
        this.openNewDealModal();
      });
    }
  }

  openDealDrawer(dealId) {
    const deal = dataStore.getDealById(dealId);
    if (!deal) return;

    const settings = dataStore.getSettings();
    const stages = settings.pipelineStages || [];
    const currency = settings.currencySymbol || '$';
    const currentStageIdx = stages.findIndex(s => s.id === deal.stage);

    const drawerContent = `
      <div class="deal-drawer-container">
        <!-- STAGE STEPPER -->
        <div class="deal-stepper">
          ${stages.map((st, idx) => {
            const isCompleted = idx < currentStageIdx;
            const isCurrent = idx === currentStageIdx;
            return `
              <div class="stepper-step ${isCurrent ? 'step-current' : (isCompleted ? 'step-completed' : '')}" data-step-stage="${st.id}">
                <div class="step-dot" style="background:${isCurrent || isCompleted ? st.color : 'var(--border-color)'};"></div>
                <div class="step-label">${st.name}</div>
              </div>
            `;
          }).join('')}
        </div>

        <!-- DEAL METRICS STRIP -->
        <div class="grid grid-3" style="margin: 20px 0; gap:12px;">
          <div class="card stat-box" style="padding:14px;">
            <div class="stat-box-label">Deal Value</div>
            <div class="stat-box-value">${currency}${deal.amount.toLocaleString()}</div>
          </div>
          <div class="card stat-box" style="padding:14px;">
            <div class="stat-box-label">Win Probability</div>
            <div class="stat-box-value" style="color:var(--color-primary);">${deal.probability}%</div>
          </div>
          <div class="card stat-box" style="padding:14px;">
            <div class="stat-box-label">Weighted Value</div>
            <div class="stat-box-value">${currency}${deal.weightedAmount.toLocaleString()}</div>
          </div>
        </div>

        <!-- DETAILS TAB -->
        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Client Account</label>
            <div class="readonly-pill">${this.escapeHtml(deal.accountName)}</div>
          </div>
          <div class="form-group">
            <label class="form-label">Primary Contact</label>
            <div class="readonly-pill">${this.escapeHtml(deal.contactName || 'None assigned')}</div>
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Expected Close Date</label>
            <div class="readonly-pill">${deal.expectedCloseDate || 'Not set'}</div>
          </div>
          <div class="form-group">
            <label class="form-label">Deal Owner</label>
            <div class="readonly-pill">${deal.assignedUser?.name || 'Sophia Chen'}</div>
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Notes & Next Steps</label>
          <div class="deal-notes-box">${this.escapeHtml(deal.notes || 'No notes added yet.')}</div>
        </div>

        <!-- STAGE HISTORY LOG -->
        <div class="section-divider" style="margin:20px 0;"></div>
        <h4 style="font-size:14px; font-weight:700; margin-bottom:12px;">Stage History & Timeline</h4>
        <div class="activity-timeline">
          ${(deal.history || []).map(h => `
            <div class="activity-item">
              <div class="activity-icon" style="background:#6366f1;">
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
              </div>
              <div class="activity-content">
                <div class="activity-title">${this.escapeHtml(h.stage.toUpperCase().replace('_', ' '))}</div>
                <div class="activity-details">${this.escapeHtml(h.note || '')}</div>
                <div class="activity-meta">${h.date}</div>
              </div>
            </div>
          `).join('')}
        </div>

        <!-- DRAWER ACTIONS -->
        <div style="display:flex; justify-content:space-between; align-items:center; margin-top:30px; padding-top:16px; border-top:1px solid var(--border-color);">
          <button class="btn btn-danger btn-sm" id="drawer-delete-deal-btn">Delete Opportunity</button>
          <div style="display:flex; gap:10px;">
            <button class="btn btn-secondary btn-sm" id="drawer-edit-deal-btn">Edit Deal</button>
            ${deal.stage !== 'closed_won' ? `
              <button class="btn btn-success btn-sm" id="drawer-mark-won-btn">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
                Mark as Closed Won
              </button>
            ` : ''}
          </div>
        </div>
      </div>
    `;

    modal.openDrawer({
      title: deal.title,
      subtitle: `${deal.accountName} • Priority: ${deal.priority.toUpperCase()}`,
      content: drawerContent,
      onOpen: (el) => {
        // Step click transitions
        const steps = el.querySelectorAll('[data-step-stage]');
        steps.forEach(st => {
          st.addEventListener('click', () => {
            const newStage = st.getAttribute('data-step-stage');
            dataStore.updateDealStage(deal.id, newStage);
            modal.closeDrawer();
            toast.success('Stage Updated', `Moved deal to ${newStage.replace('_', ' ').toUpperCase()}`);
            this.render();
          });
        });

        // Mark won
        const wonBtn = el.querySelector('#drawer-mark-won-btn');
        if (wonBtn) {
          wonBtn.addEventListener('click', () => {
            dataStore.updateDealStage(deal.id, 'closed_won');
            modal.closeDrawer();
            toast.success('🎉 Deal Won!', `Congratulations! ${deal.title} marked as Closed Won.`);
            this.render();
          });
        }

        // Delete
        const delBtn = el.querySelector('#drawer-delete-deal-btn');
        if (delBtn) {
          delBtn.addEventListener('click', () => {
            modal.confirm({
              title: `Delete "${deal.title}"?`,
              message: 'Are you sure you want to remove this deal from the system?',
              onConfirm: () => {
                dataStore.deleteDeal(deal.id);
                modal.closeDrawer();
                toast.success('Deal Deleted', 'The deal was removed.');
                this.render();
              }
            });
          });
        }

        // Edit
        const editBtn = el.querySelector('#drawer-edit-deal-btn');
        if (editBtn) {
          editBtn.addEventListener('click', () => {
            modal.closeDrawer();
            this.openEditDealModal(deal);
          });
        }
      }
    });
  }

  openNewDealModal() {
    const accounts = dataStore.getAccounts();
    const settings = dataStore.getSettings();
    const stages = settings.pipelineStages || [];
    const team = dataStore.getTeamMembers();

    const formHtml = `
      <form id="new-deal-form">
        <div class="form-group">
          <label class="form-label required">Opportunity Title</label>
          <input type="text" name="title" class="input" placeholder="e.g. Cloud Security License & Migration" required />
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Client Account</label>
            <select name="accountId" class="input" required>
              <option value="">-- Select Company --</option>
              ${accounts.map(a => `<option value="${a.id}">${this.escapeHtml(a.name)}</option>`).join('')}
            </select>
          </div>
          <div class="form-group">
            <label class="form-label required">Deal Amount ($)</label>
            <input type="number" name="amount" class="input" placeholder="150000" min="0" required />
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Pipeline Stage</label>
            <select name="stage" class="input" required>
              ${stages.map(s => `<option value="${s.id}">${s.name} (${s.probability}%)</option>`).join('')}
            </select>
          </div>
          <div class="form-group">
            <label class="form-label required">Expected Close Date</label>
            <input type="date" name="expectedCloseDate" class="input" required value="${new Date(Date.now() + 30 * 24 * 3600 * 1000).toISOString().split('T')[0]}" />
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Assigned Account Executive</label>
            <select name="assignedTo" class="input">
              ${team.map(u => `<option value="${u.id}">${u.name} (${u.role})</option>`).join('')}
            </select>
          </div>
          <div class="form-group">
            <label class="form-label">Priority</label>
            <select name="priority" class="input">
              <option value="medium">Medium</option>
              <option value="high">High</option>
              <option value="urgent">Urgent</option>
              <option value="low">Low</option>
            </select>
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Strategic Notes</label>
          <textarea name="notes" class="input" rows="3" placeholder="Key decision makers, requirements, and next steps..."></textarea>
        </div>
      </form>
    `;

    modal.openModal({
      title: 'Create New Opportunity',
      content: formHtml,
      confirmText: 'Create Opportunity',
      onConfirm: (formData) => {
        if (!formData) return false;
        const accountId = formData.get('accountId');
        const account = accounts.find(a => a.id === accountId);
        const assignedToId = formData.get('assignedTo');
        const user = team.find(u => u.id === assignedToId);

        const newDeal = {
          title: formData.get('title'),
          accountId: accountId,
          accountName: account ? account.name : 'Client',
          amount: Number(formData.get('amount')) || 0,
          stage: formData.get('stage'),
          expectedCloseDate: formData.get('expectedCloseDate'),
          priority: formData.get('priority') || 'medium',
          notes: formData.get('notes'),
          assignedTo: assignedToId,
          assignedUser: user ? { name: user.name, initials: user.initials } : { name: 'Sophia Chen', initials: 'SC' },
          tags: ['Inbound', 'New Deal']
        };

        dataStore.saveDeal(newDeal);
        toast.success('Opportunity Created', `"${newDeal.title}" added to pipeline.`);
        this.render();
        return true;
      }
    });
  }

  openEditDealModal(deal) {
    const accounts = dataStore.getAccounts();
    const settings = dataStore.getSettings();
    const stages = settings.pipelineStages || [];
    const team = dataStore.getTeamMembers();

    const formHtml = `
      <form id="edit-deal-form">
        <div class="form-group">
          <label class="form-label required">Opportunity Title</label>
          <input type="text" name="title" class="input" value="${this.escapeHtml(deal.title)}" required />
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Client Account</label>
            <select name="accountId" class="input" required>
              ${accounts.map(a => `<option value="${a.id}" ${a.id === deal.accountId ? 'selected' : ''}>${this.escapeHtml(a.name)}</option>`).join('')}
            </select>
          </div>
          <div class="form-group">
            <label class="form-label required">Deal Amount ($)</label>
            <input type="number" name="amount" class="input" value="${deal.amount}" min="0" required />
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Pipeline Stage</label>
            <select name="stage" class="input" required>
              ${stages.map(s => `<option value="${s.id}" ${s.id === deal.stage ? 'selected' : ''}>${s.name} (${s.probability}%)</option>`).join('')}
            </select>
          </div>
          <div class="form-group">
            <label class="form-label required">Expected Close Date</label>
            <input type="date" name="expectedCloseDate" class="input" required value="${deal.expectedCloseDate || ''}" />
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Priority</label>
            <select name="priority" class="input">
              <option value="low" ${deal.priority === 'low' ? 'selected' : ''}>Low</option>
              <option value="medium" ${deal.priority === 'medium' ? 'selected' : ''}>Medium</option>
              <option value="high" ${deal.priority === 'high' ? 'selected' : ''}>High</option>
              <option value="urgent" ${deal.priority === 'urgent' ? 'selected' : ''}>Urgent</option>
            </select>
          </div>
          <div class="form-group">
            <label class="form-label">Assigned Rep</label>
            <select name="assignedTo" class="input">
              ${team.map(u => `<option value="${u.id}" ${u.id === deal.assignedTo ? 'selected' : ''}>${u.name}</option>`).join('')}
            </select>
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Notes</label>
          <textarea name="notes" class="input" rows="3">${this.escapeHtml(deal.notes || '')}</textarea>
        </div>
      </form>
    `;

    modal.openModal({
      title: 'Edit Opportunity',
      content: formHtml,
      confirmText: 'Save Changes',
      onConfirm: (formData) => {
        if (!formData) return false;
        const accountId = formData.get('accountId');
        const account = accounts.find(a => a.id === accountId);
        const assignedToId = formData.get('assignedTo');
        const user = team.find(u => u.id === assignedToId);

        const updated = {
          ...deal,
          title: formData.get('title'),
          accountId: accountId,
          accountName: account ? account.name : deal.accountName,
          amount: Number(formData.get('amount')) || 0,
          stage: formData.get('stage'),
          expectedCloseDate: formData.get('expectedCloseDate'),
          priority: formData.get('priority'),
          notes: formData.get('notes'),
          assignedTo: assignedToId,
          assignedUser: user ? { name: user.name, initials: user.initials } : deal.assignedUser
        };

        dataStore.saveDeal(updated);
        toast.success('Changes Saved', `Updated "${updated.title}"`);
        this.render();
        return true;
      }
    });
  }

  downloadCSV(csvContent, filename) {
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = filename;
    link.click();
  }

  formatDate(dateStr) {
    if (!dateStr) return 'TBD';
    const d = new Date(dateStr);
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  }

  escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}

  /**
 * Enterprise Project CRM - Projects & Gantt Timeline View Controller
 * Features: Portfolio Cards, Interactive SVG Gantt Timeline View,
 * Milestone Tracking, Budget Burnup, and Project Workspace Drawer.
 */






class ProjectsView {
  constructor(container) {
    this.container = container;
    this.viewMode = 'cards'; // 'cards', 'gantt', 'table'
  }

  render() {
    const projects = dataStore.getProjects();
    const settings = dataStore.getSettings();
    const currency = settings.currencySymbol || '$';

    const totalBudget = projects.reduce((sum, p) => sum + (Number(p.budget) || 0), 0);
    const totalSpent = projects.reduce((sum, p) => sum + (Number(p.spent) || 0), 0);
    const avgHealth = Math.round(projects.reduce((sum, p) => sum + (Number(p.health) || 85), 0) / Math.max(1, projects.length));

    let html = `
      <div class="view-header">
        <div>
          <h1 class="view-title">Project Portfolio & Timeline</h1>
          <p class="view-subtitle">
            <strong>${projects.length}</strong> Total Portfolios • 
            Budget: <strong>${currency}${totalBudget.toLocaleString()}</strong> • 
            Spent: <strong>${currency}${totalSpent.toLocaleString()}</strong> • 
            Avg Health: <strong style="color:var(--color-success);">${avgHealth}%</strong>
          </p>
        </div>
        <div class="view-header-actions">
          <div class="view-mode-toggle">
            <button class="btn btn-sm ${this.viewMode === 'cards' ? 'btn-primary' : 'btn-secondary'}" id="proj-toggle-cards">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/></svg>
              Cards
            </button>
            <button class="btn btn-sm ${this.viewMode === 'gantt' ? 'btn-primary' : 'btn-secondary'}" id="proj-toggle-gantt">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="4" y1="6" x2="16" y2="6"/><line x1="8" y1="12" x2="20" y2="12"/><line x1="6" y1="18" x2="18" y2="18"/></svg>
              Gantt Timeline
            </button>
            <button class="btn btn-sm ${this.viewMode === 'table' ? 'btn-primary' : 'btn-secondary'}" id="proj-toggle-table">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg>
              Table
            </button>
          </div>
          <button class="btn btn-primary" id="proj-new-project-btn">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            New Project
          </button>
        </div>
      </div>

      <div id="projects-view-content" class="animate-fade-in"></div>
    `;

    this.container.innerHTML = html;
    this.renderContent();
    this.bindHeaderEvents();
  }

  renderContent() {
    const contentEl = this.container.querySelector('#projects-view-content');
    if (!contentEl) return;

    if (this.viewMode === 'cards') {
      this.renderCards(contentEl);
    } else if (this.viewMode === 'gantt') {
      this.renderGantt(contentEl);
    } else {
      this.renderTable(contentEl);
    }
  }

  renderCards(container) {
    const projects = dataStore.getProjects();
    const settings = dataStore.getSettings();
    const currency = settings.currencySymbol || '$';

    let html = `
      <div class="grid grid-3" style="gap: 20px;">
        ${projects.map(p => {
          const healthColor = p.health >= 90 ? '#10b981' : (p.health >= 75 ? '#f59e0b' : '#ef4444');
          const completedMs = (p.milestones || []).filter(m => m.completed).length;
          const totalMs = (p.milestones || []).length;

          return `
            <div class="card project-card cursor-pointer animate-scale-up" data-proj-id="${p.id}">
              <div class="project-card-header">
                <div>
                  <span class="badge badge-status badge-${p.status}">${p.status.replace('_', ' ').toUpperCase()}</span>
                  <div class="project-code-tag">${p.code}</div>
                </div>
                <div class="health-score-circle" style="border-color:${healthColor}; color:${healthColor};">
                  ${p.health}%
                </div>
              </div>

              <h3 class="project-card-title">${this.escapeHtml(p.name)}</h3>
              <p class="project-card-client">${this.escapeHtml(p.accountName)}</p>

              <div class="project-progress-section">
                <div style="display:flex; justify-content:space-between; font-size:12px; margin-bottom:4px;">
                  <span style="color:var(--text-muted);">Overall Progress</span>
                  <strong style="color:var(--text-primary);">${p.progress}%</strong>
                </div>
                <div class="progress-bar-wrapper">
                  <div class="progress-bar-fill" style="width:${p.progress}%; background:${healthColor};"></div>
                </div>
              </div>

              <div class="project-card-meta-grid">
                <div>
                  <div class="meta-label">Budget</div>
                  <div class="meta-val">${currency}${p.budget.toLocaleString()}</div>
                </div>
                <div>
                  <div class="meta-label">Spent</div>
                  <div class="meta-val">${currency}${p.spent.toLocaleString()}</div>
                </div>
                <div>
                  <div class="meta-label">Milestones</div>
                  <div class="meta-val">${completedMs} / ${totalMs}</div>
                </div>
              </div>

              <div class="project-card-footer">
                <div class="project-date-range">
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
                  <span>${p.startDate} → ${p.endDate}</span>
                </div>
                <div class="avatar-stack">
                  ${(p.teamMembers || []).map(uId => {
                    const u = dataStore.getTeamMemberById(uId);
                    return `<span class="avatar-mini" title="${u ? u.name : 'Team Member'}">${u ? u.initials : 'TM'}</span>`;
                  }).join('')}
                </div>
              </div>
            </div>
          `;
        }).join('')}
      </div>
    `;

    container.innerHTML = html;
    this.bindCardClicks();
  }

  renderGantt(container) {
    const projects = dataStore.getProjects();
    const tasks = dataStore.getTasks();

    // Timeline range: August 2025 - January 2026 (6 months)
    const months = [
      { name: 'Aug 2025', days: 31, start: new Date('2025-08-01') },
      { name: 'Sep 2025', days: 30, start: new Date('2025-09-01') },
      { name: 'Oct 2025', days: 31, start: new Date('2025-10-01') },
      { name: 'Nov 2025', days: 30, start: new Date('2025-11-01') },
      { name: 'Dec 2025', days: 31, start: new Date('2025-12-01') },
      { name: 'Jan 2026', days: 31, start: new Date('2026-01-01') }
    ];

    const timelineStart = new Date('2025-08-01').getTime();
    const timelineEnd = new Date('2026-01-31').getTime();
    const totalDuration = timelineEnd - timelineStart;

    let html = `
      <div class="card gantt-wrapper">
        <div class="gantt-header-row">
          <div class="gantt-project-col">Project & Milestones</div>
          <div class="gantt-timeline-col">
            <div class="gantt-months-bar">
              ${months.map(m => `
                <div class="gantt-month-header" style="flex:${m.days};">
                  ${m.name}
                </div>
              `).join('')}
            </div>
          </div>
        </div>

        <div class="gantt-body">
          ${projects.map(p => {
            const pStart = Math.max(timelineStart, new Date(p.startDate || '2025-08-01').getTime());
            const pEnd = Math.min(timelineEnd, new Date(p.endDate || '2025-12-31').getTime());
            const leftPct = ((pStart - timelineStart) / totalDuration) * 100;
            const widthPct = Math.max(2, ((pEnd - pStart) / totalDuration) * 100);
            const healthColor = p.health >= 90 ? '#10b981' : (p.health >= 75 ? '#f59e0b' : '#ef4444');

            return `
              <div class="gantt-project-row">
                <div class="gantt-project-cell cursor-pointer" data-proj-id="${p.id}">
                  <div style="font-weight:700; color:var(--text-primary); font-size:13px;">${this.escapeHtml(p.code)}: ${this.escapeHtml(p.name)}</div>
                  <div style="font-size:11px; color:var(--text-muted);">${this.escapeHtml(p.accountName)} • ${p.progress}%</div>
                </div>
                <div class="gantt-timeline-cell">
                  <!-- Project Main Bar -->
                  <div class="gantt-bar cursor-pointer" style="left:${leftPct}%; width:${widthPct}%; background:${healthColor};" data-proj-id="${p.id}">
                    <div class="gantt-bar-fill" style="width:${p.progress}%;"></div>
                    <span class="gantt-bar-label">${p.progress}%</span>
                  </div>

                  <!-- Milestones -->
                  ${(p.milestones || []).map(m => {
                    const mDate = new Date(m.dueDate).getTime();
                    if (mDate >= timelineStart && mDate <= timelineEnd) {
                      const mLeft = ((mDate - timelineStart) / totalDuration) * 100;
                      return `
                        <div class="gantt-milestone-marker ${m.completed ? 'completed' : ''}" style="left:${mLeft}%;" title="Milestone: ${this.escapeHtml(m.title)} (${m.dueDate})">
                          <span class="milestone-diamond"></span>
                        </div>
                      `;
                    }
                    return '';
                  }).join('')}
                </div>
              </div>
            `;
          }).join('')}
        </div>
      </div>
    `;

    container.innerHTML = html;
    this.bindCardClicks();
  }

  renderTable(container) {
    const projects = dataStore.getProjects();
    const settings = dataStore.getSettings();
    const currency = settings.currencySymbol || '$';

    container.innerHTML = '<div id="projects-table-container"></div>';

    new TableGrid({
      container: '#projects-table-container',
      data: projects,
      pageSize: 10,
      defaultSortKey: 'budget',
      defaultSortAsc: false,
      columns: [
        {
          key: 'name',
          label: 'Project Name',
          sortable: true,
          render: (val, item) => `
            <div>
              <strong style="color:var(--text-primary);">${this.escapeHtml(val)}</strong>
              <div style="font-size:11px; color:var(--text-muted);">${item.code}</div>
            </div>
          `
        },
        {
          key: 'accountName',
          label: 'Client Account',
          sortable: true,
          render: (val) => `<span style="font-weight:600;">${this.escapeHtml(val)}</span>`
        },
        {
          key: 'status',
          label: 'Status',
          sortable: true,
          render: (val) => `<span class="badge badge-status badge-${val}">${val.replace('_', ' ').toUpperCase()}</span>`
        },
        {
          key: 'health',
          label: 'Health',
          sortable: true,
          render: (val) => {
            const color = val >= 90 ? '#10b981' : (val >= 75 ? '#f59e0b' : '#ef4444');
            return `<strong style="color:${color};">${val}%</strong>`;
          }
        },
        {
          key: 'progress',
          label: 'Progress',
          sortable: true,
          render: (val, item) => `
            <div style="width:120px;">
              <div class="progress-bar-wrapper">
                <div class="progress-bar-fill" style="width:${val}%; background:${item.health >= 85 ? '#10b981' : '#f59e0b'};"></div>
              </div>
              <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">${val}% done</div>
            </div>
          `
        },
        {
          key: 'budget',
          label: 'Budget',
          sortable: true,
          render: (val, item) => `
            <div>
              <strong>${currency}${Number(val).toLocaleString()}</strong>
              <div style="font-size:11px; color:var(--text-muted);">${currency}${Number(item.spent || 0).toLocaleString()} spent</div>
            </div>
          `
        },
        {
          key: 'endDate',
          label: 'Deadline',
          sortable: true,
          render: (val) => val || 'TBD'
        }
      ],
      onRowClick: (p) => {
        this.openProjectDrawer(p.id);
      }
    });
  }

  bindCardClicks() {
    const cards = this.container.querySelectorAll('[data-proj-id]');
    cards.forEach(card => {
      card.addEventListener('click', () => {
        const id = card.getAttribute('data-proj-id');
        this.openProjectDrawer(id);
      });
    });
  }

  bindHeaderEvents() {
    const toggleCards = this.container.querySelector('#proj-toggle-cards');
    const toggleGantt = this.container.querySelector('#proj-toggle-gantt');
    const toggleTable = this.container.querySelector('#proj-toggle-table');
    const newProjBtn = this.container.querySelector('#proj-new-project-btn');

    if (toggleCards) {
      toggleCards.addEventListener('click', () => {
        this.viewMode = 'cards';
        this.render();
      });
    }

    if (toggleGantt) {
      toggleGantt.addEventListener('click', () => {
        this.viewMode = 'gantt';
        this.render();
      });
    }

    if (toggleTable) {
      toggleTable.addEventListener('click', () => {
        this.viewMode = 'table';
        this.render();
      });
    }

    if (newProjBtn) {
      newProjBtn.addEventListener('click', () => {
        this.openNewProjectModal();
      });
    }
  }

  openProjectDrawer(projectId) {
    const p = dataStore.getProjectById(projectId);
    if (!p) return;

    const settings = dataStore.getSettings();
    const currency = settings.currencySymbol || '$';
    const projectTasks = dataStore.getTasks().filter(t => t.projectId === projectId);
    const healthColor = p.health >= 90 ? '#10b981' : (p.health >= 75 ? '#f59e0b' : '#ef4444');

    const drawerContent = `
      <div class="project-drawer-container">
        <div class="grid grid-3" style="margin-bottom: 20px; gap:12px;">
          <div class="card stat-box" style="padding:14px;">
            <div class="stat-box-label">Total Budget</div>
            <div class="stat-box-value">${currency}${p.budget.toLocaleString()}</div>
          </div>
          <div class="card stat-box" style="padding:14px;">
            <div class="stat-box-label">Budget Burned</div>
            <div class="stat-box-value" style="color:#f59e0b;">${currency}${p.spent.toLocaleString()}</div>
          </div>
          <div class="card stat-box" style="padding:14px;">
            <div class="stat-box-label">Health Index</div>
            <div class="stat-box-value" style="color:${healthColor};">${p.health}%</div>
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Project Description</label>
          <div class="deal-notes-box">${this.escapeHtml(p.description || 'No description provided.')}</div>
        </div>

        <!-- MILESTONES CHECKLIST -->
        <div class="section-divider" style="margin:20px 0;"></div>
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;">
          <h4 style="font-size:14px; font-weight:700;">Milestones & Deliverables</h4>
          <span class="badge badge-info">${(p.milestones || []).filter(m => m.completed).length} / ${(p.milestones || []).length} Completed</span>
        </div>

        <div class="milestones-list" style="display:flex; flex-direction:column; gap:8px;">
          ${(p.milestones || []).map(m => `
            <div class="milestone-item ${m.completed ? 'milestone-done' : ''}" style="display:flex; align-items:center; justify-content:space-between; padding:10px 14px; background:var(--bg-card-hover); border-radius:8px;">
              <label style="display:flex; align-items:center; gap:10px; cursor:pointer; font-size:13px; font-weight:500;">
                <input type="checkbox" class="crm-checkbox milestone-checkbox" data-milestone-id="${m.id}" ${m.completed ? 'checked' : ''} />
                <span style="${m.completed ? 'text-decoration:line-through; color:var(--text-muted);' : ''}">${this.escapeHtml(m.title)}</span>
              </label>
              <span style="font-size:11px; color:var(--text-muted);">${m.dueDate}</span>
            </div>
          `).join('')}
        </div>

        <!-- LINKED TASKS -->
        <div class="section-divider" style="margin:20px 0;"></div>
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;">
          <h4 style="font-size:14px; font-weight:700;">Active Tasks (${projectTasks.length})</h4>
          <button class="btn btn-sm btn-secondary" id="proj-add-task-btn">+ Add Task</button>
        </div>

        <div class="project-tasks-list" style="display:flex; flex-direction:column; gap:8px;">
          ${projectTasks.map(t => `
            <div class="task-list-item" style="display:flex; align-items:center; justify-content:space-between; padding:10px 14px; background:var(--bg-card); border:1px solid var(--border-color); border-radius:8px;">
              <div>
                <div style="font-weight:600; font-size:13px;">${this.escapeHtml(t.title)}</div>
                <div style="font-size:11px; color:var(--text-muted);">Assignee: ${t.assignee?.name || 'Unassigned'} • Due: ${t.dueDate}</div>
              </div>
              <span class="badge badge-status badge-${t.status}">${t.status.toUpperCase()}</span>
            </div>
          `).join('')}
          ${projectTasks.length === 0 ? `<div style="font-size:12px; color:var(--text-muted);">No tasks linked yet.</div>` : ''}
        </div>

        <!-- DRAWER FOOTER ACTIONS -->
        <div style="display:flex; justify-content:space-between; align-items:center; margin-top:30px; padding-top:16px; border-top:1px solid var(--border-color);">
          <button class="btn btn-danger btn-sm" id="drawer-delete-proj-btn">Delete Portfolio</button>
          <div style="display:flex; gap:10px;">
            <button class="btn btn-secondary btn-sm" id="drawer-edit-proj-btn">Edit Project</button>
          </div>
        </div>
      </div>
    `;

    modal.openDrawer({
      title: p.name,
      subtitle: `${p.code} • Client: ${p.accountName}`,
      content: drawerContent,
      onOpen: (el) => {
        // Milestone toggle
        const msCheckboxes = el.querySelectorAll('.milestone-checkbox');
        msCheckboxes.forEach(cb => {
          cb.addEventListener('change', () => {
            const mId = cb.getAttribute('data-milestone-id');
            dataStore.toggleMilestone(p.id, mId);
            toast.success('Milestone Updated', 'Progress updated automatically.');
            this.render();
          });
        });

        // Add task button
        const addTaskBtn = el.querySelector('#proj-add-task-btn');
        if (addTaskBtn) {
          addTaskBtn.addEventListener('click', () => {
            modal.closeDrawer();
            window.crmApp.openNewTaskModal(p.id);
          });
        }

        // Delete project
        const delBtn = el.querySelector('#drawer-delete-proj-btn');
        if (delBtn) {
          delBtn.addEventListener('click', () => {
            modal.confirm({
              title: `Delete ${p.code}?`,
              message: 'Are you sure you want to remove this project and its milestones?',
              onConfirm: () => {
                dataStore.deleteProject(p.id);
                modal.closeDrawer();
                toast.success('Project Deleted', 'The project portfolio was deleted.');
                this.render();
              }
            });
          });
        }

        // Edit project
        const editBtn = el.querySelector('#drawer-edit-proj-btn');
        if (editBtn) {
          editBtn.addEventListener('click', () => {
            modal.closeDrawer();
            this.openEditProjectModal(p);
          });
        }
      }
    });
  }

  openNewProjectModal() {
    const accounts = dataStore.getAccounts();
    const team = dataStore.getTeamMembers();

    const formHtml = `
      <form id="new-project-form">
        <div class="form-group">
          <label class="form-label required">Project Name</label>
          <input type="text" name="name" class="input" placeholder="e.g. Distributed Core Banking Modernization" required />
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Client Account</label>
            <select name="accountId" class="input" required>
              <option value="">-- Select Client --</option>
              ${accounts.map(a => `<option value="${a.id}">${this.escapeHtml(a.name)}</option>`).join('')}
            </select>
          </div>
          <div class="form-group">
            <label class="form-label required">Project Code</label>
            <input type="text" name="code" class="input" placeholder="PRJ-ABC-01" required />
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Total Budget ($)</label>
            <input type="number" name="budget" class="input" placeholder="180000" min="0" required />
          </div>
          <div class="form-group">
            <label class="form-label">Project Lead / Manager</label>
            <select name="managerId" class="input">
              ${team.map(u => `<option value="${u.id}">${u.name} (${u.role})</option>`).join('')}
            </select>
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Start Date</label>
            <input type="date" name="startDate" class="input" required value="${new Date().toISOString().split('T')[0]}" />
          </div>
          <div class="form-group">
            <label class="form-label required">Target End Date</label>
            <input type="date" name="endDate" class="input" required value="${new Date(Date.now() + 90 * 24 * 3600 * 1000).toISOString().split('T')[0]}" />
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Scope & Description</label>
          <textarea name="description" class="input" rows="3" placeholder="Key deliverables, architecture components, and constraints..."></textarea>
        </div>
      </form>
    `;

    modal.openModal({
      title: 'Create Project Portfolio',
      content: formHtml,
      confirmText: 'Launch Project',
      onConfirm: (formData) => {
        if (!formData) return false;
        const accountId = formData.get('accountId');
        const account = accounts.find(a => a.id === accountId);
        const managerId = formData.get('managerId');
        const manager = team.find(u => u.id === managerId);

        const newPrj = {
          name: formData.get('name'),
          code: formData.get('code') || 'PRJ-' + Math.floor(100 + Math.random() * 900),
          accountId: accountId,
          accountName: account ? account.name : 'Client',
          budget: Number(formData.get('budget')) || 0,
          spent: 0,
          progress: 5,
          health: 95,
          status: 'on_track',
          startDate: formData.get('startDate'),
          endDate: formData.get('endDate'),
          managerId: managerId,
          managerName: manager ? manager.name : 'Elena Rostova',
          description: formData.get('description'),
          milestones: [
            { id: 'm-new-1', title: 'Architecture Blueprint Sign-off', dueDate: formData.get('startDate'), completed: true },
            { id: 'm-new-2', title: 'Phase 1 MVP Release', dueDate: formData.get('endDate'), completed: false }
          ],
          teamMembers: ['usr-102', 'usr-103', 'usr-105']
        };

        dataStore.saveProject(newPrj);
        toast.success('Project Launched', `"${newPrj.name}" created successfully.`);
        this.render();
        return true;
      }
    });
  }

  openEditProjectModal(project) {
    const accounts = dataStore.getAccounts();
    const team = dataStore.getTeamMembers();

    const formHtml = `
      <form id="edit-project-form">
        <div class="form-group">
          <label class="form-label required">Project Name</label>
          <input type="text" name="name" class="input" value="${this.escapeHtml(project.name)}" required />
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Status</label>
            <select name="status" class="input" required>
              <option value="on_track" ${project.status === 'on_track' ? 'selected' : ''}>On Track</option>
              <option value="at_risk" ${project.status === 'at_risk' ? 'selected' : ''}>At Risk</option>
              <option value="delayed" ${project.status === 'delayed' ? 'selected' : ''}>Delayed</option>
              <option value="completed" ${project.status === 'completed' ? 'selected' : ''}>Completed</option>
            </select>
          </div>
          <div class="form-group">
            <label class="form-label required">Progress (%)</label>
            <input type="number" name="progress" class="input" min="0" max="100" value="${project.progress}" required />
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Budget ($)</label>
            <input type="number" name="budget" class="input" value="${project.budget}" required />
          </div>
          <div class="form-group">
            <label class="form-label required">Spent ($)</label>
            <input type="number" name="spent" class="input" value="${project.spent}" required />
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Description</label>
          <textarea name="description" class="input" rows="3">${this.escapeHtml(project.description || '')}</textarea>
        </div>
      </form>
    `;

    modal.openModal({
      title: 'Edit Project',
      content: formHtml,
      confirmText: 'Save Changes',
      onConfirm: (formData) => {
        if (!formData) return false;
        const updated = {
          ...project,
          name: formData.get('name'),
          status: formData.get('status'),
          progress: Number(formData.get('progress')) || 0,
          budget: Number(formData.get('budget')) || 0,
          spent: Number(formData.get('spent')) || 0,
          description: formData.get('description')
        };
        dataStore.saveProject(updated);
        toast.success('Changes Saved', `Updated ${updated.name}`);
        this.render();
        return true;
      }
    });
  }

  escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}

  /**
 * Enterprise Project CRM - Tasks & Time Tracking View Controller
 * Features: Task Kanban Board with Drag & Drop, Eisenhower Priority Matrix,
 * List View, Subtasks Manager, and Live Time Tracking Stopwatch integration.
 */






class TasksView {
  constructor(container) {
    this.container = container;
    this.viewMode = 'kanban'; // 'kanban', 'matrix', 'table'
  }

  render() {
    const tasks = dataStore.getTasks();
    const settings = dataStore.getSettings();
    const statuses = settings.taskStatuses || [];

    const activeTimer = dataStore.getTimerState();

    let html = `
      <div class="view-header">
        <div>
          <h1 class="view-title">Task & Delivery Management</h1>
          <p class="view-subtitle">
            <strong>${tasks.length}</strong> Tasks • 
            In Progress: <strong>${tasks.filter(t => t.status === 'in_progress').length}</strong> • 
            Completed: <strong style="color:var(--color-success);">${tasks.filter(t => t.status === 'completed').length}</strong>
          </p>
        </div>
        <div class="view-header-actions">
          <div class="view-mode-toggle">
            <button class="btn btn-sm ${this.viewMode === 'kanban' ? 'btn-primary' : 'btn-secondary'}" id="tasks-toggle-kanban">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="7" height="18" rx="1"/><rect x="14" y="3" width="7" height="18" rx="1"/></svg>
              Kanban
            </button>
            <button class="btn btn-sm ${this.viewMode === 'matrix' ? 'btn-primary' : 'btn-secondary'}" id="tasks-toggle-matrix">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/></svg>
              Eisenhower Matrix
            </button>
            <button class="btn btn-sm ${this.viewMode === 'table' ? 'btn-primary' : 'btn-secondary'}" id="tasks-toggle-table">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg>
              Table
            </button>
          </div>
          <button class="btn btn-primary" id="tasks-new-task-btn">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            New Task
          </button>
        </div>
      </div>

      <!-- ACTIVE TIMER BANNER IF RUNNING -->
      ${activeTimer && activeTimer.isRunning ? `
        <div class="active-timer-banner animate-slide-in">
          <div style="display:flex; align-items:center; gap:12px;">
            <span class="timer-pulse-dot"></span>
            <div>
              <strong style="color:var(--text-primary);">Timer Running:</strong>
              <span>${this.escapeHtml(activeTimer.taskName)}</span>
            </div>
          </div>
          <div style="display:flex; align-items:center; gap:12px;">
            <div class="timer-time-display" id="tasks-live-timer-counter">${this.formatDuration(activeTimer.elapsedSeconds)}</div>
            <button class="btn btn-sm btn-danger" id="tasks-stop-timer-btn">Stop & Log</button>
          </div>
        </div>
      ` : ''}

      <div id="tasks-view-content" class="animate-fade-in"></div>
    `;

    this.container.innerHTML = html;
    this.renderContent();
    this.bindHeaderEvents();
  }

  renderContent() {
    const contentEl = this.container.querySelector('#tasks-view-content');
    if (!contentEl) return;

    if (this.viewMode === 'kanban') {
      this.renderKanban(contentEl);
    } else if (this.viewMode === 'matrix') {
      this.renderMatrix(contentEl);
    } else {
      this.renderTable(contentEl);
    }
  }

  renderKanban(container) {
    const tasks = dataStore.getTasks();
    const settings = dataStore.getSettings();
    const statuses = settings.taskStatuses || [];

    let html = `
      <div class="kanban-board" id="tasks-kanban-board">
        ${statuses.map(st => {
          const colTasks = tasks.filter(t => t.status === st.id);

          return `
            <div class="kanban-column" data-task-status="${st.id}">
              <div class="kanban-column-header">
                <div class="kanban-column-title-wrap">
                  <span class="kanban-stage-indicator" style="background:${st.color};"></span>
                  <h4 class="kanban-column-title">${this.escapeHtml(st.name)}</h4>
                  <span class="kanban-count-pill">${colTasks.length}</span>
                </div>
              </div>

              <div class="kanban-cards-container" data-task-status="${st.id}">
                ${colTasks.map(t => {
                  const completedSubtasks = (t.subtasks || []).filter(s => s.done).length;
                  const totalSubtasks = (t.subtasks || []).length;
                  const isOverdue = t.status !== 'completed' && new Date(t.dueDate) < new Date();

                  return `
                    <div class="kanban-card cursor-grab animate-scale-up" draggable="true" data-task-id="${t.id}">
                      <div class="kanban-card-header">
                        <span class="badge badge-priority badge-${t.priority}">${t.priority.toUpperCase()}</span>
                        <span class="kanban-card-date ${isOverdue ? 'date-overdue' : ''}">
                          ${isOverdue ? '⚠️ ' : ''}${t.dueDate}
                        </span>
                      </div>

                      <div class="kanban-card-title">${this.escapeHtml(t.title)}</div>
                      
                      <div class="kanban-card-account">
                        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>
                        <span>${this.escapeHtml(t.projectName)}</span>
                      </div>

                      ${totalSubtasks > 0 ? `
                        <div class="task-checklist-preview">
                          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 11 12 14 22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>
                          <span>${completedSubtasks}/${totalSubtasks} subtasks</span>
                        </div>
                      ` : ''}

                      <div class="kanban-card-footer">
                        <div class="task-time-logged">
                          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                          <span>${t.loggedHours}h / ${t.estimatedHours}h</span>
                        </div>
                        <div class="avatar-pill" title="Assignee: ${t.assignee?.name || 'Unassigned'}">
                          ${t.assignee?.initials || 'UN'}
                        </div>
                      </div>
                    </div>
                  `;
                }).join('')}

                ${colTasks.length === 0 ? `
                  <div class="kanban-empty-dropzone">Drop tasks here</div>
                ` : ''}
              </div>
            </div>
          `;
        }).join('')}
      </div>
    `;

    container.innerHTML = html;
    this.initDragAndDrop();
    this.bindCardClicks();
  }

  renderMatrix(container) {
    const tasks = dataStore.getTasks().filter(t => t.status !== 'completed');

    const q1 = tasks.filter(t => (t.priority === 'urgent' || t.priority === 'high') && this.isDueSoon(t.dueDate));
    const q2 = tasks.filter(t => (t.priority === 'urgent' || t.priority === 'high') && !this.isDueSoon(t.dueDate));
    const q3 = tasks.filter(t => (t.priority === 'medium' || t.priority === 'low') && this.isDueSoon(t.dueDate));
    const q4 = tasks.filter(t => (t.priority === 'medium' || t.priority === 'low') && !this.isDueSoon(t.dueDate));

    let html = `
      <div class="matrix-grid">
        <!-- Q1: Urgent & Important (DO FIRST) -->
        <div class="card matrix-quadrant q1-border">
          <div class="matrix-header">
            <div>
              <h3 class="matrix-title" style="color:#ef4444;">Do First (Urgent & Critical)</h3>
              <p class="matrix-subtitle">Immediate deadlines and high business impact</p>
            </div>
            <span class="badge badge-danger">${q1.length} Tasks</span>
          </div>
          <div class="matrix-tasks-list">
            ${q1.map(t => this.renderMatrixTaskItem(t)).join('')}
            ${q1.length === 0 ? '<div class="matrix-empty">No urgent critical tasks</div>' : ''}
          </div>
        </div>

        <!-- Q2: Not Urgent but Important (SCHEDULE) -->
        <div class="card matrix-quadrant q2-border">
          <div class="matrix-header">
            <div>
              <h3 class="matrix-title" style="color:#3b82f6;">Schedule (Strategic & Important)</h3>
              <p class="matrix-subtitle">Long-term architecture, roadmaps & milestones</p>
            </div>
            <span class="badge badge-info">${q2.length} Tasks</span>
          </div>
          <div class="matrix-tasks-list">
            ${q2.map(t => this.renderMatrixTaskItem(t)).join('')}
            ${q2.length === 0 ? '<div class="matrix-empty">No strategic tasks</div>' : ''}
          </div>
        </div>

        <!-- Q3: Urgent but Low Importance (DELEGATE) -->
        <div class="card matrix-quadrant q3-border">
          <div class="matrix-header">
            <div>
              <h3 class="matrix-title" style="color:#f59e0b;">Delegate (Urgent / Support)</h3>
              <p class="matrix-subtitle">Quick requests, operational inquiries & minor fixes</p>
            </div>
            <span class="badge badge-warning">${q3.length} Tasks</span>
          </div>
          <div class="matrix-tasks-list">
            ${q3.map(t => this.renderMatrixTaskItem(t)).join('')}
            ${q3.length === 0 ? '<div class="matrix-empty">No delegated tasks</div>' : ''}
          </div>
        </div>

        <!-- Q4: Not Urgent & Low Importance (DON'T DO / BACKLOG) -->
        <div class="card matrix-quadrant q4-border">
          <div class="matrix-header">
            <div>
              <h3 class="matrix-title" style="color:#64748b;">Backlog (Low Priority)</h3>
              <p class="matrix-subtitle">Nice-to-have ideas and future optimizations</p>
            </div>
            <span class="badge badge-secondary">${q4.length} Tasks</span>
          </div>
          <div class="matrix-tasks-list">
            ${q4.map(t => this.renderMatrixTaskItem(t)).join('')}
            ${q4.length === 0 ? '<div class="matrix-empty">Backlog is clean</div>' : ''}
          </div>
        </div>
      </div>
    `;

    container.innerHTML = html;
    this.bindCardClicks();
  }

  renderMatrixTaskItem(t) {
    return `
      <div class="matrix-task-card cursor-pointer" data-task-id="${t.id}">
        <div style="display:flex; justify-content:space-between; align-items:flex-start;">
          <strong style="font-size:13px; color:var(--text-primary);">${this.escapeHtml(t.title)}</strong>
          <span class="avatar-pill" style="width:22px; height:22px; font-size:10px;">${t.assignee?.initials || 'UN'}</span>
        </div>
        <div style="display:flex; justify-content:space-between; font-size:11px; color:var(--text-muted); margin-top:6px;">
          <span>${this.escapeHtml(t.projectName)}</span>
          <span>Due: ${t.dueDate}</span>
        </div>
      </div>
    `;
  }

  renderTable(container) {
    const tasks = dataStore.getTasks();

    container.innerHTML = '<div id="tasks-table-container"></div>';

    new TableGrid({
      container: '#tasks-table-container',
      data: tasks,
      pageSize: 10,
      defaultSortKey: 'dueDate',
      defaultSortAsc: true,
      columns: [
        {
          key: 'title',
          label: 'Task Title',
          sortable: true,
          render: (val, item) => `
            <div>
              <strong style="color:var(--text-primary); font-size:13px;">${this.escapeHtml(val)}</strong>
              <div style="font-size:11px; color:var(--text-muted);">${this.escapeHtml(item.projectName)}</div>
            </div>
          `
        },
        {
          key: 'priority',
          label: 'Priority',
          sortable: true,
          render: (val) => `<span class="badge badge-priority badge-${val}">${val.toUpperCase()}</span>`
        },
        {
          key: 'status',
          label: 'Status',
          sortable: true,
          render: (val) => `<span class="badge badge-status badge-${val}">${val.replace('_', ' ').toUpperCase()}</span>`
        },
        {
          key: 'dueDate',
          label: 'Due Date',
          sortable: true,
          render: (val, item) => {
            const isOverdue = item.status !== 'completed' && new Date(val) < new Date();
            return `<span style="font-weight:600; color:${isOverdue ? '#ef4444' : 'inherit'};">${val || 'TBD'}</span>`;
          }
        },
        {
          key: 'loggedHours',
          label: 'Logged / Est',
          sortable: true,
          render: (val, item) => `<span>${val}h / ${item.estimatedHours}h</span>`
        },
        {
          key: 'assignee',
          label: 'Assignee',
          sortable: true,
          render: (val) => `
            <div style="display:flex; align-items:center; gap:6px;">
              <span class="avatar-pill">${val?.initials || 'UN'}</span>
              <span>${val?.name || 'Unassigned'}</span>
            </div>
          `
        }
      ],
      onRowClick: (t) => {
        this.openTaskDrawer(t.id);
      }
    });
  }

  initDragAndDrop() {
    const cards = this.container.querySelectorAll('.kanban-card');
    const containers = this.container.querySelectorAll('.kanban-cards-container');

    cards.forEach(card => {
      card.addEventListener('dragstart', (e) => {
        card.classList.add('is-dragging');
        e.dataTransfer.setData('text/plain', card.getAttribute('data-task-id'));
        e.dataTransfer.effectAllowed = 'move';
      });

      card.addEventListener('dragend', () => {
        card.classList.remove('is-dragging');
        containers.forEach(c => c.classList.remove('drag-over'));
      });
    });

    containers.forEach(dropzone => {
      dropzone.addEventListener('dragover', (e) => {
        e.preventDefault();
        dropzone.classList.add('drag-over');
      });

      dropzone.addEventListener('dragleave', (e) => {
        if (!dropzone.contains(e.relatedTarget)) {
          dropzone.classList.remove('drag-over');
        }
      });

      dropzone.addEventListener('drop', (e) => {
        e.preventDefault();
        dropzone.classList.remove('drag-over');
        const taskId = e.dataTransfer.getData('text/plain');
        const targetStatus = dropzone.getAttribute('data-task-status');

        if (taskId && targetStatus) {
          const updated = dataStore.updateTaskStatus(taskId, targetStatus);
          if (updated) {
            toast.success('Task Status', `"${updated.title}" moved to ${targetStatus.replace('_', ' ').toUpperCase()}`);
            this.render();
          }
        }
      });
    });
  }

  bindCardClicks() {
    const cards = this.container.querySelectorAll('[data-task-id]');
    cards.forEach(card => {
      card.addEventListener('click', () => {
        const id = card.getAttribute('data-task-id');
        this.openTaskDrawer(id);
      });
    });
  }

  bindHeaderEvents() {
    const toggleKanban = this.container.querySelector('#tasks-toggle-kanban');
    const toggleMatrix = this.container.querySelector('#tasks-toggle-matrix');
    const toggleTable = this.container.querySelector('#tasks-toggle-table');
    const newTaskBtn = this.container.querySelector('#tasks-new-task-btn');
    const stopTimerBtn = this.container.querySelector('#tasks-stop-timer-btn');

    if (toggleKanban) toggleKanban.addEventListener('click', () => { this.viewMode = 'kanban'; this.render(); });
    if (toggleMatrix) toggleMatrix.addEventListener('click', () => { this.viewMode = 'matrix'; this.render(); });
    if (toggleTable) toggleTable.addEventListener('click', () => { this.viewMode = 'table'; this.render(); });
    if (newTaskBtn) newTaskBtn.addEventListener('click', () => this.openNewTaskModal());

    if (stopTimerBtn) {
      stopTimerBtn.addEventListener('click', () => {
        const logged = dataStore.stopAndLogTimer();
        toast.success('Time Logged', `Recorded ${logged.loggedHours} hours to task.`);
        this.render();
      });
    }
  }

  openTaskDrawer(taskId) {
    const task = dataStore.getTaskById(taskId);
    if (!task) return;

    const drawerContent = `
      <div class="task-drawer-container">
        <!-- TIME TRACKER BAR -->
        <div class="task-stopwatch-box">
          <div>
            <div style="font-size:11px; color:var(--text-muted); text-transform:uppercase; font-weight:700;">Live Stopwatch</div>
            <div style="font-size:18px; font-weight:700; color:var(--text-primary);">${task.loggedHours}h Logged (${task.estimatedHours}h Est.)</div>
          </div>
          <button class="btn btn-sm btn-primary" id="drawer-start-timer-btn">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polygon points="10 8 16 12 10 16 10 8"/></svg>
            Start Timer
          </button>
        </div>

        <div class="form-group-row" style="margin-top:16px;">
          <div class="form-group">
            <label class="form-label">Project Portfolio</label>
            <div class="readonly-pill">${this.escapeHtml(task.projectName)}</div>
          </div>
          <div class="form-group">
            <label class="form-label">Status</label>
            <div class="readonly-pill">${task.status.replace('_', ' ').toUpperCase()}</div>
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Priority</label>
            <div class="readonly-pill">${task.priority.toUpperCase()}</div>
          </div>
          <div class="form-group">
            <label class="form-label">Due Date</label>
            <div class="readonly-pill">${task.dueDate || 'TBD'}</div>
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Task Details</label>
          <div class="deal-notes-box">${this.escapeHtml(task.description || 'No description.')}</div>
        </div>

        <!-- SUBTASKS CHECKLIST -->
        <div class="section-divider" style="margin:20px 0;"></div>
        <h4 style="font-size:14px; font-weight:700; margin-bottom:12px;">Subtasks Checklist (${(task.subtasks || []).filter(s => s.done).length}/${(task.subtasks || []).length})</h4>
        <div class="subtasks-list" style="display:flex; flex-direction:column; gap:8px;">
          ${(task.subtasks || []).map(st => `
            <div class="subtask-row" style="display:flex; align-items:center; justify-content:space-between; padding:10px 14px; background:var(--bg-card-hover); border-radius:8px;">
              <label style="display:flex; align-items:center; gap:10px; cursor:pointer; font-size:13px; font-weight:500;">
                <input type="checkbox" class="crm-checkbox subtask-check" data-subtask-id="${st.id}" ${st.done ? 'checked' : ''} />
                <span style="${st.done ? 'text-decoration:line-through; color:var(--text-muted);' : ''}">${this.escapeHtml(st.title)}</span>
              </label>
            </div>
          `).join('')}
          ${(!task.subtasks || task.subtasks.length === 0) ? '<div style="font-size:12px; color:var(--text-muted);">No subtasks defined.</div>' : ''}
        </div>

        <!-- FOOTER ACTIONS -->
        <div style="display:flex; justify-content:space-between; align-items:center; margin-top:30px; padding-top:16px; border-top:1px solid var(--border-color);">
          <button class="btn btn-danger btn-sm" id="drawer-delete-task-btn">Delete Task</button>
          <div style="display:flex; gap:10px;">
            <button class="btn btn-secondary btn-sm" id="drawer-edit-task-btn">Edit Task</button>
          </div>
        </div>
      </div>
    `;

    modal.openDrawer({
      title: task.title,
      subtitle: `${task.projectName} • Assignee: ${task.assignee?.name || 'Unassigned'}`,
      content: drawerContent,
      onOpen: (el) => {
        // Subtask toggles
        const checks = el.querySelectorAll('.subtask-check');
        checks.forEach(cb => {
          cb.addEventListener('change', () => {
            const sId = cb.getAttribute('data-subtask-id');
            dataStore.toggleSubtask(task.id, sId);
            toast.success('Subtask Updated', 'Checklist state updated.');
            this.render();
          });
        });

        // Start stopwatch timer
        const timerBtn = el.querySelector('#drawer-start-timer-btn');
        if (timerBtn) {
          timerBtn.addEventListener('click', () => {
            dataStore.startTimer(task.id, task.title);
            modal.closeDrawer();
            toast.info('⏱️ Stopwatch Started', `Tracking time on "${task.title}".`);
            this.render();
          });
        }

        // Delete task
        const delBtn = el.querySelector('#drawer-delete-task-btn');
        if (delBtn) {
          delBtn.addEventListener('click', () => {
            modal.confirm({
              title: `Delete Task "${task.title}"?`,
              message: 'Are you sure you want to remove this task?',
              onConfirm: () => {
                dataStore.deleteTask(task.id);
                modal.closeDrawer();
                toast.success('Task Deleted', 'The task was removed.');
                this.render();
              }
            });
          });
        }

        // Edit task
        const editBtn = el.querySelector('#drawer-edit-task-btn');
        if (editBtn) {
          editBtn.addEventListener('click', () => {
            modal.closeDrawer();
            this.openEditTaskModal(task);
          });
        }
      }
    });
  }

  openNewTaskModal(preselectedProjectId = null) {
    const projects = dataStore.getProjects();
    const team = dataStore.getTeamMembers();

    const formHtml = `
      <form id="new-task-form">
        <div class="form-group">
          <label class="form-label required">Task Title</label>
          <input type="text" name="title" class="input" placeholder="e.g. Implement Kafka Failover Recovery Routine" required />
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Project Portfolio</label>
            <select name="projectId" class="input" required>
              ${projects.map(p => `<option value="${p.id}" ${p.id === preselectedProjectId ? 'selected' : ''}>${this.escapeHtml(p.code)}: ${this.escapeHtml(p.name)}</option>`).join('')}
            </select>
          </div>
          <div class="form-group">
            <label class="form-label required">Priority</label>
            <select name="priority" class="input" required>
              <option value="medium">Medium</option>
              <option value="high">High</option>
              <option value="urgent">Urgent</option>
              <option value="low">Low</option>
            </select>
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Assignee</label>
            <select name="assigneeId" class="input">
              ${team.map(u => `<option value="${u.id}">${u.name} (${u.role})</option>`).join('')}
            </select>
          </div>
          <div class="form-group">
            <label class="form-label required">Due Date</label>
            <input type="date" name="dueDate" class="input" required value="${new Date(Date.now() + 7 * 24 * 3600 * 1000).toISOString().split('T')[0]}" />
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Estimated Hours</label>
            <input type="number" name="estimatedHours" class="input" value="8" min="1" />
          </div>
          <div class="form-group">
            <label class="form-label">Initial Status</label>
            <select name="status" class="input">
              <option value="todo">To Do</option>
              <option value="in_progress">In Progress</option>
              <option value="backlog">Backlog</option>
              <option value="review">Review</option>
              <option value="completed">Completed</option>
            </select>
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Description & Acceptance Criteria</label>
          <textarea name="description" class="input" rows="3" placeholder="Technical specifications and testing requirements..."></textarea>
        </div>
      </form>
    `;

    modal.openModal({
      title: 'Create Delivery Task',
      content: formHtml,
      confirmText: 'Create Task',
      onConfirm: (formData) => {
        if (!formData) return false;
        const prjId = formData.get('projectId');
        const prj = projects.find(p => p.id === prjId);
        const assigneeId = formData.get('assigneeId');
        const user = team.find(u => u.id === assigneeId);

        const newTask = {
          title: formData.get('title'),
          projectId: prjId,
          projectName: prj ? prj.name : 'Project',
          status: formData.get('status') || 'todo',
          priority: formData.get('priority') || 'medium',
          assigneeId: assigneeId,
          assignee: user ? { name: user.name, initials: user.initials, avatar: user.avatar } : { name: 'Devon Wright', initials: 'DW' },
          dueDate: formData.get('dueDate'),
          estimatedHours: Number(formData.get('estimatedHours')) || 8,
          loggedHours: 0,
          description: formData.get('description'),
          subtasks: [
            { id: 'st-new-1', title: 'Technical Architecture Review', done: false },
            { id: 'st-new-2', title: 'Unit Tests and Code Coverage Sign-off', done: false }
          ],
          tags: ['Feature', 'Sprint 1']
        };

        dataStore.saveTask(newTask);
        toast.success('Task Created', `"${newTask.title}" added to board.`);
        this.render();
        return true;
      }
    });
  }

  openEditTaskModal(task) {
    const projects = dataStore.getProjects();
    const team = dataStore.getTeamMembers();

    const formHtml = `
      <form id="edit-task-form">
        <div class="form-group">
          <label class="form-label required">Task Title</label>
          <input type="text" name="title" class="input" value="${this.escapeHtml(task.title)}" required />
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Status</label>
            <select name="status" class="input" required>
              <option value="backlog" ${task.status === 'backlog' ? 'selected' : ''}>Backlog</option>
              <option value="todo" ${task.status === 'todo' ? 'selected' : ''}>To Do</option>
              <option value="in_progress" ${task.status === 'in_progress' ? 'selected' : ''}>In Progress</option>
              <option value="review" ${task.status === 'review' ? 'selected' : ''}>Review</option>
              <option value="completed" ${task.status === 'completed' ? 'selected' : ''}>Completed</option>
            </select>
          </div>
          <div class="form-group">
            <label class="form-label required">Priority</label>
            <select name="priority" class="input" required>
              <option value="low" ${task.priority === 'low' ? 'selected' : ''}>Low</option>
              <option value="medium" ${task.priority === 'medium' ? 'selected' : ''}>Medium</option>
              <option value="high" ${task.priority === 'high' ? 'selected' : ''}>High</option>
              <option value="urgent" ${task.priority === 'urgent' ? 'selected' : ''}>Urgent</option>
            </select>
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Assignee</label>
            <select name="assigneeId" class="input">
              ${team.map(u => `<option value="${u.id}" ${u.id === task.assigneeId ? 'selected' : ''}>${u.name}</option>`).join('')}
            </select>
          </div>
          <div class="form-group">
            <label class="form-label required">Due Date</label>
            <input type="date" name="dueDate" class="input" value="${task.dueDate || ''}" required />
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Estimated Hours</label>
            <input type="number" name="estimatedHours" class="input" value="${task.estimatedHours}" min="0" />
          </div>
          <div class="form-group">
            <label class="form-label">Logged Hours</label>
            <input type="number" name="loggedHours" class="input" value="${task.loggedHours}" step="0.5" min="0" />
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Description</label>
          <textarea name="description" class="input" rows="3">${this.escapeHtml(task.description || '')}</textarea>
        </div>
      </form>
    `;

    modal.openModal({
      title: 'Edit Task',
      content: formHtml,
      confirmText: 'Save Changes',
      onConfirm: (formData) => {
        if (!formData) return false;
        const assigneeId = formData.get('assigneeId');
        const user = team.find(u => u.id === assigneeId);

        const updated = {
          ...task,
          title: formData.get('title'),
          status: formData.get('status'),
          priority: formData.get('priority'),
          dueDate: formData.get('dueDate'),
          estimatedHours: Number(formData.get('estimatedHours')) || 0,
          loggedHours: Number(formData.get('loggedHours')) || 0,
          description: formData.get('description'),
          assigneeId: assigneeId,
          assignee: user ? { name: user.name, initials: user.initials, avatar: user.avatar } : task.assignee
        };

        dataStore.saveTask(updated);
        toast.success('Changes Saved', `Updated "${updated.title}"`);
        this.render();
        return true;
      }
    });
  }

  isDueSoon(dateStr) {
    if (!dateStr) return false;
    const diff = (new Date(dateStr).getTime() - Date.now()) / (1000 * 3600 * 24);
    return diff <= 5; // due within 5 days
  }

  formatDuration(seconds) {
    const hrs = Math.floor(seconds / 3600);
    const mins = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return `${hrs.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  }

  escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}

  /**
 * Enterprise Project CRM - Clients & Contacts 360° Directory View Controller
 * Features: Accounts Directory, Contacts Address Book, Tier Filters,
 * Health Scoring, and 360° Comprehensive Client Drawer.
 */






class ClientsView {
  constructor(container) {
    this.container = container;
    this.tabMode = 'accounts'; // 'accounts' or 'contacts'
  }

  render() {
    const accounts = dataStore.getAccounts();
    const contacts = dataStore.getContacts();

    let html = `
      <div class="view-header">
        <div>
          <h1 class="view-title">Client & Contact Directory (CRM 360°)</h1>
          <p class="view-subtitle">
            <strong>${accounts.length}</strong> Accounts • 
            <strong>${contacts.length}</strong> Key Contacts • 
            Enterprise Accounts: <strong>${accounts.filter(a => a.tier === 'Enterprise').length}</strong>
          </p>
        </div>
        <div class="view-header-actions">
          <div class="view-mode-toggle">
            <button class="btn btn-sm ${this.tabMode === 'accounts' ? 'btn-primary' : 'btn-secondary'}" id="clients-tab-accounts">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"/><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"/></svg>
              Companies (${accounts.length})
            </button>
            <button class="btn btn-sm ${this.tabMode === 'contacts' ? 'btn-primary' : 'btn-secondary'}" id="clients-tab-contacts">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
              Contacts (${contacts.length})
            </button>
          </div>
          <button class="btn btn-primary" id="clients-new-btn">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            ${this.tabMode === 'accounts' ? 'New Account' : 'New Contact'}
          </button>
        </div>
      </div>

      <div id="clients-view-content" class="animate-fade-in"></div>
    `;

    this.container.innerHTML = html;
    this.renderContent();
    this.bindHeaderEvents();
  }

  renderContent() {
    const contentEl = this.container.querySelector('#clients-view-content');
    if (!contentEl) return;

    if (this.tabMode === 'accounts') {
      this.renderAccounts(contentEl);
    } else {
      this.renderContacts(contentEl);
    }
  }

  renderAccounts(container) {
    const accounts = dataStore.getAccounts();

    let html = `
      <div class="grid grid-3" style="gap: 20px;">
        ${accounts.map(acc => {
          const summary = dataStore.getAccount360(acc.id);
          const healthColor = acc.healthScore >= 90 ? '#10b981' : (acc.healthScore >= 75 ? '#f59e0b' : '#ef4444');

          return `
            <div class="card account-card cursor-pointer animate-scale-up" data-account-id="${acc.id}">
              <div class="account-card-header">
                <div class="account-logo-avatar" style="background:${acc.logoBg || '#6366f1'};">
                  ${acc.name.slice(0, 2).toUpperCase()}
                </div>
                <div>
                  <span class="badge badge-tier">${acc.tier}</span>
                </div>
              </div>

              <h3 class="account-card-title">${this.escapeHtml(acc.name)}</h3>
              <p class="account-card-industry">${this.escapeHtml(acc.industry)}</p>

              <div class="account-stats-row">
                <div>
                  <div class="meta-label">Health Score</div>
                  <div style="font-weight:700; color:${healthColor}; font-size:15px;">${acc.healthScore}%</div>
                </div>
                <div>
                  <div class="meta-label">Est. Revenue</div>
                  <div style="font-weight:700; color:var(--text-primary); font-size:14px;">${acc.annualRevenue}</div>
                </div>
                <div>
                  <div class="meta-label">Deals Pipeline</div>
                  <div style="font-weight:700; color:var(--color-primary); font-size:14px;">$${summary.stats.totalDealValue.toLocaleString()}</div>
                </div>
              </div>

              <div class="account-tags-wrap">
                ${(acc.tags || []).map(t => `<span class="tag-pill">${this.escapeHtml(t)}</span>`).join('')}
              </div>

              <div class="account-card-footer">
                <div style="font-size:11px; color:var(--text-muted);">
                  ${summary.projects.length} Projects • ${summary.contacts.length} Contacts
                </div>
                <button class="btn btn-sm btn-ghost view-360-btn" data-account-id="${acc.id}">360° View →</button>
              </div>
            </div>
          `;
        }).join('')}
      </div>
    `;

    container.innerHTML = html;
    this.bindAccountClicks();
  }

  renderContacts(container) {
    const contacts = dataStore.getContacts();

    container.innerHTML = '<div id="contacts-table-container"></div>';

    new TableGrid({
      container: '#contacts-table-container',
      data: contacts,
      pageSize: 10,
      defaultSortKey: 'name',
      defaultSortAsc: true,
      columns: [
        {
          key: 'name',
          label: 'Contact Name',
          sortable: true,
          render: (val, item) => `
            <div style="display:flex; align-items:center; gap:10px;">
              <span class="avatar-pill" style="width:32px; height:32px; font-size:12px;">${item.initials || 'CT'}</span>
              <div>
                <strong style="color:var(--text-primary); font-size:13px;">${this.escapeHtml(val)}</strong>
                ${item.isPrimary ? `<span class="badge badge-success" style="font-size:9px; margin-left:4px;">PRIMARY</span>` : ''}
                <div style="font-size:11px; color:var(--text-muted);">${this.escapeHtml(item.title || '')}</div>
              </div>
            </div>
          `
        },
        {
          key: 'accountName',
          label: 'Company',
          sortable: true,
          render: (val) => `<span style="font-weight:600;">${this.escapeHtml(val)}</span>`
        },
        {
          key: 'email',
          label: 'Email',
          sortable: true,
          render: (val) => `<a href="mailto:${val}" class="link-styled" onclick="event.stopPropagation()">${this.escapeHtml(val)}</a>`
        },
        {
          key: 'phone',
          label: 'Phone',
          sortable: true,
          render: (val) => `<span style="font-family:monospace; font-size:12px;">${val || '—'}</span>`
        },
        {
          key: 'department',
          label: 'Department',
          sortable: true,
          render: (val) => val || 'General'
        },
        {
          key: 'lastContacted',
          label: 'Last Contact',
          sortable: true,
          render: (val) => val || 'Recently'
        }
      ],
      onRowClick: (cnt) => {
        this.openContactModal(cnt);
      }
    });
  }

  bindAccountClicks() {
    const cards = this.container.querySelectorAll('[data-account-id]');
    cards.forEach(card => {
      card.addEventListener('click', () => {
        const id = card.getAttribute('data-account-id');
        this.openAccount360Drawer(id);
      });
    });
  }

  bindHeaderEvents() {
    const tabAccounts = this.container.querySelector('#clients-tab-accounts');
    const tabContacts = this.container.querySelector('#clients-tab-contacts');
    const newBtn = this.container.querySelector('#clients-new-btn');

    if (tabAccounts) {
      tabAccounts.addEventListener('click', () => {
        this.tabMode = 'accounts';
        this.render();
      });
    }

    if (tabContacts) {
      tabContacts.addEventListener('click', () => {
        this.tabMode = 'contacts';
        this.render();
      });
    }

    if (newBtn) {
      newBtn.addEventListener('click', () => {
        if (this.tabMode === 'accounts') {
          this.openNewAccountModal();
        } else {
          this.openNewContactModal();
        }
      });
    }
  }

  openAccount360Drawer(accountId) {
    const summary = dataStore.getAccount360(accountId);
    if (!summary) return;

    const { account, contacts, deals, projects, invoices, tickets, stats } = summary;
    const settings = dataStore.getSettings();
    const currency = settings.currencySymbol || '$';

    const drawerContent = `
      <div class="client-360-container">
        <!-- 360 OVERVIEW STRIP -->
        <div class="grid grid-4" style="margin-bottom: 20px; gap:10px;">
          <div class="card stat-box" style="padding:12px;">
            <div class="stat-box-label">Pipeline Value</div>
            <div class="stat-box-value">${currency}${stats.totalDealValue.toLocaleString()}</div>
          </div>
          <div class="card stat-box" style="padding:12px;">
            <div class="stat-box-label">Total Invoiced</div>
            <div class="stat-box-value">${currency}${stats.totalInvoiced.toLocaleString()}</div>
          </div>
          <div class="card stat-box" style="padding:12px;">
            <div class="stat-box-label">Paid Revenue</div>
            <div class="stat-box-value" style="color:var(--color-success);">${currency}${stats.totalPaid.toLocaleString()}</div>
          </div>
          <div class="card stat-box" style="padding:12px;">
            <div class="stat-box-label">Health Score</div>
            <div class="stat-box-value" style="color:${account.healthScore >= 85 ? '#10b981' : '#f59e0b'};">${account.healthScore}%</div>
          </div>
        </div>

        <!-- ACCOUNT INFO -->
        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Industry & Tier</label>
            <div class="readonly-pill">${this.escapeHtml(account.industry)} • ${account.tier}</div>
          </div>
          <div class="form-group">
            <label class="form-label">Website & Phone</label>
            <div class="readonly-pill">${account.phone || '—'}</div>
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Account Notes</label>
          <div class="deal-notes-box">${this.escapeHtml(account.notes || 'No notes added.')}</div>
        </div>

        <!-- ASSOCIATED CONTACTS -->
        <div class="section-divider" style="margin:20px 0;"></div>
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
          <h4 style="font-size:14px; font-weight:700;">Contacts (${contacts.length})</h4>
        </div>
        <div style="display:flex; flex-direction:column; gap:8px;">
          ${contacts.map(c => `
            <div style="display:flex; align-items:center; justify-content:space-between; padding:10px 14px; background:var(--bg-card-hover); border-radius:8px;">
              <div style="display:flex; align-items:center; gap:10px;">
                <span class="avatar-pill">${c.initials}</span>
                <div>
                  <div style="font-weight:600; font-size:13px;">${this.escapeHtml(c.name)} ${c.isPrimary ? '<span class="badge badge-success" style="font-size:8px;">PRIMARY</span>' : ''}</div>
                  <div style="font-size:11px; color:var(--text-muted);">${c.title} • ${c.email}</div>
                </div>
              </div>
            </div>
          `).join('')}
        </div>

        <!-- ACTIVE PROJECTS & DEALS -->
        <div class="section-divider" style="margin:20px 0;"></div>
        <h4 style="font-size:14px; font-weight:700; margin-bottom:10px;">Active Deals & Projects</h4>
        <div style="display:flex; flex-direction:column; gap:8px;">
          ${deals.map(d => `
            <div style="display:flex; align-items:center; justify-content:space-between; padding:10px 14px; background:var(--bg-card); border:1px solid var(--border-color); border-radius:8px;">
              <div>
                <div style="font-weight:600; font-size:13px;">${this.escapeHtml(d.title)}</div>
                <div style="font-size:11px; color:var(--text-muted);">Stage: ${d.stage} • Close: ${d.expectedCloseDate}</div>
              </div>
              <strong style="color:var(--color-primary);">${currency}${d.amount.toLocaleString()}</strong>
            </div>
          `).join('')}
        </div>

        <!-- INVOICES & PAYMENTS -->
        <div class="section-divider" style="margin:20px 0;"></div>
        <h4 style="font-size:14px; font-weight:700; margin-bottom:10px;">Invoices & Billing History</h4>
        <div style="display:flex; flex-direction:column; gap:8px;">
          ${invoices.map(inv => `
            <div style="display:flex; align-items:center; justify-content:space-between; padding:10px 14px; background:var(--bg-card); border:1px solid var(--border-color); border-radius:8px;">
              <div>
                <div style="font-weight:600; font-size:13px;">${inv.invoiceNumber}</div>
                <div style="font-size:11px; color:var(--text-muted);">Due: ${inv.dueDate}</div>
              </div>
              <div style="text-align:right;">
                <div style="font-weight:700;">${currency}${inv.total.toLocaleString()}</div>
                <span class="badge badge-status badge-${inv.status}">${inv.status.toUpperCase()}</span>
              </div>
            </div>
          `).join('')}
        </div>

        <!-- DRAWER FOOTER ACTIONS -->
        <div style="display:flex; justify-content:space-between; align-items:center; margin-top:30px; padding-top:16px; border-top:1px solid var(--border-color);">
          <button class="btn btn-danger btn-sm" id="drawer-delete-acc-btn">Delete Account</button>
          <button class="btn btn-secondary btn-sm" id="drawer-edit-acc-btn">Edit Account</button>
        </div>
      </div>
    `;

    modal.openDrawer({
      title: account.name,
      subtitle: `${account.industry} • Tier: ${account.tier}`,
      content: drawerContent,
      onOpen: (el) => {
        const delBtn = el.querySelector('#drawer-delete-acc-btn');
        if (delBtn) {
          delBtn.addEventListener('click', () => {
            modal.confirm({
              title: `Delete "${account.name}"?`,
              message: 'Are you sure? This will remove the account from your CRM.',
              onConfirm: () => {
                dataStore.deleteAccount(account.id);
                modal.closeDrawer();
                toast.success('Account Deleted', 'Removed company record.');
                this.render();
              }
            });
          });
        }

        const editBtn = el.querySelector('#drawer-edit-acc-btn');
        if (editBtn) {
          editBtn.addEventListener('click', () => {
            modal.closeDrawer();
            this.openEditAccountModal(account);
          });
        }
      }
    });
  }

  openNewAccountModal() {
    const formHtml = `
      <form id="new-account-form">
        <div class="form-group">
          <label class="form-label required">Company / Account Name</label>
          <input type="text" name="name" class="input" placeholder="e.g. Apex BioSciences Inc." required />
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Industry</label>
            <input type="text" name="industry" class="input" placeholder="e.g. Fintech / AI SaaS" required />
          </div>
          <div class="form-group">
            <label class="form-label required">Account Tier</label>
            <select name="tier" class="input" required>
              <option value="Enterprise">Enterprise</option>
              <option value="Mid-Market">Mid-Market</option>
              <option value="Growth">Growth</option>
              <option value="Startup">Startup</option>
            </select>
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Phone</label>
            <input type="text" name="phone" class="input" placeholder="+1 (555) 019-2831" />
          </div>
          <div class="form-group">
            <label class="form-label">Annual Revenue</label>
            <input type="text" name="annualRevenue" class="input" placeholder="$15.0M" />
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Office Address</label>
          <input type="text" name="address" class="input" placeholder="100 Market St, San Francisco, CA" />
        </div>

        <div class="form-group">
          <label class="form-label">Strategic Overview & Notes</label>
          <textarea name="notes" class="input" rows="3" placeholder="Key business focus and relationship history..."></textarea>
        </div>
      </form>
    `;

    modal.openModal({
      title: 'Add New Client Account',
      content: formHtml,
      confirmText: 'Save Account',
      onConfirm: (formData) => {
        if (!formData) return false;
        const newAcc = {
          name: formData.get('name'),
          industry: formData.get('industry'),
          tier: formData.get('tier'),
          phone: formData.get('phone'),
          annualRevenue: formData.get('annualRevenue') || '$5.0M',
          address: formData.get('address'),
          notes: formData.get('notes'),
          healthScore: 90,
          status: 'Active',
          tags: ['New Client', formData.get('tier')]
        };
        dataStore.saveAccount(newAcc);
        toast.success('Account Created', `Added "${newAcc.name}"`);
        this.render();
        return true;
      }
    });
  }

  openEditAccountModal(account) {
    const formHtml = `
      <form id="edit-account-form">
        <div class="form-group">
          <label class="form-label required">Company Name</label>
          <input type="text" name="name" class="input" value="${this.escapeHtml(account.name)}" required />
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Industry</label>
            <input type="text" name="industry" class="input" value="${this.escapeHtml(account.industry)}" required />
          </div>
          <div class="form-group">
            <label class="form-label required">Account Tier</label>
            <select name="tier" class="input" required>
              <option value="Enterprise" ${account.tier === 'Enterprise' ? 'selected' : ''}>Enterprise</option>
              <option value="Mid-Market" ${account.tier === 'Mid-Market' ? 'selected' : ''}>Mid-Market</option>
              <option value="Growth" ${account.tier === 'Growth' ? 'selected' : ''}>Growth</option>
              <option value="Startup" ${account.tier === 'Startup' ? 'selected' : ''}>Startup</option>
            </select>
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Phone</label>
            <input type="text" name="phone" class="input" value="${account.phone || ''}" />
          </div>
          <div class="form-group">
            <label class="form-label">Health Score (0-100%)</label>
            <input type="number" name="healthScore" class="input" min="0" max="100" value="${account.healthScore || 85}" />
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Notes</label>
          <textarea name="notes" class="input" rows="3">${this.escapeHtml(account.notes || '')}</textarea>
        </div>
      </form>
    `;

    modal.openModal({
      title: 'Edit Client Account',
      content: formHtml,
      confirmText: 'Save Changes',
      onConfirm: (formData) => {
        if (!formData) return false;
        const updated = {
          ...account,
          name: formData.get('name'),
          industry: formData.get('industry'),
          tier: formData.get('tier'),
          phone: formData.get('phone'),
          healthScore: Number(formData.get('healthScore')) || 85,
          notes: formData.get('notes')
        };
        dataStore.saveAccount(updated);
        toast.success('Changes Saved', `Updated "${updated.name}"`);
        this.render();
        return true;
      }
    });
  }

  openNewContactModal() {
    const accounts = dataStore.getAccounts();

    const formHtml = `
      <form id="new-contact-form">
        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">First Name</label>
            <input type="text" name="firstName" class="input" placeholder="Sarah" required />
          </div>
          <div class="form-group">
            <label class="form-label required">Last Name</label>
            <input type="text" name="lastName" class="input" placeholder="Connor" required />
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Company / Account</label>
            <select name="accountId" class="input" required>
              ${accounts.map(a => `<option value="${a.id}">${this.escapeHtml(a.name)}</option>`).join('')}
            </select>
          </div>
          <div class="form-group">
            <label class="form-label required">Professional Title</label>
            <input type="text" name="title" class="input" placeholder="VP of Infrastructure" required />
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Email</label>
            <input type="email" name="email" class="input" placeholder="s.connor@example.com" required />
          </div>
          <div class="form-group">
            <label class="form-label">Phone</label>
            <input type="text" name="phone" class="input" placeholder="+1 (415) 555-9011" />
          </div>
        </div>

        <div class="form-group">
          <label style="display:flex; align-items:center; gap:8px; cursor:pointer;">
            <input type="checkbox" name="isPrimary" class="crm-checkbox" />
            <span style="font-size:13px; font-weight:600;">Set as Primary Decision Maker for this Account</span>
          </label>
        </div>
      </form>
    `;

    modal.openModal({
      title: 'Add New Contact',
      content: formHtml,
      confirmText: 'Save Contact',
      onConfirm: (formData) => {
        if (!formData) return false;
        const accId = formData.get('accountId');
        const acc = accounts.find(a => a.id === accId);

        const newCnt = {
          firstName: formData.get('firstName'),
          lastName: formData.get('lastName'),
          accountId: accId,
          accountName: acc ? acc.name : 'Company',
          title: formData.get('title'),
          email: formData.get('email'),
          phone: formData.get('phone'),
          isPrimary: formData.get('isPrimary') === 'on',
          status: 'Active'
        };

        dataStore.saveContact(newCnt);
        toast.success('Contact Added', `Created ${newCnt.firstName} ${newCnt.lastName}`);
        this.render();
        return true;
      }
    });
  }

  openContactModal(cnt) {
    const modalContent = `
      <div style="display:flex; align-items:center; gap:16px; margin-bottom:20px;">
        <span class="avatar-pill" style="width:54px; height:54px; font-size:20px;">${cnt.initials}</span>
        <div>
          <h3 style="margin:0; font-size:18px; color:var(--text-primary);">${this.escapeHtml(cnt.name)}</h3>
          <div style="font-size:13px; color:var(--text-muted);">${this.escapeHtml(cnt.title || '')} @ <strong>${this.escapeHtml(cnt.accountName)}</strong></div>
        </div>
      </div>

      <div class="form-group-row">
        <div class="form-group">
          <label class="form-label">Email</label>
          <div class="readonly-pill"><a href="mailto:${cnt.email}" class="link-styled">${cnt.email}</a></div>
        </div>
        <div class="form-group">
          <label class="form-label">Phone</label>
          <div class="readonly-pill">${cnt.phone || '—'}</div>
        </div>
      </div>

      <div class="form-group">
        <label class="form-label">Notes</label>
        <div class="deal-notes-box">${this.escapeHtml(cnt.notes || 'No notes available.')}</div>
      </div>
    `;

    modal.openModal({
      title: 'Contact Profile',
      content: modalContent,
      showFooter: true,
      confirmText: 'Done',
      cancelText: 'Delete Contact',
      onConfirm: () => true
    });
  }

  escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}

  /**
 * Enterprise Project CRM - Invoices & Billing Operations View Controller
 * Features: Dynamic Invoice Builder, Tax/Discount Calculations,
 * Payment Status Tracking, Multi-Currency Selector, and Printable Invoice View.
 */






class InvoicesView {
  constructor(container) {
    this.container = container;
  }

  render() {
    const invoices = dataStore.getInvoices();
    const settings = dataStore.getSettings();
    const currency = settings.currencySymbol || '$';

    const totalPaid = invoices.filter(i => i.status === 'paid').reduce((sum, i) => sum + (Number(i.paidAmount) || 0), 0);
    const totalPending = invoices.filter(i => i.status === 'pending').reduce((sum, i) => sum + (Number(i.total) || 0), 0);
    const totalOverdue = invoices.filter(i => i.status === 'overdue').reduce((sum, i) => sum + (Number(i.total) || 0), 0);

    let html = `
      <div class="view-header">
        <div>
          <h1 class="view-title">Invoicing & Financial Operations</h1>
          <p class="view-subtitle">Billing milestones, receivables tracking, and payment reconciliations</p>
        </div>
        <div class="view-header-actions">
          <button class="btn btn-secondary" id="inv-export-csv-btn">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
            Export CSV
          </button>
          <button class="btn btn-primary" id="inv-create-new-btn">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            Create Invoice
          </button>
        </div>
      </div>

      <!-- STATS SUMMARY -->
      <div class="grid grid-3" style="margin-bottom: 24px;">
        <div class="card stat-box" style="border-left: 4px solid #10b981;">
          <div class="stat-box-label">Total Revenue Collected</div>
          <div class="stat-box-value" style="color:#10b981;">${currency}${totalPaid.toLocaleString()}</div>
          <div style="font-size:11px; color:var(--text-muted); margin-top:4px;">${invoices.filter(i => i.status === 'paid').length} Paid Invoices</div>
        </div>

        <div class="card stat-box" style="border-left: 4px solid #f59e0b;">
          <div class="stat-box-label">Pending Receivables (Net-30)</div>
          <div class="stat-box-value" style="color:#f59e0b;">${currency}${totalPending.toLocaleString()}</div>
          <div style="font-size:11px; color:var(--text-muted); margin-top:4px;">${invoices.filter(i => i.status === 'pending').length} Invoices Awaiting Payment</div>
        </div>

        <div class="card stat-box" style="border-left: 4px solid #ef4444;">
          <div class="stat-box-label">Overdue & Collections</div>
          <div class="stat-box-value" style="color:#ef4444;">${currency}${totalOverdue.toLocaleString()}</div>
          <div style="font-size:11px; color:var(--text-muted); margin-top:4px;">${invoices.filter(i => i.status === 'overdue').length} Invoices Requiring Follow-up</div>
        </div>
      </div>

      <div class="card">
        <div class="card-body no-padding" id="invoices-table-container"></div>
      </div>
    `;

    this.container.innerHTML = html;
    this.renderTable();
    this.bindHeaderEvents();
  }

  renderTable() {
    const invoices = dataStore.getInvoices();
    const settings = dataStore.getSettings();
    const currency = settings.currencySymbol || '$';

    new TableGrid({
      container: '#invoices-table-container',
      data: invoices,
      pageSize: 10,
      defaultSortKey: 'dueDate',
      defaultSortAsc: false,
      columns: [
        {
          key: 'invoiceNumber',
          label: 'Invoice #',
          sortable: true,
          render: (val) => `<strong style="color:var(--color-primary);">${val}</strong>`
        },
        {
          key: 'accountName',
          label: 'Client Account',
          sortable: true,
          render: (val) => `<span style="font-weight:600;">${this.escapeHtml(val)}</span>`
        },
        {
          key: 'issueDate',
          label: 'Issued Date',
          sortable: true,
          render: (val) => val || '—'
        },
        {
          key: 'dueDate',
          label: 'Due Date',
          sortable: true,
          render: (val, item) => {
            const isOverdue = item.status === 'overdue';
            return `<span style="font-weight:600; color:${isOverdue ? '#ef4444' : 'inherit'};">${val || '—'}</span>`;
          }
        },
        {
          key: 'status',
          label: 'Status',
          sortable: true,
          render: (val) => `<span class="badge badge-status badge-${val}">${val.toUpperCase()}</span>`
        },
        {
          key: 'total',
          label: 'Total Amount',
          sortable: true,
          render: (val) => `<strong style="font-size:13px;">${currency}${Number(val).toLocaleString()}</strong>`
        },
        {
          key: 'id',
          label: 'Actions',
          sortable: false,
          render: (val, item) => `
            <div style="display:flex; gap:8px;" onclick="event.stopPropagation()">
              <button class="btn btn-sm btn-secondary btn-print-inv" data-inv-id="${val}" title="Print / View Invoice">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>
                View
              </button>
              ${item.status !== 'paid' ? `
                <button class="btn btn-sm btn-success btn-mark-paid" data-inv-id="${val}">
                  Mark Paid
                </button>
              ` : ''}
            </div>
          `
        }
      ],
      onRowClick: (inv) => {
        this.openPrintableInvoiceModal(inv.id);
      }
    });

    this.bindTableActionButtons();
  }

  bindTableActionButtons() {
    const printBtns = this.container.querySelectorAll('.btn-print-inv');
    printBtns.forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = btn.getAttribute('data-inv-id');
        this.openPrintableInvoiceModal(id);
      });
    });

    const paidBtns = this.container.querySelectorAll('.btn-mark-paid');
    paidBtns.forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = btn.getAttribute('data-inv-id');
        dataStore.markInvoicePaid(id);
        toast.success('Payment Received', 'Invoice marked as paid and logged to ledger.');
        this.render();
      });
    });
  }

  bindHeaderEvents() {
    const createBtn = this.container.querySelector('#inv-create-new-btn');
    const exportBtn = this.container.querySelector('#inv-export-csv-btn');

    if (createBtn) {
      createBtn.addEventListener('click', () => {
        this.openCreateInvoiceModal();
      });
    }

    if (exportBtn) {
      exportBtn.addEventListener('click', () => {
        const csv = dataStore.exportCollectionCSV('invoices');
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = 'crm-invoices-export.csv';
        link.click();
        toast.info('CSV Exported', 'Downloaded invoices ledger.');
      });
    }
  }

  openCreateInvoiceModal() {
    const accounts = dataStore.getAccounts();
    const projects = dataStore.getProjects();
    const settings = dataStore.getSettings();

    const formHtml = `
      <form id="new-invoice-form">
        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Client Account</label>
            <select name="accountId" id="inv-form-account" class="input" required>
              <option value="">-- Select Client --</option>
              ${accounts.map(a => `<option value="${a.id}">${this.escapeHtml(a.name)}</option>`).join('')}
            </select>
          </div>
          <div class="form-group">
            <label class="form-label">Linked Project</label>
            <select name="projectId" class="input">
              <option value="">-- General Retainer / None --</option>
              ${projects.map(p => `<option value="${p.id}">${this.escapeHtml(p.code)}: ${this.escapeHtml(p.name)}</option>`).join('')}
            </select>
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Issue Date</label>
            <input type="date" name="issueDate" class="input" required value="${new Date().toISOString().split('T')[0]}" />
          </div>
          <div class="form-group">
            <label class="form-label required">Due Date</label>
            <input type="date" name="dueDate" class="input" required value="${new Date(Date.now() + 30 * 24 * 3600 * 1000).toISOString().split('T')[0]}" />
          </div>
        </div>

        <!-- LINE ITEMS SECTION -->
        <div class="section-divider" style="margin:20px 0;"></div>
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
          <label class="form-label" style="margin:0; font-weight:700;">Line Items & Deliverables</label>
          <button type="button" class="btn btn-sm btn-secondary" id="inv-add-line-btn">+ Add Item</button>
        </div>

        <div id="inv-line-items-container" style="display:flex; flex-direction:column; gap:10px;">
          <div class="inv-line-row" style="display:flex; gap:8px; align-items:center;">
            <input type="text" name="item_desc[]" class="input" placeholder="Description of service / milestone" style="flex:3;" required value="Enterprise Architecture & Milestone Delivery" />
            <input type="number" name="item_qty[]" class="input item-qty" placeholder="Qty" style="width:70px;" min="1" value="1" required />
            <input type="number" name="item_rate[]" class="input item-rate" placeholder="Rate ($)" style="width:110px;" min="0" value="25000" required />
            <button type="button" class="btn btn-sm btn-ghost btn-remove-line" style="color:#ef4444;">&times;</button>
          </div>
        </div>

        <!-- TOTALS & TAX -->
        <div class="section-divider" style="margin:20px 0;"></div>
        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Tax Rate (%)</label>
            <input type="number" name="taxRate" id="inv-tax-rate" class="input" value="${settings.taxRate || 8.5}" step="0.1" min="0" />
          </div>
          <div class="form-group">
            <label class="form-label">Discount ($)</label>
            <input type="number" name="discount" id="inv-discount" class="input" value="0" min="0" />
          </div>
        </div>

        <div class="form-group">
          <label class="form-label">Payment Terms & Notes</label>
          <textarea name="notes" class="input" rows="2">Net-30. Please remit wire payment to Chase Treasury wire account.</textarea>
        </div>
      </form>
    `;

    modal.openModal({
      title: 'Generate New Invoice',
      content: formHtml,
      width: '720px',
      confirmText: 'Generate Invoice',
      onOpen: (body) => {
        const addBtn = body.querySelector('#inv-add-line-btn');
        const container = body.querySelector('#inv-line-items-container');

        addBtn.addEventListener('click', () => {
          const row = document.createElement('div');
          row.className = 'inv-line-row animate-slide-in';
          row.style.cssText = 'display:flex; gap:8px; align-items:center;';
          row.innerHTML = `
            <input type="text" name="item_desc[]" class="input" placeholder="Service / Consulting" style="flex:3;" required />
            <input type="number" name="item_qty[]" class="input item-qty" placeholder="Qty" style="width:70px;" min="1" value="1" required />
            <input type="number" name="item_rate[]" class="input item-rate" placeholder="Rate ($)" style="width:110px;" min="0" value="150" required />
            <button type="button" class="btn btn-sm btn-ghost btn-remove-line" style="color:#ef4444;">&times;</button>
          `;
          container.appendChild(row);
          row.querySelector('.btn-remove-line').addEventListener('click', () => row.remove());
        });

        body.querySelectorAll('.btn-remove-line').forEach(btn => {
          btn.addEventListener('click', (e) => e.target.closest('.inv-line-row').remove());
        });
      },
      onConfirm: (formData, body) => {
        if (!formData) return false;
        const accountId = formData.get('accountId');
        const account = accounts.find(a => a.id === accountId);

        const descs = Array.from(body.querySelectorAll('input[name="item_desc[]"]')).map(el => el.value);
        const qtys = Array.from(body.querySelectorAll('input[name="item_qty[]"]')).map(el => Number(el.value) || 1);
        const rates = Array.from(body.querySelectorAll('input[name="item_rate[]"]')).map(el => Number(el.value) || 0);

        const items = descs.map((desc, i) => ({
          description: desc,
          quantity: qtys[i],
          unitPrice: rates[i],
          amount: qtys[i] * rates[i]
        }));

        const newInvoice = {
          accountId: accountId,
          accountName: account ? account.name : 'Client',
          projectId: formData.get('projectId'),
          issueDate: formData.get('issueDate'),
          dueDate: formData.get('dueDate'),
          status: 'pending',
          currency: settings.defaultCurrency || 'USD',
          taxRate: Number(formData.get('taxRate')) || 0,
          discount: Number(formData.get('discount')) || 0,
          items: items,
          notes: formData.get('notes')
        };

        dataStore.saveInvoice(newInvoice);
        toast.success('Invoice Generated', 'New invoice created and added to records.');
        this.render();
        return true;
      }
    });
  }

  openPrintableInvoiceModal(invoiceId) {
    const inv = dataStore.getInvoiceById(invoiceId);
    if (!inv) return;

    const settings = dataStore.getSettings();
    const currency = settings.currencySymbol || '$';

    const printHtml = `
      <div class="printable-invoice-sheet" id="printable-invoice-content">
        <!-- INVOICE HEADER -->
        <div style="display:flex; justify-content:space-between; align-items:flex-start; border-bottom:2px solid var(--border-color); padding-bottom:20px; margin-bottom:20px;">
          <div>
            <h2 style="margin:0; font-size:22px; font-weight:800; color:var(--color-primary);">${this.escapeHtml(settings.companyName)}</h2>
            <div style="font-size:12px; color:var(--text-muted); margin-top:4px;">${this.escapeHtml(settings.companyAddress)}</div>
            <div style="font-size:12px; color:var(--text-muted);">${this.escapeHtml(settings.companyEmail)} • ${this.escapeHtml(settings.companyPhone)}</div>
          </div>
          <div style="text-align:right;">
            <h1 style="margin:0; font-size:26px; font-weight:900; color:var(--text-primary); letter-spacing:1px;">INVOICE</h1>
            <div style="font-size:14px; font-weight:700; color:var(--color-primary); margin-top:4px;">${inv.invoiceNumber}</div>
            <span class="badge badge-status badge-${inv.status}" style="margin-top:6px;">${inv.status.toUpperCase()}</span>
          </div>
        </div>

        <!-- CLIENT & DATES -->
        <div class="grid grid-2" style="margin-bottom:24px; gap:20px;">
          <div>
            <div style="font-size:11px; text-transform:uppercase; font-weight:700; color:var(--text-muted);">Billed To:</div>
            <h3 style="margin:4px 0 0 0; font-size:16px; color:var(--text-primary);">${this.escapeHtml(inv.accountName)}</h3>
          </div>
          <div style="text-align:right;">
            <div><span style="color:var(--text-muted); font-size:12px;">Issue Date:</span> <strong>${inv.issueDate}</strong></div>
            <div><span style="color:var(--text-muted); font-size:12px;">Payment Due:</span> <strong>${inv.dueDate}</strong></div>
          </div>
        </div>

        <!-- ITEMS TABLE -->
        <table class="table" style="width:100%; margin-bottom:20px;">
          <thead>
            <tr style="border-bottom:2px solid var(--border-color);">
              <th style="text-align:left;">Description</th>
              <th style="text-align:center; width:60px;">Qty</th>
              <th style="text-align:right; width:120px;">Unit Price</th>
              <th style="text-align:right; width:130px;">Amount</th>
            </tr>
          </thead>
          <tbody>
            ${(inv.items || []).map(item => `
              <tr style="border-bottom:1px solid var(--border-color);">
                <td style="font-weight:500;">${this.escapeHtml(item.description)}</td>
                <td style="text-align:center;">${item.quantity}</td>
                <td style="text-align:right;">${currency}${Number(item.unitPrice).toLocaleString()}</td>
                <td style="text-align:right; font-weight:700;">${currency}${Number(item.amount || (item.quantity * item.unitPrice)).toLocaleString()}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>

        <!-- TOTALS BREAKDOWN -->
        <div style="display:flex; justify-content:flex-end; margin-bottom:30px;">
          <div style="width:280px; display:flex; flex-direction:column; gap:8px;">
            <div style="display:flex; justify-content:space-between; font-size:13px;">
              <span style="color:var(--text-muted);">Subtotal:</span>
              <strong>${currency}${Number(inv.subtotal).toLocaleString()}</strong>
            </div>
            ${inv.taxAmount > 0 ? `
              <div style="display:flex; justify-content:space-between; font-size:13px;">
                <span style="color:var(--text-muted);">Tax (${inv.taxRate}%):</span>
                <span>${currency}${Number(inv.taxAmount).toLocaleString()}</span>
              </div>
            ` : ''}
            ${inv.discount > 0 ? `
              <div style="display:flex; justify-content:space-between; font-size:13px; color:#10b981;">
                <span>Discount:</span>
                <span>-${currency}${Number(inv.discount).toLocaleString()}</span>
              </div>
            ` : ''}
            <div style="display:flex; justify-content:space-between; font-size:16px; font-weight:800; border-top:2px solid var(--border-color); padding-top:8px; color:var(--text-primary);">
              <span>Total Due:</span>
              <span style="color:var(--color-primary);">${currency}${Number(inv.total).toLocaleString()}</span>
            </div>
          </div>
        </div>

        <!-- NOTES -->
        <div style="padding:12px 16px; background:var(--bg-card-hover); border-radius:8px; font-size:12px; color:var(--text-secondary);">
          <strong>Payment Terms:</strong> ${this.escapeHtml(inv.notes || 'Net-30 wire transfer terms.')}
        </div>
      </div>
    `;

    modal.openModal({
      title: `Invoice ${inv.invoiceNumber}`,
      content: printHtml,
      width: '800px',
      confirmText: 'Print / Save PDF',
      confirmClass: 'btn-primary',
      cancelText: 'Close',
      onConfirm: () => {
        window.print();
        return false;
      }
    });
  }

  escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}

  /**
 * Enterprise Project CRM - Customer Support & SLA Helpdesk View Controller
 * Features: Split-Pane Ticket Desk, Live SLA Countdown Timers,
 * Client Messages vs Internal Private Notes, and Response Thread Composer.
 */





class TicketsView {
  constructor(container) {
    this.container = container;
    this.selectedTicketId = null;
  }

  render() {
    const tickets = dataStore.getTickets();
    if (!this.selectedTicketId && tickets.length > 0) {
      this.selectedTicketId = tickets[0].id;
    }

    const openCount = tickets.filter(t => t.status === 'open' || t.status === 'in_progress').length;
    const urgentCount = tickets.filter(t => t.priority === 'urgent' && t.status !== 'resolved').length;

    let html = `
      <div class="view-header">
        <div>
          <h1 class="view-title">Support Desk & SLA Manager</h1>
          <p class="view-subtitle">
            <strong>${tickets.length}</strong> Total Tickets • 
            <strong>${openCount}</strong> Open / In Progress • 
            <strong style="color:var(--color-danger);">${urgentCount} Urgent SLA Escalations</strong>
          </p>
        </div>
        <div class="view-header-actions">
          <button class="btn btn-primary" id="tkt-new-btn">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            Open Ticket
          </button>
        </div>
      </div>

      <!-- SPLIT VIEW DESK -->
      <div class="ticket-desk-layout">
        <!-- LEFT PANE: TICKET QUEUE -->
        <div class="card ticket-queue-pane">
          <div class="ticket-queue-header">
            <h3 style="font-size:14px; font-weight:700; margin:0;">Active Queue</h3>
            <span class="badge badge-info">${tickets.length} Tickets</span>
          </div>

          <div class="ticket-queue-list">
            ${tickets.map(t => {
              const isSelected = t.id === this.selectedTicketId;
              const isUrgent = t.priority === 'urgent' && t.status !== 'resolved';

              return `
                <div class="ticket-queue-item cursor-pointer ${isSelected ? 'ticket-selected' : ''}" data-tkt-id="${t.id}">
                  <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;">
                    <span class="ticket-id-tag">${t.ticketNumber}</span>
                    <span class="badge badge-priority badge-${t.priority}">${t.priority.toUpperCase()}</span>
                  </div>
                  <div class="ticket-item-subject">${this.escapeHtml(t.subject)}</div>
                  <div style="display:flex; justify-content:space-between; align-items:center; font-size:11px; color:var(--text-muted); margin-top:6px;">
                    <span>${this.escapeHtml(t.accountName)}</span>
                    <span class="badge badge-status badge-${t.status}">${t.status.toUpperCase()}</span>
                  </div>
                </div>
              `;
            }).join('')}
          </div>
        </div>

        <!-- RIGHT PANE: THREAD & COMPOSER -->
        <div class="card ticket-thread-pane" id="ticket-detail-container">
          <!-- Populated dynamically by renderSelectedTicket() -->
        </div>
      </div>
    `;

    this.container.innerHTML = html;
    this.renderSelectedTicket();
    this.bindEvents();
  }

  renderSelectedTicket() {
    const threadContainer = this.container.querySelector('#ticket-detail-container');
    if (!threadContainer) return;

    const ticket = dataStore.getTicketById(this.selectedTicketId);
    if (!ticket) {
      threadContainer.innerHTML = '<div class="chart-empty">Select a ticket from the queue</div>';
      return;
    }

    let html = `
      <div class="ticket-thread-header">
        <div style="flex:1;">
          <div style="display:flex; align-items:center; gap:8px; margin-bottom:6px;">
            <span class="ticket-id-tag" style="font-size:13px;">${ticket.ticketNumber}</span>
            <span class="badge badge-priority badge-${ticket.priority}">${ticket.priority.toUpperCase()}</span>
            <span class="badge badge-status badge-${ticket.status}">${ticket.status.replace('_', ' ').toUpperCase()}</span>
          </div>
          <h2 class="ticket-thread-title">${this.escapeHtml(ticket.subject)}</h2>
          <div style="font-size:12px; color:var(--text-muted); margin-top:4px;">
            <strong>${this.escapeHtml(ticket.contactName || 'Client')}</strong> (${this.escapeHtml(ticket.contactEmail || '')}) • 
            ${this.escapeHtml(ticket.accountName)} • 
            Assigned to <strong>${ticket.assignedUser?.name || 'Unassigned'}</strong>
          </div>
        </div>

        <div style="display:flex; gap:8px; align-items:center;">
          ${ticket.status !== 'resolved' ? `
            <button class="btn btn-sm btn-success" id="tkt-resolve-btn">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>
              Resolve
            </button>
          ` : `
            <button class="btn btn-sm btn-secondary" id="tkt-reopen-btn">Reopen</button>
          `}
        </div>
      </div>

      <!-- MESSAGES THREAD -->
      <div class="ticket-messages-scroll" id="ticket-messages-scroll">
        ${(ticket.messages || []).map(msg => {
          const isClient = msg.senderType === 'client';
          const isInternal = msg.senderType === 'internal_note';

          return `
            <div class="ticket-message-block ${isInternal ? 'msg-internal-note' : (isClient ? 'msg-client' : 'msg-agent')}">
              <div class="msg-header">
                <div style="display:flex; align-items:center; gap:8px;">
                  <strong>${this.escapeHtml(msg.sender)}</strong>
                  ${isInternal ? `<span class="badge badge-warning" style="font-size:9px;">INTERNAL NOTE</span>` : ''}
                </div>
                <span class="msg-timestamp">${this.formatDate(msg.timestamp)}</span>
              </div>
              <div class="msg-body">${this.escapeHtml(msg.content)}</div>
            </div>
          `;
        }).join('')}
      </div>

      <!-- REPLY COMPOSER -->
      <div class="ticket-reply-box">
        <div class="composer-type-toggle">
          <label style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:600; cursor:pointer;">
            <input type="radio" name="replyType" value="agent" checked /> Public Reply to Client
          </label>
          <label style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:600; cursor:pointer; color:#f59e0b;">
            <input type="radio" name="replyType" value="internal_note" /> Private Internal Team Note
          </label>
        </div>

        <textarea class="input ticket-composer-input" id="ticket-reply-text" rows="3" placeholder="Type your response or internal note..."></textarea>
        
        <div style="display:flex; justify-content:space-between; align-items:center; margin-top:8px;">
          <div style="font-size:11px; color:var(--text-muted);">Supports instant multi-agent synchronization</div>
          <button class="btn btn-primary btn-sm" id="ticket-send-reply-btn">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>
            Send Reply
          </button>
        </div>
      </div>
    `;

    threadContainer.innerHTML = html;
    this.scrollThreadToBottom();
    this.bindThreadEvents(ticket);
  }

  scrollThreadToBottom() {
    const scrollBox = this.container.querySelector('#ticket-messages-scroll');
    if (scrollBox) {
      scrollBox.scrollTop = scrollBox.scrollHeight;
    }
  }

  bindEvents() {
    // Ticket queue selection clicks
    const items = this.container.querySelectorAll('.ticket-queue-item');
    items.forEach(it => {
      it.addEventListener('click', () => {
        this.selectedTicketId = it.getAttribute('data-tkt-id');
        this.render();
      });
    });

    const newBtn = this.container.querySelector('#tkt-new-btn');
    if (newBtn) {
      newBtn.addEventListener('click', () => {
        this.openNewTicketModal();
      });
    }
  }

  bindThreadEvents(ticket) {
    const sendBtn = this.container.querySelector('#ticket-send-reply-btn');
    const replyInput = this.container.querySelector('#ticket-reply-text');
    const resolveBtn = this.container.querySelector('#tkt-resolve-btn');
    const reopenBtn = this.container.querySelector('#tkt-reopen-btn');

    if (sendBtn && replyInput) {
      sendBtn.addEventListener('click', () => {
        const text = replyInput.value.trim();
        if (!text) return;

        const replyTypeRadio = this.container.querySelector('input[name="replyType"]:checked');
        const replyType = replyTypeRadio ? replyTypeRadio.value : 'agent';

        const newMsg = {
          sender: replyType === 'internal_note' ? 'Alexander Sterling (Note)' : 'Alexander Sterling (Customer Success)',
          senderType: replyType,
          content: text
        };

        dataStore.addTicketMessage(ticket.id, newMsg);
        toast.success('Message Dispatched', replyType === 'internal_note' ? 'Internal note added.' : 'Reply sent to client.');
        this.renderSelectedTicket();
      });
    }

    if (resolveBtn) {
      resolveBtn.addEventListener('click', () => {
        ticket.status = 'resolved';
        dataStore.saveTicket(ticket);
        toast.success('Ticket Resolved', `${ticket.ticketNumber} marked as resolved.`);
        this.render();
      });
    }

    if (reopenBtn) {
      reopenBtn.addEventListener('click', () => {
        ticket.status = 'open';
        dataStore.saveTicket(ticket);
        toast.info('Ticket Reopened', `${ticket.ticketNumber} reopened.`);
        this.render();
      });
    }
  }

  openNewTicketModal() {
    const accounts = dataStore.getAccounts();
    const team = dataStore.getTeamMembers();

    const formHtml = `
      <form id="new-ticket-form">
        <div class="form-group">
          <label class="form-label required">Subject / Issue Title</label>
          <input type="text" name="subject" class="input" placeholder="e.g. Latency spike on endpoint /v2/tx/batch" required />
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label required">Client Account</label>
            <select name="accountId" class="input" required>
              ${accounts.map(a => `<option value="${a.id}">${this.escapeHtml(a.name)}</option>`).join('')}
            </select>
          </div>
          <div class="form-group">
            <label class="form-label required">Priority & SLA Tier</label>
            <select name="priority" class="input" required>
              <option value="urgent">Urgent (4h SLA)</option>
              <option value="high">High (8h SLA)</option>
              <option value="medium" selected>Medium (24h SLA)</option>
              <option value="low">Low (48h SLA)</option>
            </select>
          </div>
        </div>

        <div class="form-group-row">
          <div class="form-group">
            <label class="form-label">Category</label>
            <select name="category" class="input">
              <option value="Bug / Outage">Bug / Outage</option>
              <option value="Technical Inquiry">Technical Inquiry</option>
              <option value="Feature Request">Feature Request</option>
              <option value="Billing & Accounting">Billing & Accounting</option>
              <option value="Compliance & Legal">Compliance & Legal</option>
            </select>
          </div>
          <div class="form-group">
            <label class="form-label">Assigned Specialist</label>
            <select name="assignedTo" class="input">
              ${team.map(u => `<option value="${u.id}">${u.name} (${u.role})</option>`).join('')}
            </select>
          </div>
        </div>

        <div class="form-group">
          <label class="form-label required">Initial Client Message</label>
          <textarea name="initialMessage" class="input" rows="4" placeholder="Detailed reproduction steps, logs, or error descriptions..." required></textarea>
        </div>
      </form>
    `;

    modal.openModal({
      title: 'Open Support Ticket',
      content: formHtml,
      confirmText: 'Submit Ticket',
      onConfirm: (formData) => {
        if (!formData) return false;
        const accId = formData.get('accountId');
        const acc = accounts.find(a => a.id === accId);
        const assignedToId = formData.get('assignedTo');
        const user = team.find(u => u.id === assignedToId);

        const newTkt = {
          subject: formData.get('subject'),
          accountId: accId,
          accountName: acc ? acc.name : 'Client',
          priority: formData.get('priority'),
          category: formData.get('category'),
          status: 'open',
          assignedTo: assignedToId,
          assignedUser: user ? { name: user.name, initials: user.initials } : { name: 'Maya Patel', initials: 'MP' },
          messages: [
            {
              id: 'msg-init',
              sender: 'Client Support Portal',
              senderType: 'client',
              timestamp: new Date().toISOString(),
              content: formData.get('initialMessage')
            }
          ]
        };

        const saved = dataStore.saveTicket(newTkt);
        this.selectedTicketId = saved.id;
        toast.success('Ticket Opened', `Created ${saved.ticketNumber}`);
        this.render();
        return true;
      }
    });
  }

  formatDate(isoStr) {
    if (!isoStr) return '';
    const d = new Date(isoStr);
    return d.toLocaleString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  }

  escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}

  /**
 * Enterprise Project CRM - Contracts & Legal Document Management View Controller
 * Features: Executed / Pending SOWs, MSAs, DPAs, E-Signature Status, and Contract Value Aggregations.
 */






class ContractsView {
  constructor(container) {
    this.container = container;
  }

  render() {
    const contracts = dataStore.data.contracts || [];
    const settings = dataStore.getSettings();
    const currency = settings.currencySymbol || '$';

    const totalValue = contracts.reduce((sum, c) => sum + (Number(c.value) || 0), 0);
    const executedCount = contracts.filter(c => c.status === 'Executed').length;

    let html = `
      <div class="view-header">
        <div>
          <h1 class="view-title">Contract & Legal Repository</h1>
          <p class="view-subtitle">
            <strong>${contracts.length}</strong> Total Agreements • 
            Active Portfolio Value: <strong>${currency}${totalValue.toLocaleString()}</strong> • 
            Executed & Signed: <strong style="color:var(--color-success);">${executedCount}</strong>
          </p>
        </div>
        <div class="view-header-actions">
          <button class="btn btn-primary" id="ctr-new-btn">
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            Draft Agreement
          </button>
        </div>
      </div>

      <div class="card">
        <div class="card-body no-padding" id="contracts-table-container"></div>
      </div>
    `;

    this.container.innerHTML = html;
    this.renderTable();
    this.bindHeaderEvents();
  }

  renderTable() {
    const contracts = dataStore.data.contracts || [];
    const settings = dataStore.getSettings();
    const currency = settings.currencySymbol || '$';

    new TableGrid({
      container: '#contracts-table-container',
      data: contracts,
      pageSize: 10,
      defaultSortKey: 'value',
      defaultSortAsc: false,
      columns: [
        {
          key: 'title',
          label: 'Agreement Title',
          sortable: true,
          render: (val, item) => `
            <div>
              <strong style="color:var(--text-primary); font-size:13px;">${this.escapeHtml(val)}</strong>
              <div style="font-size:11px; color:var(--text-muted);">${item.contractNumber} • Type: ${item.type}</div>
            </div>
          `
        },
        {
          key: 'accountName',
          label: 'Client Account',
          sortable: true,
          render: (val) => `<span style="font-weight:600;">${this.escapeHtml(val)}</span>`
        },
        {
          key: 'status',
          label: 'Signature Status',
          sortable: true,
          render: (val) => `<span class="badge badge-status badge-${val === 'Executed' ? 'paid' : (val === 'Pending Signature' ? 'pending' : 'delayed')}">${val.toUpperCase()}</span>`
        },
        {
          key: 'value',
          label: 'Contract Value',
          sortable: true,
          render: (val) => `<strong>${currency}${Number(val).toLocaleString()}</strong>`
        },
        {
          key: 'endDate',
          label: 'Term Expiration',
          sortable: true,
          render: (val) => val || 'Perpetual'
        }
      ],
      onRowClick: (ctr) => {
        this.openContractModal(ctr);
      }
    });
  }

  bindHeaderEvents() {
    const newBtn = this.container.querySelector('#ctr-new-btn');
    if (newBtn) {
      newBtn.addEventListener('click', () => {
        toast.info('Draft Contract', 'Opened contract drafting template.');
      });
    }
  }

  openContractModal(ctr) {
    const settings = dataStore.getSettings();
    const currency = settings.currencySymbol || '$';

    const content = `
      <div class="form-group-row">
        <div class="form-group">
          <label class="form-label">Contract Number</label>
          <div class="readonly-pill">${ctr.contractNumber}</div>
        </div>
        <div class="form-group">
          <label class="form-label">Status</label>
          <div class="readonly-pill">${ctr.status}</div>
        </div>
      </div>

      <div class="form-group-row">
        <div class="form-group">
          <label class="form-label">Client Account</label>
          <div class="readonly-pill">${this.escapeHtml(ctr.accountName)}</div>
        </div>
        <div class="form-group">
          <label class="form-label">Contract Value</label>
          <div class="readonly-pill">${currency}${Number(ctr.value).toLocaleString()}</div>
        </div>
      </div>

      <div class="form-group-row">
        <div class="form-group">
          <label class="form-label">Start Date</label>
          <div class="readonly-pill">${ctr.startDate}</div>
        </div>
        <div class="form-group">
          <label class="form-label">Expiration Date</label>
          <div class="readonly-pill">${ctr.endDate}</div>
        </div>
      </div>
    `;

    modal.openModal({
      title: ctr.title,
      content,
      confirmText: 'Done',
      cancelText: 'Close',
      onConfirm: () => true
    });
  }

  escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}

